    def _get_comprehensive_geophysical_constraints(self, regional_setting: str) -> Dict:
        """Generate comprehensive geophysical constraints based on regional tectonic setting."""
        try:
            base_constraints = {
                'spatial_bounds': {
                    'x_range': (-100000, 100000),
                    'y_range': (-100000, 100000),
                    'depth_range': (-50000, -50)
                },
                'volume_change_bounds': (1e2, 1e10),
                'fault_constraints': {},
                'distributed_constraints': {},
                'default_constraints': {}
            }
            
            # Regional modifications based on tectonic setting
            if regional_setting == 'subduction_zone':
                base_constraints['spatial_bounds']['depth_range'] = (-200000, -100)  # Deeper sources
                base_constraints['fault_constraints'] = {
                    'length_range': (1000, 2000000),  # Very large megathrust faults
                    'width_range': (5000, 300000),    # Wide subduction interface
                    'dip_range': (10, 45),             # Shallow dipping megathrusts
                    'slip_range': (0.01, 200)         # Large coseismic slip
                }
            elif regional_setting == 'extensional':
                base_constraints['fault_constraints'] = {
                    'dip_range': (45, 90),             # Steep normal faults
                    'rake_range': (-120, -60),         # Normal faulting rake
                    'length_range': (500, 100000),    # Moderate fault lengths
                    'slip_range': (0.001, 20)         # Moderate slip
                }
            elif regional_setting == 'transform':
                base_constraints['fault_constraints'] = {
                    'dip_range': (70, 90),             # Steep strike-slip faults
                    'rake_range': (-30, 30),           # Strike-slip rake range
                    'length_range': (5000, 1500000),  # Long transform faults
                    'slip_range': (0.01, 100)         # Large strike-slip events
                }
            elif regional_setting == 'volcanic':
                base_constraints['volume_change_bounds'] = (1e3, 1e12)  # Large magma chambers
                base_constraints['spatial_bounds']['depth_range'] = (-30000, -500)  # Shallow magma
            
            return base_constraints
            
        except Exception as e:
            logging.error(f"Failed to generate geophysical constraints: {e}")
            return {
                'spatial_bounds': {'x_range': (-50000, 50000), 'y_range': (-50000, 50000), 'depth_range': (-20000, -100)},
                'volume_change_bounds': (1e3, 1e9),
                'fault_constraints': {},
                'distributed_constraints': {},
                'default_constraints': {}
            }
    
    def _apply_regional_constraint_modifications(self, parameter_bounds: List, 
                                               parameter_names: List[str], regional_setting: str) -> List:
        """Apply regional tectonic setting modifications to parameter bounds."""
        try:
            modified_bounds = parameter_bounds.copy()
            
            # Apply setting-specific modifications
            for i, param_name in enumerate(parameter_names):
                if param_name == 'depth' and regional_setting == 'subduction_zone':
                    # Extend depth range for subduction zones
                    modified_bounds[i] = (100, 100000)  # Very deep sources possible
                elif param_name == 'length' and regional_setting == 'transform':
                    # Extend length range for transform faults
                    modified_bounds[i] = (10000, 2000000)  # Very long transform systems
                elif param_name in ['x', 'y'] and regional_setting == 'continental':
                    # Standard continental bounds
                    modified_bounds[i] = (-200000, 200000)
            
            return modified_bounds
            
        except Exception as e:
            logging.error(f"Regional constraint modification failed: {e}")
            return parameter_bounds
    
    def _generate_constraint_validators(self, parameter_names: List[str], 
                                      parameter_bounds: List, source_type: str) -> Dict:
        """Generate constraint validation functions for parameters."""
        try:
            validators = {}
            
            for i, (param_name, bounds) in enumerate(zip(parameter_names, parameter_bounds)):
                min_val, max_val = bounds
                
                def create_validator(name, min_bound, max_bound):
                    def validator(value):
                        if not isinstance(value, (int, float)):
                            return False, f"{name} must be numeric"
                        if value < min_bound or value > max_bound:
                            return False, f"{name} ({value}) outside bounds [{min_bound}, {max_bound}]"
                        return True, "Valid"
                    return validator
                
                validators[param_name] = create_validator(param_name, min_val, max_val)
            
            # Add cross-parameter validators for fault geometry
            if source_type == 'finite_fault':
                def fault_geometry_validator(params_dict):
                    length = params_dict.get('length', 0)
                    width = params_dict.get('width', 0)
                    
                    if length > 0 and width > 0:
                        aspect_ratio = length / width
                        if aspect_ratio > 20.0 or aspect_ratio < 0.1:
                            return False, f"Unrealistic fault aspect ratio: {aspect_ratio:.2f}"
                    
                    return True, "Valid geometry"
                
                validators['fault_geometry'] = fault_geometry_validator
            
            return validators
            
        except Exception as e:
            logging.error(f"Failed to generate constraint validators: {e}")
            return {}
    
    def _get_scaling_relationships(self, source_type: str) -> Dict:
        """Get empirical scaling relationships for source parameters."""
        try:
            relationships = {}
            
            if source_type == 'finite_fault':
                # Wells & Coppersmith (1994) scaling relationships
                relationships = {
                    'magnitude_length': lambda M: 10**(M - 5.0),  # Length from magnitude
                    'magnitude_width': lambda M: 10**(M - 4.0),   # Width from magnitude  
                    'magnitude_area': lambda M: 10**(M - 4.0),    # Area from magnitude
                    'length_width': lambda L: min(L/3.0, 20000), # Width from length
                    'slip_area': lambda A: A**(1/3) * 1e-4,       # Slip from area
                    'stress_drop_range': (0.1e6, 100e6),         # Typical stress drop range (Pa)
                }
            elif source_type == 'point_source':
                relationships = {
                    'volume_magnitude': lambda V: np.log10(V) - 3.0,  # Rough volume-magnitude
                    'depth_attenuation': lambda d: max(0.1, 1.0/(d/1000 + 1)), # Depth effects
                }
            
            return relationships
            
        except Exception as e:
            logging.error(f"Failed to get scaling relationships: {e}")
            return {}
    
