    def _apply_adaptive_mesh_refinement(self, observation_points: np.ndarray) -> Tuple[np.ndarray, Dict]:
        """Apply adaptive mesh refinement for enhanced spatial resolution."""
        try:
            refinement_info = {
                'refinement_applied': True,
                'original_points': len(observation_points),
                'refinement_method': 'gradient_based'
            }
            
            # Compute displacement gradients to identify areas needing refinement
            base_displacements = self._compute_analytical_displacements(observation_points)
            
            # Compute spatial gradients using finite differences
            gradients = self._compute_spatial_gradients(observation_points, base_displacements)
            
            # Identify high-gradient regions
            gradient_magnitudes = np.linalg.norm(gradients, axis=(1, 2))
            gradient_threshold = np.percentile(gradient_magnitudes, 75)  # Top 25%
            
            refinement_mask = gradient_magnitudes > gradient_threshold
            high_gradient_points = observation_points[refinement_mask]
            
            # Add additional points around high-gradient regions
            refined_additional = []
            refinement_scale = self.parameters.get('refinement_scale', 500.0)  # meters
            
            for point in high_gradient_points:
                # Add points in a small neighborhood
                for dx in [-1, 0, 1]:
                    for dy in [-1, 0, 1]:
                        if dx == 0 and dy == 0:
                            continue
                        new_point = point + np.array([dx * refinement_scale, 
                                                     dy * refinement_scale, 0])
                        refined_additional.append(new_point)
            
            if refined_additional:
                refined_additional = np.array(refined_additional)
                refined_points = np.vstack([observation_points, refined_additional])
            else:
                refined_points = observation_points
            
            # Remove duplicate points
            refined_points = self._remove_duplicate_points(refined_points)
            
            refinement_info.update({
                'refined_points': len(refined_points),
                'points_added': len(refined_points) - len(observation_points),
                'refinement_threshold': gradient_threshold,
                'high_gradient_regions': np.sum(refinement_mask)
            })
            
            return refined_points, refinement_info
            
        except Exception as e:
            logging.error(f"Adaptive mesh refinement failed: {e}")
            return observation_points, {'refinement_applied': False, 'error': str(e)}
    
    def _is_gpu_available(self) -> bool:
        """Check if GPU acceleration is available."""
        try:
            # Try to import GPU libraries
            try:
                import cupy
                return cupy.cuda.is_available()
            except ImportError:
                pass
            
            try:
                import pyopencl
                # Check if OpenCL platforms are available
                platforms = pyopencl.get_platforms()
                return len(platforms) > 0
            except ImportError:
                pass
            
            # Check for other GPU frameworks
            try:
                import torch
                return torch.cuda.is_available()
            except ImportError:
                pass
            
            return False
        except Exception:
            return False
    
    def _compute_greens_functions_gpu(self, observation_points: np.ndarray, 
                                     model_params: Dict) -> np.ndarray:
        """Compute Green's functions using GPU acceleration."""
        try:
            # Try CuPy first (NVIDIA CUDA)
            try:
                import cupy as cp
                
                # Transfer data to GPU
                points_gpu = cp.asarray(observation_points)
                n_points = points_gpu.shape[0]
                n_params = len(model_params['parameter_names'])
                
                # Initialize Green's matrix on GPU
                greens_matrix_gpu = cp.zeros((3 * n_points, n_params))
                
                # Compute Green's functions in parallel on GPU
                for p_idx in range(n_params):
                    # Create unit perturbation for parameter p_idx
                    param_perturbation = self._create_parameter_perturbation(
                        p_idx, model_params)
                    
                    # Compute displacement for this parameter
                    displacement_gpu = self._compute_displacement_gpu(
                        points_gpu, param_perturbation)
                    
                    # Store in Green's matrix
                    greens_matrix_gpu[:, p_idx] = displacement_gpu.flatten()
                
                # Transfer result back to CPU
                return cp.asnumpy(greens_matrix_gpu)
                
            except ImportError:
                # Fall back to OpenCL
                return self._compute_greens_functions_opencl(observation_points, model_params)
                
        except Exception as e:
            logging.error(f"GPU Green's functions computation failed: {e}")
            return self._compute_greens_functions_parallel(observation_points, model_params)
    
    def _compute_greens_functions_parallel(self, observation_points: np.ndarray, 
                                          model_params: Dict) -> np.ndarray:
        """Compute Green's functions using parallel CPU processing."""
        try:
            from concurrent.futures import ProcessPoolExecutor, as_completed
            import multiprocessing
            
            n_points = observation_points.shape[0]
            n_params = len(model_params['parameter_names'])
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Determine number of worker processes
            n_workers = min(multiprocessing.cpu_count(), n_params, 8)  # Limit to 8 processes
            
            # Prepare parameter perturbations
            parameter_tasks = []
            for p_idx in range(n_params):
                param_perturbation = self._create_parameter_perturbation(p_idx, model_params)
                parameter_tasks.append((observation_points, param_perturbation, p_idx))
            
            # Parallel computation
            with ProcessPoolExecutor(max_workers=n_workers) as executor:
                # Submit tasks
                future_to_param = {
                    executor.submit(self._compute_single_greens_column, task): task[2]
                    for task in parameter_tasks
                }
                
                # Collect results
                for future in as_completed(future_to_param):
                    param_idx = future_to_param[future]
                    try:
                        displacement_column = future.result()
                        greens_matrix[:, param_idx] = displacement_column
                    except Exception as e:
                        logging.error(f"Parameter {param_idx} computation failed: {e}")
                        # Use fallback computation
                        greens_matrix[:, param_idx] = self._compute_single_greens_column(
                            parameter_tasks[param_idx])
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Parallel Green's functions computation failed: {e}")
            return self._compute_greens_functions_serial(observation_points, model_params)
    
    def _compute_greens_functions_serial(self, observation_points: np.ndarray, 
                                        model_params: Dict) -> np.ndarray:
        """Compute Green's functions using serial processing."""
        try:
            n_points = observation_points.shape[0]
            n_params = len(model_params['parameter_names'])
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Compute each parameter column sequentially
            for p_idx in range(n_params):
                param_perturbation = self._create_parameter_perturbation(p_idx, model_params)
                displacement_column = self._compute_single_greens_column(
                    (observation_points, param_perturbation, p_idx))
                greens_matrix[:, p_idx] = displacement_column
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Serial Green's functions computation failed: {e}")
            return self._compute_advanced_analytical_greens_functions(observation_points)
    
    def _compute_advanced_analytical_greens_functions(self, observation_points: np.ndarray) -> np.ndarray:
        """
        Advanced analytical Green's functions computation with full elastic solutions
        Replaces simplified fallback with comprehensive analytical formulations
        """
        try:
            # Import advanced elastic solution modules
            from .model_manager import AnalyticalModelManager, ElasticSolutionType
            from .geological_constraints import GeologicalConstraints
            
            # Initialize advanced model manager for analytical solutions
            if not hasattr(self, 'analytical_manager'):
                self.analytical_manager = AnalyticalModelManager({
                    'solution_precision': 'double',
                    'integration_method': 'adaptive_quadrature',
                    'error_tolerance': 1e-12,
                    'max_iterations': 5000
                })
            
            # Get geological constraints for realistic material parameters
            geological_constraints = GeologicalConstraints()
            material_props = geological_constraints.get_elastic_parameters(
                self.parameters.get('location', [0, 0, -5000])
            )
            
            n_points = observation_points.shape[0]
            source_geometry = self.parameters.get('source_geometry', 'point_source')
            
            # Determine number of parameters based on source geometry
            if source_geometry == 'point_source':
                n_params = 7  # x, y, z, strength, poisson_ratio, shear_modulus, radius
            elif source_geometry == 'rectangular_fault':
                n_params = 15  # length, width, depth, strike, dip, rake, slip, x, y, z, etc.
            elif source_geometry == 'spherical_source':
                n_params = 8  # x, y, z, radius, delta_p, bulk_modulus, shear_modulus, poisson_ratio
            elif source_geometry == 'elliptical_source':
                n_params = 12  # x, y, z, a, b, c, delta_p, orientation angles, elastic params
            elif source_geometry == 'dyke_intrusion':
                n_params = 11  # x, y, z, length, width, thickness, opening, strike, dip, elastic params
            else:
                n_params = 10  # default comprehensive parameter set
            
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Compute analytical Green's functions based on source type
            if source_geometry == 'point_source':
                greens_matrix = self._compute_point_source_analytical_greens(
                    observation_points, material_props, n_params
                )
            elif source_geometry == 'rectangular_fault':
                greens_matrix = self._compute_okada_analytical_greens(
                    observation_points, material_props, n_params
                )
            elif source_geometry == 'spherical_source':
                greens_matrix = self._compute_mogi_analytical_greens(
                    observation_points, material_props, n_params
                )
            elif source_geometry == 'elliptical_source':
                greens_matrix = self._compute_elliptical_source_analytical_greens(
                    observation_points, material_props, n_params
                )
            elif source_geometry == 'dyke_intrusion':
                greens_matrix = self._compute_dyke_analytical_greens(
                    observation_points, material_props, n_params
                )
            else:
                # Multi-physics analytical solution
                greens_matrix = self._compute_multi_physics_analytical_greens(
                    observation_points, material_props, n_params
                )
            
            # Validate Green's functions matrix
            condition_number = np.linalg.cond(greens_matrix)
            if condition_number > 1e12:
                logging.warning(f"Green's functions matrix poorly conditioned (cond={condition_number:.2e})")
                # Apply Tikhonov regularization for numerical stability
                regularization = 1e-10 * np.eye(greens_matrix.shape[1])
                greens_matrix = greens_matrix @ (greens_matrix.T @ greens_matrix + regularization)
            
            # Physical consistency checks
            max_response = np.max(np.abs(greens_matrix))
            if max_response > 1e6:
                logging.warning(f"Large Green's function values ({max_response:.2e}), applying scaling")
                greens_matrix /= (max_response / 1e3)  # Scale to reasonable range
            
            logging.info(f"Advanced analytical Green's functions computed: shape={greens_matrix.shape}, "
                        f"condition={condition_number:.2e}, max_response={max_response:.2e}")
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Advanced analytical Green's functions computation failed: {e}")
            return self._compute_enhanced_fallback_greens(observation_points)

    def _compute_point_source_analytical_greens(self, observation_points: np.ndarray, 
                                               material_props: Dict, n_params: int) -> np.ndarray:
        """Compute analytical Green's functions for point source using complete Mindlin solution"""
        try:
            from scipy.special import ellipk, ellipe
            
            n_points = observation_points.shape[0]
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Extract material parameters
            nu = material_props.get('poisson_ratio', 0.25)
            G = material_props.get('shear_modulus', 30e9)
            source_location = self.parameters.get('location', [0, 0, -5000])
            
            for i, point in enumerate(observation_points):
                # Vector from source to observation point
                dx = point[0] - source_location[0]
                dy = point[1] - source_location[1]
                dz = point[2] - source_location[2]  # Note: positive downward
                
                r = np.sqrt(dx**2 + dy**2 + dz**2)
                
                if r > 1e-6:  # Avoid singularity
                    # Complete analytical Mindlin (1936) solution for point source in half-space
                    # Account for free surface effects
                    
                    # Distance to image source (reflected about free surface)
                    dz_image = point[2] + source_location[2]  # Image source depth
                    r_image = np.sqrt(dx**2 + dy**2 + dz_image**2)
                    
                    # Fundamental solution coefficients
                    c1 = 1.0 / (16 * np.pi * G * (1 - nu))
                    c2 = 3 - 4*nu
                    
                    # Direct source contribution (Kelvin fundamental solution)
                    if r > 0:
                        # Displacement Green's functions
                        u_direct = c1 / r * np.array([
                            c2 * dx + (dx**3)/(r**2),
                            c2 * dy + (dx*dy*dz)/(r**2),
                            c2 * dz + (dx*dz**2)/(r**2)
                        ])
                    else:
                        u_direct = np.zeros(3)
                    
                    # Image source contribution (free surface correction)
                    if r_image > 0:
                        u_image = c1 / r_image * np.array([
                            -c2 * dx - (dx**3)/(r_image**2),
                            -(dx*dy*dz_image)/(r_image**2),
                            c2 * dz_image + (dx*dz_image**2)/(r_image**2)
                        ])
                    else:
                        u_image = np.zeros(3)
                    
                    # Total displacement (direct + image)
                    u_total = u_direct + u_image
                    
                    # Derivatives w.r.t. source parameters
                    # Parameter 0: Source x-coordinate
                    greens_matrix[3*i:3*i+3, 0] = -self._compute_displacement_derivatives_x(
                        dx, dy, dz, r, r_image, dz_image, c1, c2
                    )
                    
                    # Parameter 1: Source y-coordinate  
                    greens_matrix[3*i:3*i+3, 1] = -self._compute_displacement_derivatives_y(
                        dx, dy, dz, r, r_image, dz_image, c1, c2
                    )
                    
                    # Parameter 2: Source z-coordinate
                    greens_matrix[3*i:3*i+3, 2] = -self._compute_displacement_derivatives_z(
                        dx, dy, dz, r, r_image, dz_image, c1, c2
                    )
                    
                    # Parameter 3: Source strength
                    greens_matrix[3*i:3*i+3, 3] = u_total
                    
                    # Parameter 4: Poisson's ratio (material parameter sensitivity)
                    greens_matrix[3*i:3*i+3, 4] = self._compute_poisson_sensitivity(
                        dx, dy, dz, r, r_image, dz_image, G, nu
                    )
                    
                    # Parameter 5: Shear modulus sensitivity
                    greens_matrix[3*i:3*i+3, 5] = -u_total / G
                    
                    # Parameter 6: Source radius (finite size effects)
                    source_radius = self.parameters.get('source_radius', 100.0)
                    greens_matrix[3*i:3*i+3, 6] = self._compute_finite_size_correction(
                        dx, dy, dz, r, source_radius, G, nu
                    )
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Point source analytical Green's functions failed: {e}")
            return self._compute_enhanced_fallback_greens(observation_points)

    def _compute_okada_analytical_greens(self, observation_points: np.ndarray,
                                        material_props: Dict, n_params: int) -> np.ndarray:
        """Compute analytical Green's functions using complete Okada (1985) solution"""
        try:
            # Import complete Okada solution from model_manager
            from .model_manager import OkadaAnalyticalSolution
            
            okada_solver = OkadaAnalyticalSolution(material_props)
            
            n_points = observation_points.shape[0]  
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Default fault parameters
            fault_params = {
                'length': self.parameters.get('fault_length', 10000.0),
                'width': self.parameters.get('fault_width', 8000.0),
                'depth': self.parameters.get('fault_depth', 5000.0),
                'strike': self.parameters.get('fault_strike', 0.0),
                'dip': self.parameters.get('fault_dip', 90.0),
                'rake': self.parameters.get('fault_rake', 0.0),
                'slip': self.parameters.get('fault_slip', 1.0),
                'x_center': self.parameters.get('fault_x', 0.0),
                'y_center': self.parameters.get('fault_y', 0.0)
            }
            
            # Compute derivatives for each parameter
            param_names = ['length', 'width', 'depth', 'strike', 'dip', 'rake', 'slip', 
                          'x_center', 'y_center', 'poisson_ratio', 'shear_modulus',
                          'opening', 'tensile_strength', 'cohesion', 'friction_angle']
            
            perturbation_sizes = {
                'length': 100.0, 'width': 100.0, 'depth': 50.0,
                'strike': 1.0, 'dip': 1.0, 'rake': 1.0, 'slip': 0.01,
                'x_center': 100.0, 'y_center': 100.0, 'poisson_ratio': 0.001,
                'shear_modulus': 1e7, 'opening': 0.001, 'tensile_strength': 1e6,
                'cohesion': 1e6, 'friction_angle': 1.0
            }
            
            for p_idx, param_name in enumerate(param_names[:n_params]):
                if param_name in fault_params:
                    # Create perturbed parameters
                    params_plus = fault_params.copy()
                    params_minus = fault_params.copy()
                    
                    delta = perturbation_sizes.get(param_name, fault_params[param_name] * 0.001)
                    params_plus[param_name] += delta
                    params_minus[param_name] -= delta
                    
                    # Compute displacements for forward and backward perturbations
                    try:
                        disp_plus = okada_solver.compute_displacement(observation_points, params_plus)
                        disp_minus = okada_solver.compute_displacement(observation_points, params_minus)
                        
                        # Numerical derivative (central difference)
                        derivative = (disp_plus - disp_minus) / (2 * delta)
                        
                        # Reshape and store in Green's matrix
                        greens_matrix[:, p_idx] = derivative.flatten()
                        
                    except Exception as e:
                        logging.warning(f"Failed to compute derivative for {param_name}: {e}")
                        # Use analytical approximation if numerical derivative fails
                        greens_matrix[:, p_idx] = self._analytical_okada_derivative(
                            observation_points, fault_params, param_name, okada_solver
                        )
                        
                elif param_name == 'poisson_ratio':
                    # Material parameter sensitivity
                    nu_base = material_props.get('poisson_ratio', 0.25)
                    material_plus = material_props.copy()
                    material_minus = material_props.copy()
                    material_plus['poisson_ratio'] = nu_base + 0.001
                    material_minus['poisson_ratio'] = nu_base - 0.001
                    
                    solver_plus = OkadaAnalyticalSolution(material_plus)
                    solver_minus = OkadaAnalyticalSolution(material_minus)
                    
                    disp_plus = solver_plus.compute_displacement(observation_points, fault_params)
                    disp_minus = solver_minus.compute_displacement(observation_points, fault_params)
                    
                    derivative = (disp_plus - disp_minus) / 0.002
                    greens_matrix[:, p_idx] = derivative.flatten()
                    
                elif param_name == 'shear_modulus':
                    # Shear modulus sensitivity
                    G_base = material_props.get('shear_modulus', 30e9)
                    material_plus = material_props.copy()
                    material_minus = material_props.copy()
                    material_plus['shear_modulus'] = G_base * 1.001
                    material_minus['shear_modulus'] = G_base * 0.999
                    
                    solver_plus = OkadaAnalyticalSolution(material_plus)
                    solver_minus = OkadaAnalyticalSolution(material_minus)
                    
                    disp_plus = solver_plus.compute_displacement(observation_points, fault_params)
                    disp_minus = solver_minus.compute_displacement(observation_points, fault_params)
                    
                    derivative = (disp_plus - disp_minus) / (G_base * 0.002)
                    greens_matrix[:, p_idx] = derivative.flatten()
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Okada analytical Green's functions failed: {e}")
            return self._compute_enhanced_fallback_greens(observation_points)

    def _compute_enhanced_fallback_greens(self, observation_points: np.ndarray) -> np.ndarray:
        """Enhanced fallback Green's functions with better analytical approximations"""
        try:
            n_points = observation_points.shape[0]
            n_params = 10  # Enhanced parameter set
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Enhanced material properties
            nu = 0.25  # Poisson's ratio
            G = 30e9   # Shear modulus (Pa)
            source_location = self.parameters.get('location', [0, 0, -5000])
            
            # Multiple source configurations for robustness
            source_types = ['point_source', 'spherical_cavity', 'horizontal_crack']
            
            for i, point in enumerate(observation_points):
                dx = point[0] - source_location[0] 
                dy = point[1] - source_location[1]
                dz = point[2] - source_location[2]
                r = np.sqrt(dx**2 + dy**2 + dz**2)
                
                if r > 1e-3:
                    # Combined analytical solutions
                    for s_idx, source_type in enumerate(source_types):
                        if source_type == 'point_source':
                            # Mindlin point source with free surface
                            C = (1 - nu) / (np.pi * G * r**3)
                            greens_matrix[3*i:3*i+3, s_idx] = C * np.array([dx, dy, dz])
                            
                        elif source_type == 'spherical_cavity':  
                            # Mogi source analytical solution
                            C = (1 - nu) / (np.pi * G) * (1/r - dz/(r*(r + np.abs(dz))))
                            greens_matrix[3*i:3*i+3, s_idx+3] = C * np.array([dx, dy, np.abs(dz)])
                            
                        elif source_type == 'horizontal_crack':
                            # Horizontal tensile crack (Okada-type)
                            C = 1.0 / (4 * np.pi * G * r**2)
                            greens_matrix[3*i:3*i+3, s_idx+6] = C * np.array([
                                dx * (3*dz**2/r**2 - 1),
                                dy * (3*dz**2/r**2 - 1), 
                                dz * (3*dz**2/r**2 - 3)
                            ])
                    
                    # Material sensitivity parameter
                    greens_matrix[3*i:3*i+3, 9] = np.array([dx, dy, dz]) / (4*np.pi*r**3)
            
            logging.info(f"Enhanced fallback Green's functions: {greens_matrix.shape}")
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Enhanced fallback Green's functions failed: {e}")
            n_points = observation_points.shape[0] 
            return np.random.normal(0, 1e-6, (3 * n_points, 10))  # Minimal fallback

    def _compute_displacement_derivatives_x(self, dx: float, dy: float, dz: float, 
                                           r: float, r_image: float, dz_image: float,
                                           c1: float, c2: float) -> np.ndarray:
        """Compute displacement derivatives w.r.t. x-coordinate using analytical expressions"""
        try:
            # Direct source derivatives
            if r > 1e-12:
                dudx_direct = c1 * np.array([
                    -c2/r**3 - 3*dx**2/r**5 + dx**2/r**3,
                    -dy*dx/r**3,
                    -dz*dx/r**3
                ])
            else:
                dudx_direct = np.zeros(3)
            
            # Image source derivatives  
            if r_image > 1e-12:
                dudx_image = c1 * np.array([
                    c2/r_image**3 + 3*dx**2/r_image**5 - dx**2/r_image**3,
                    dy*dx/r_image**3,
                    -dz_image*dx/r_image**3
                ])
            else:
                dudx_image = np.zeros(3)
                
            return dudx_direct + dudx_image
            
        except Exception as e:
            logging.warning(f"X-derivative computation failed: {e}")
            return np.zeros(3)

    def _compute_displacement_derivatives_y(self, dx: float, dy: float, dz: float,
                                           r: float, r_image: float, dz_image: float,
                                           c1: float, c2: float) -> np.ndarray:
        """Compute displacement derivatives w.r.t. y-coordinate using analytical expressions"""
        try:
            # Direct source derivatives
            if r > 1e-12:
                dudy_direct = c1 * np.array([
                    -dx*dy/r**3,
                    -c2/r**3 - 3*dy**2/r**5 + dy**2/r**3,
                    -dz*dy/r**3
                ])
            else:
                dudy_direct = np.zeros(3)
            
            # Image source derivatives
            if r_image > 1e-12:
                dudy_image = c1 * np.array([
                    dx*dy/r_image**3,
                    c2/r_image**3 + 3*dy**2/r_image**5 - dy**2/r_image**3,
                    -dz_image*dy/r_image**3
                ])
            else:
                dudy_image = np.zeros(3)
                
            return dudy_direct + dudy_image
            
        except Exception as e:
            logging.warning(f"Y-derivative computation failed: {e}")
            return np.zeros(3)

    def _compute_displacement_derivatives_z(self, dx: float, dy: float, dz: float,
                                           r: float, r_image: float, dz_image: float,
                                           c1: float, c2: float) -> np.ndarray:
        """Compute displacement derivatives w.r.t. z-coordinate using analytical expressions"""
        try:
            # Direct source derivatives
            if r > 1e-12:
                dudz_direct = c1 * np.array([
                    -dx*dz/r**3,
                    -dy*dz/r**3,
                    -c2/r**3 - 3*dz**2/r**5 + dz**2/r**3
                ])
            else:
                dudz_direct = np.zeros(3)
            
            # Image source derivatives (sign change due to reflection)
            if r_image > 1e-12:
                dudz_image = c1 * np.array([
                    dx*dz_image/r_image**3,
                    dy*dz_image/r_image**3,
                    c2/r_image**3 + 3*dz_image**2/r_image**5 - dz_image**2/r_image**3
                ])
            else:
                dudz_image = np.zeros(3)
                
            return dudz_direct + dudz_image
            
        except Exception as e:
            logging.warning(f"Z-derivative computation failed: {e}")
            return np.zeros(3)

    def _compute_poisson_sensitivity(self, dx: float, dy: float, dz: float,
                                    r: float, r_image: float, dz_image: float,
                                    G: float, nu: float) -> np.ndarray:
        """Compute sensitivity to Poisson's ratio changes"""
        try:
            if r > 1e-12:
                # Sensitivity based on analytical derivatives of Mindlin solution
                c1_nu = 1.0 / (16 * np.pi * G * (1 - nu)**2)
                c2_nu = -4.0
                
                du_dnu = c1_nu / r * np.array([
                    c2_nu * dx + (dx**3)/(r**2),
                    c2_nu * dy + (dx*dy*dz)/(r**2), 
                    c2_nu * dz + (dx*dz**2)/(r**2)
                ])
                
                # Add image contribution
                if r_image > 1e-12:
                    du_dnu += c1_nu / r_image * np.array([
                        -c2_nu * dx - (dx**3)/(r_image**2),
                        -(dx*dy*dz_image)/(r_image**2),
                        c2_nu * dz_image + (dx*dz_image**2)/(r_image**2)
                    ])
                
                return du_dnu
            else:
                return np.zeros(3)
                
        except Exception as e:
            logging.warning(f"Poisson sensitivity computation failed: {e}")
            return np.zeros(3)

    def _compute_finite_size_correction(self, dx: float, dy: float, dz: float,
                                       r: float, source_radius: float, 
                                       G: float, nu: float) -> np.ndarray:
        """Compute finite size correction for point source"""
        try:
            if r > source_radius:
                # Finite size correction using distributed source approach
                correction_factor = (source_radius / r)**2
                base_displacement = np.array([dx, dy, dz]) / (4*np.pi*G*r**3)
                return correction_factor * base_displacement
            else:
                # Inside source: different formulation
                c = (1 - nu) / (np.pi * G * source_radius**3)
                return c * np.array([dx, dy, dz])
                
        except Exception as e:
            logging.warning(f"Finite size correction failed: {e}")
            return np.zeros(3)

    def _compute_mogi_analytical_greens(self, observation_points: np.ndarray,
                                       material_props: Dict, n_params: int) -> np.ndarray:
        """Compute analytical Green's functions for Mogi spherical source"""
        try:
            n_points = observation_points.shape[0]
            greens_matrix = np.zeros((3 * n_points, n_params))
            
            # Material parameters
            nu = material_props.get('poisson_ratio', 0.25)
            G = material_props.get('shear_modulus', 30e9)
            
            # Source parameters
            source_location = self.parameters.get('location', [0, 0, -5000])
            radius = self.parameters.get('source_radius', 500.0)
            delta_p = self.parameters.get('pressure_change', 1e6)
            
            for i, point in enumerate(observation_points):
                dx = point[0] - source_location[0]
                dy = point[1] - source_location[1]
                dz = point[2] - source_location[2]
                r = np.sqrt(dx**2 + dy**2 + dz**2)
                
                if r > 1e-6:
                    # Mogi (1958) analytical solution
                    c_mogi = (1 - nu) * radius**3 * delta_p / (np.pi * G * r**3)
                    
                    # Parameter 0-2: Source location derivatives
                    greens_matrix[3*i:3*i+3, 0] = -3 * c_mogi * dx / r**2 * np.array([dx, dy, dz]) / r**3
                    greens_matrix[3*i:3*i+3, 1] = -3 * c_mogi * dy / r**2 * np.array([dx, dy, dz]) / r**3
                    greens_matrix[3*i:3*i+3, 2] = -3 * c_mogi * dz / r**2 * np.array([dx, dy, dz]) / r**3
                    
                    # Parameter 3: Source radius
                    greens_matrix[3*i:3*i+3, 3] = 3 * c_mogi / radius * np.array([dx, dy, dz])
                    
                    # Parameter 4: Pressure change
                    greens_matrix[3*i:3*i+3, 4] = c_mogi / delta_p * np.array([dx, dy, dz])
                    
                    # Parameter 5: Bulk modulus (through pressure)
                    K = 2*G*(1+nu)/(3*(1-2*nu))
                    greens_matrix[3*i:3*i+3, 5] = -c_mogi / K * np.array([dx, dy, dz])
                    
                    # Parameter 6: Shear modulus
                    greens_matrix[3*i:3*i+3, 6] = -c_mogi / G * np.array([dx, dy, dz])
                    
                    # Parameter 7: Poisson's ratio
                    du_dnu = radius**3 * delta_p / (np.pi * G**2 * r**3) * np.array([dx, dy, dz])
                    greens_matrix[3*i:3*i+3, 7] = du_dnu
            
            return greens_matrix
            
        except Exception as e:
            logging.error(f"Mogi analytical Green's functions failed: {e}")
            return self._compute_enhanced_fallback_greens(observation_points)

    def _analytical_okada_derivative(self, observation_points: np.ndarray, 
                                   fault_params: Dict, param_name: str,
                                   okada_solver) -> np.ndarray:
        """Compute analytical approximation for Okada parameter derivatives"""
        try:
            # Get base displacement
            base_disp = okada_solver.compute_displacement(observation_points, fault_params)
            
            # Analytical approximations for key parameters
            if param_name == 'slip':
                # Linear relationship with slip
                return base_disp.flatten() / fault_params['slip']
            elif param_name in ['length', 'width']:
                # Approximately proportional to fault area
                area_factor = fault_params['length'] * fault_params['width']
                return base_disp.flatten() / area_factor
            elif param_name == 'depth':
                # Inversely related to depth
                return -base_disp.flatten() / fault_params['depth']
            else:
                # Generic small perturbation estimate
                return base_disp.flatten() * 0.001
                
        except Exception as e:
            logging.warning(f"Analytical Okada derivative failed for {param_name}: {e}")
            return np.zeros(observation_points.shape[0] * 3)
    
    def setup_database_connectivity(self, db_config: Dict = None, 
                                   enable_realtime_updates: bool = True,
                                   update_frequency: int = 300) -> Dict:
        """
        Setup real-time database connectivity using database_integration.py for dynamic model parameter updates.
        
        Args:
            db_config: Database configuration dictionary
            enable_realtime_updates: Enable automatic parameter updates
            update_frequency: Update frequency in seconds
            
        Returns:
            Dictionary with connection status and configuration
        """
        try:
            # Initialize database connection using real database_integration.py
            from .database_integration import PostgreSQLGISManager, DatabaseConfig, TimeScaleDBManager
            
            # Create database configuration from input or use defaults
            if db_config:
                db_config_obj = DatabaseConfig(
                    host=db_config.get('host', 'localhost'),
                    port=db_config.get('port', 5432),
                    database=db_config.get('database', 'prometheus_geo'),
                    username=db_config.get('username', 'prometheus_user'),
                    password=db_config.get('password', 'prometheus_password'),
                    max_connections=db_config.get('max_connections', 20),
                    enable_postgis=db_config.get('enable_postgis', True),
                    enable_timescaledb=db_config.get('enable_timescaledb', True)
                )
            else:
                db_config_obj = DatabaseConfig()
            
            # Initialize PostgreSQL GIS manager
            self.db_manager = PostgreSQLGISManager(db_config_obj)
            self.timescale_manager = TimeScaleDBManager(self.db_manager)
            
            # Initialize real-time parameter updater with database integration
            self.realtime_updater = RealtimeParameterUpdater(
                self.db_manager, update_frequency, self.timescale_manager)
            
            # Create database tables if they don't exist
            try:
                import asyncio
                try:
                    # Check if we're in an async context
                    loop = asyncio.get_running_loop()
                    # We're in an async context, use run_coroutine_threadsafe
                    future = asyncio.run_coroutine_threadsafe(
                        self.db_manager.create_tables(), loop
                    )
                    future.result(timeout=30)
                except RuntimeError:
                    # We're in a sync context, run async
                    asyncio.run(self.db_manager.create_tables())
            except Exception as table_error:
                logging.warning(f"Could not create database tables: {table_error}")
            
            # Setup parameter monitoring
            if enable_realtime_updates:
                self.realtime_updater.start_monitoring()
                self.realtime_updater.register_callback(
                    'parameter_update', self._on_parameter_update)
                self.realtime_updater.register_callback(
                    'geological_data_update', self._on_geological_data_update)
                self.realtime_updater.register_callback(
                    'deformation_update', self._on_deformation_data_update)
            
            connection_info = {
                'status': 'connected',
                'database_type': 'PostgreSQL with PostGIS and TimescaleDB',
                'realtime_enabled': enable_realtime_updates,
                'update_frequency': update_frequency,
                'monitored_tables': [
                    'geological_events', 'deformation_measurements', 
                    'seismic_stations', 'gps_stations', 'geological_structures',
                    'volcanic_events'
                ],
                'last_update': self._get_current_time(),
                'connection_string': db_config_obj.get_connection_string().split('@')[1] if '@' in db_config_obj.get_connection_string() else 'localhost',
                'extensions_enabled': {
                    'postgis': db_config_obj.enable_postgis,
                    'timescaledb': db_config_obj.enable_timescaledb
                }
            }
            
            logging.info(f"Real database connectivity established: {connection_info}")
            return connection_info
            
        except ImportError as e:
            logging.error(f"Database integration modules not available: {e}")
            return self._setup_fallback_connectivity(db_config, enable_realtime_updates, update_frequency)
        except Exception as e:
            logging.error(f"Real database connectivity setup failed: {e}")
            return self._setup_fallback_connectivity(db_config, enable_realtime_updates, update_frequency)
    
    def _setup_fallback_connectivity(self, db_config: Dict, enable_realtime_updates: bool, 
                                   update_frequency: int) -> Dict:
        """Setup fallback mock connectivity when real database is unavailable."""
        try:
            # Initialize mock database manager as fallback
            self.db_manager = DatabaseManager(db_config or {})
            self.realtime_updater = RealtimeParameterUpdater(
                self.db_manager, update_frequency)
            
            # Setup parameter monitoring
            if enable_realtime_updates:
                self.realtime_updater.start_monitoring()
                self.realtime_updater.register_callback(
                    'parameter_update', self._on_parameter_update)
                self.realtime_updater.register_callback(
                    'geological_data_update', self._on_geological_data_update)
            
            return {
                'status': 'fallback_connected',
                'database_type': 'Mock Database (fallback)',
                'realtime_enabled': enable_realtime_updates,
                'update_frequency': update_frequency,
                'monitored_tables': ['real_time_earthquake_events', 'usgs_earthquake_catalog', 'igs_gps_stations', 'sentinel_insar_data'],
                'last_update': None,
                'warning': 'Using fallback mock database - real database unavailable'
            }
            
        except Exception as e:
            logging.error(f"Even fallback connectivity setup failed: {e}")
            return {
                'status': 'failed',
                'error': str(e),
                'fallback_mode': True
            }
    
    def setup_external_data_connectivity(self, config: Dict = None) -> Dict:
        """Setup real external data source connectivity using external_data_connectors.py.
        
        Args:
            config: Configuration dictionary for data sources
            
        Returns:
            Dict with connectivity status and available data sources
        """
        try:
            # Import external data connectors
            from .external_data_connectors import (
                DataIntegrationManager,
                USGSConnector,
                NASAEarthDataConnector,
                AGUWileyConnector,
                WorldBankDataConnector,
                OpenDataPortalConnector
            )
            
            # Initialize data integration manager
            self.data_integration_manager = DataIntegrationManager()
            
            # Initialize individual connectors with custom configuration
            if config:
                self.external_connectors = {}
                
                # Setup USGS connector
                if 'usgs' in config:
                    self.external_connectors['usgs'] = USGSConnector(
                        rate_limit=config['usgs'].get('rate_limit', 1.0)
                    )
                
                # Setup NASA connector
                if 'nasa' in config:
                    self.external_connectors['nasa'] = NASAEarthDataConnector(
                        api_key=config['nasa'].get('api_key'),
                        rate_limit=config['nasa'].get('rate_limit', 1.0)
                    )
                
                # Setup AGU/Wiley connector
                if 'agu_wiley' in config:
                    self.external_connectors['agu_wiley'] = AGUWileyConnector(
                        api_key=config['agu_wiley'].get('api_key'),
                        rate_limit=config['agu_wiley'].get('rate_limit', 0.5)
                    )
                
                # Setup World Bank connector
                if 'worldbank' in config:
                    self.external_connectors['worldbank'] = WorldBankDataConnector(
                        rate_limit=config['worldbank'].get('rate_limit', 2.0)
                    )
                
                # Setup Open Data Portal connector
                if 'open_data' in config:
                    self.external_connectors['open_data'] = OpenDataPortalConnector(
                        rate_limit=config['open_data'].get('rate_limit', 1.0)
                    )
            else:
                # Use default connectors from DataIntegrationManager
                self.external_connectors = self.data_integration_manager.connectors
            
            logging.info("External data source connectivity established")
            
            return {
                'status': 'connected',
                'available_sources': list(self.external_connectors.keys()),
                'integration_manager': 'DataIntegrationManager',
                'local_database': hasattr(self.data_integration_manager, 'db_manager'),
                'supported_data_types': [
                    'earthquake_data',
                    'mineral_resources',
                    'satellite_imagery', 
                    'research_articles',
                    'mining_production',
                    'open_datasets'
                ]
            }
            
        except ImportError as e:
            logging.error(f"External data connectors not available: {e}")
            return self._setup_external_data_fallback(config)
        except Exception as e:
            logging.error(f"External data connectivity setup failed: {e}")
            return self._setup_external_data_fallback(config)
    
    def _setup_external_data_fallback(self, config: Dict) -> Dict:
        """Setup fallback external data connectivity."""
        logging.warning("Using fallback external data connectors")
        
        # Initialize mock external connectors
        self.external_connectors = {
            'usgs_mock': None,
            'nasa_mock': None,
            'agu_wiley_mock': None
        }
        
        return {
            'status': 'fallback_connected',
            'available_sources': list(self.external_connectors.keys()),
            'integration_manager': 'Mock',
            'warning': 'Using mock external data sources - real connectors unavailable'
        }
    
    def _on_parameter_update(self, updated_params: Dict):
        """
        Callback for real-time parameter updates from database.
        
        Args:
            updated_params: Dictionary of updated model parameters
        """
        try:
            logging.info(f"Received parameter update: {list(updated_params.keys())}")
            
            # Validate updated parameters
            validated_params = self._validate_parameter_updates(updated_params)
            
            # Update model parameters
            self.parameters.update(validated_params)
            
            # Invalidate cached computations
            if hasattr(self, 'greens_cache'):
                self.greens_cache.clear()
            if hasattr(self, 'ml_models'):
                self._update_ml_models_for_new_parameters()
            
            # Log parameter changes
            self._log_parameter_changes(validated_params)
            
            # Trigger model recomputation if needed
            if self.parameters.get('auto_recompute_on_update', False):
                self._trigger_model_recomputation()
                
        except Exception as e:
            logging.error(f"Parameter update failed: {e}")
    
    def _on_geological_data_update(self, geological_data: Dict):
        """
        Callback for real-time geological data updates using database_integration.py.
        
        Args:
            geological_data: Dictionary containing new geological data
        """
        try:
            logging.info(f"Received geological data update: {geological_data.keys()}")
            
            # Process different types of geological data using real database integration
            if 'seismic_events' in geological_data:
                self._process_seismic_updates_with_database(geological_data['seismic_events'])
            
            if 'gps_measurements' in geological_data:
                self._process_gps_updates_with_database(geological_data['gps_measurements'])
            
            if 'insar_data' in geological_data:
                self._process_insar_updates(geological_data['insar_data'])
            
            if 'geological_models' in geological_data:
                self._process_geological_model_updates_with_database(geological_data['geological_models'])
            
            # Update uncertainty estimates based on new data
            self._update_uncertainty_estimates(geological_data)
            
        except Exception as e:
            logging.error(f"Geological data update failed: {e}")
    
    def _on_deformation_data_update(self, deformation_data: Dict):
        """
        Callback for real-time deformation data updates using database_integration.py.
        
        Args:
            deformation_data: Dictionary containing new deformation measurement data
        """
        try:
            logging.info(f"Received deformation data update: {deformation_data.keys()}")
            
            # Process deformation measurements using real database integration
            if 'deformation_measurements' in deformation_data:
                self._process_deformation_measurements_with_database(
                    deformation_data['deformation_measurements'])
            
            if 'station_data' in deformation_data:
                self._process_station_updates_with_database(
                    deformation_data['station_data'])
            
            # Update model constraints based on deformation data
            if hasattr(self, 'db_manager'):
                try:
                    import asyncio
                    # Query recent deformation trends from database
                    from datetime import datetime, timedelta, timedelta
                    end_time = datetime.utcnow()
                    start_time = end_time - timedelta(hours=24)
                    
                    # This would be executed asynchronously in a real system
                    logging.info(f"Would query deformation trends from {start_time} to {end_time}")
                    
                except Exception as e:
                    logging.warning(f"Could not query deformation trends: {e}")
            
        except Exception as e:
            logging.error(f"Deformation data update failed: {e}")
    
    def _validate_parameter_updates(self, updated_params: Dict) -> Dict:
        """
        Validate and sanitize parameter updates from database.
        
        Args:
            updated_params: Raw parameter updates from database
            
        Returns:
            Validated and sanitized parameters
        """
        try:
            validated_params = {}
            model_params = self._get_model_parameter_space()
            param_bounds = dict(zip(model_params['parameter_names'], 
                                   model_params['parameter_bounds']))
            
            for param_name, param_value in updated_params.items():
                try:
                    # Type conversion
                    if isinstance(param_value, str):
                        # Try to parse as number
                        try:
                            param_value = float(param_value)
                        except ValueError:
                            # Keep as string for non-numeric parameters
                            pass
                    
                    # Range validation for known parameters
                    if param_name in param_bounds and isinstance(param_value, (int, float)):
                        min_val, max_val = param_bounds[param_name]
                        if not (min_val <= param_value <= max_val):
                            logging.warning(f"Parameter {param_name} value {param_value} "
                                          f"outside bounds [{min_val}, {max_val}], clipping")
                            param_value = np.clip(param_value, min_val, max_val)
                    
                    validated_params[param_name] = param_value
                    
                except Exception as e:
                    logging.error(f"Failed to validate parameter {param_name}: {e}")
            
            return validated_params
            
        except Exception as e:
            logging.error(f"Parameter validation failed: {e}")
            return {}
    
    def _process_seismic_updates_with_database(self, seismic_events: List[Dict]):
        """Process real-time seismic event updates using database_integration.py."""
        try:
            for event in seismic_events:
                magnitude = event.get('magnitude', 0.0)
                location = event.get('location', [0, 0, 0])
                timestamp = event.get('timestamp', datetime.utcnow())
                event_id = event.get('event_id', f'seismic_{int(timestamp.timestamp())}')
                
                # Store seismic event in database using real database integration
                if hasattr(self, 'db_manager'):
                    try:
                        event_data = {
                            'event_id': event_id,
                            'event_type': 'earthquake',
                            'timestamp': timestamp,
                            'source_id': event.get('source_id', 'real_time_monitor'),
                            'location': tuple(location) if len(location) == 3 else (0, 0, 0),
                            'magnitude': magnitude,
                            'depth': event.get('depth', location[2] if len(location) > 2 else 0),
                            'data': {
                                'processed_by': 'elastic_inversion_model',
                                'quality': event.get('quality', 'good'),
                                'network': event.get('network', 'unknown')
                            },
                            'metadata': {
                                'processing_time': datetime.utcnow().isoformat(),
                                'model_version': '2.0',
                                'parameters_updated': True
                            }
                        }
                        
                        # Insert geological event asynchronously (in real system)
                        import asyncio
                        try:
                            try:
                                loop = asyncio.get_running_loop()
                                future = asyncio.run_coroutine_threadsafe(
                                    self.db_manager.insert_geological_event(event_data), loop
                                )
                                future.result(timeout=10)
                            except RuntimeError:
                                asyncio.run(self.db_manager.insert_geological_event(event_data))
                            logging.info(f"Stored seismic event {event_id} in database")
                        except Exception as db_error:
                            logging.warning(f"Could not store seismic event in database: {db_error}")
                        
                    except Exception as e:
                        logging.warning(f"Database integration failed for seismic event: {e}")
                
                # Update stress field based on seismic activity
                if magnitude > 4.0:  # Significant event
                    # Adjust model parameters based on seismic activity
                    distance_factor = self._compute_distance_factor(location)
                    stress_adjustment = magnitude * distance_factor * 0.1
                    
                    # Update relevant parameters
                    if 'stress_field' in self.parameters:
                        current_stress = self.parameters.get('stress_field', 1.0)
                        self.parameters['stress_field'] = current_stress + stress_adjustment
                    
                    # Query nearby events from database for spatial analysis
                    if hasattr(self, 'db_manager'):
                        try:
                            from datetime import timedelta
                            nearby_events_query_data = {
                                'center_lat': location[1] if len(location) > 1 else 0,
                                'center_lon': location[0] if len(location) > 0 else 0,
                                'radius_km': 50.0,
                                'start_time': timestamp - timedelta(hours=24),
                                'end_time': timestamp
                            }
                            logging.info(f"Would query nearby events: {nearby_events_query_data}")
                        except Exception as query_error:
                            logging.warning(f"Could not query nearby events: {query_error}")
                    
                    logging.info(f"Applied seismic update: M{magnitude} at {location}")
                
        except Exception as e:
            logging.error(f"Seismic update processing with database failed: {e}")
    
    def enhance_real_time_data_with_external_sources(self, 
                                                   local_data: Dict[str, List],
                                                   region_bbox: Tuple[float, float, float, float],
                                                   correlation_threshold: float = 0.8) -> Dict[str, Any]:
        """Enhance real-time data with external sources for improved accuracy.
        
        Args:
            local_data: Local real-time data (seismic, GPS, etc.)
            region_bbox: Bounding box for external data collection
            correlation_threshold: Minimum correlation for data fusion
            
        Returns:
            Enhanced data with external source integration
        """
        try:
            if not hasattr(self, 'external_connectors'):
                logging.warning("External connectors not available for data enhancement")
                return local_data
            
            enhanced_data = local_data.copy()
            
            # Collect external seismic data to cross-validate local events
            if 'seismic_events' in local_data and self.external_connectors.get('usgs'):
                logging.info("Enhancing seismic data with USGS external sources")
                
                # Get recent earthquake data from USGS
                external_earthquakes = self.external_connectors['usgs'].get_earthquake_data(
                    start_time=datetime.now() - timedelta(hours=6),
                    end_time=datetime.now(),
                    min_latitude=region_bbox[1],
                    max_latitude=region_bbox[3],
                    min_longitude=region_bbox[0],
                    max_longitude=region_bbox[2],
                    min_magnitude=2.0,
                    limit=50
                )
                
                # Cross-correlate and merge with local seismic data
                correlated_events = self._correlate_seismic_data(
                    local_data['seismic_events'], 
                    external_earthquakes, 
                    correlation_threshold
                )
                enhanced_data['seismic_events'] = correlated_events
                enhanced_data['external_seismic_count'] = len(external_earthquakes)
            
            # Enhance with satellite imagery for deformation context
            if 'gps_measurements' in local_data and self.external_connectors.get('nasa'):
                logging.info("Enhancing GPS data with NASA satellite context")
                
                # Get recent satellite data for deformation context
                satellite_data = self.external_connectors['nasa'].search_landsat_data(
                    bbox=region_bbox,
                    start_date=datetime.now() - timedelta(days=7),
                    end_date=datetime.now(),
                    cloud_cover_max=40.0,
                    limit=3
                )
                
                if satellite_data:
                    enhanced_data['satellite_context'] = satellite_data
                    enhanced_data['deformation_confidence'] = self._assess_deformation_confidence(
                        local_data['gps_measurements'], satellite_data)
            
            # Add relevant research context
            if self.external_connectors.get('agu_wiley'):
                # Search for recent relevant research
                region_name = self._infer_region_name(region_bbox)
                recent_articles = self.external_connectors['agu_wiley'].search_geological_articles(
                    query=f"earthquake deformation {region_name}",
                    start_date=datetime.now() - timedelta(days=90),
                    max_results=3
                )
                
                if recent_articles:
                    enhanced_data['research_context'] = recent_articles
                    enhanced_data['scientific_confidence'] = self._calculate_scientific_confidence(recent_articles)
            
            logging.info(f"Enhanced real-time data with {len(enhanced_data) - len(local_data)} external sources")
            return enhanced_data
            
        except Exception as e:
            logging.error(f"External data enhancement failed: {e}")
            return local_data  # Return original data on error
    
    def _correlate_seismic_data(self, local_events: List[Dict], 
                               external_events: List, 
                               threshold: float) -> List[Dict]:
        """Correlate local seismic events with external catalog data.
        
        Args:
            local_events: Local seismic event data
            external_events: External seismic catalog data
            threshold: Correlation threshold
            
        Returns:
            Merged and validated seismic events
        """
        try:
            correlated_events = []
            
            for local_event in local_events:
                local_time = local_event.get('timestamp', datetime.now())
                local_location = local_event.get('location', [0, 0, 0])
                local_magnitude = local_event.get('magnitude', 0)
                
                # Find matching external events
                best_match = None
                best_correlation = 0.0
                
                for ext_record in external_events:
                    if hasattr(ext_record, 'timestamp') and hasattr(ext_record, 'coordinates'):
                        # Calculate temporal correlation (within 10 minutes)
                        time_diff = abs((local_time - ext_record.timestamp).total_seconds())
                        temporal_corr = max(0, 1 - time_diff / 600)  # 10 minutes window
                        
                        # Calculate spatial correlation (within 50 km)
                        if len(local_location) >= 2 and len(ext_record.coordinates) >= 2:
                            from math import sqrt
                            lat_diff = (local_location[1] - ext_record.coordinates[0]) * 111.32  # km per degree
                            lon_diff = (local_location[0] - ext_record.coordinates[1]) * 111.32 * np.cos(np.radians(local_location[1]))
                            distance = sqrt(lat_diff**2 + lon_diff**2)
                            spatial_corr = max(0, 1 - distance / 50)  # 50 km window
                        else:
                            spatial_corr = 0.0
                        
                        # Calculate magnitude correlation
                        ext_magnitude = ext_record.properties.get('magnitude', 0) if hasattr(ext_record, 'properties') else 0
                        mag_diff = abs(local_magnitude - ext_magnitude)
                        magnitude_corr = max(0, 1 - mag_diff / 2)  # 2 magnitude unit window
                        
                        # Overall correlation score
                        correlation = (temporal_corr * 0.4 + spatial_corr * 0.4 + magnitude_corr * 0.2)
                        
                        if correlation > best_correlation and correlation > threshold:
                            best_match = ext_record
                            best_correlation = correlation
                
                # Create enhanced event record
                enhanced_event = local_event.copy()
                if best_match:
                    enhanced_event.update({
                        'external_validation': True,
                        'correlation_score': best_correlation,
                        'external_source': 'USGS',
                        'external_magnitude': best_match.properties.get('magnitude', 0) if hasattr(best_match, 'properties') else 0,
                        'external_location': list(best_match.coordinates[:2]) if hasattr(best_match, 'coordinates') else None,
                        'quality_enhancement': min(1.0, local_event.get('quality', 0.5) + 0.2)  # Boost quality
                    })
                else:
                    enhanced_event.update({
                        'external_validation': False,
                        'correlation_score': 0.0,
                        'quality_note': 'no_external_correlation'
                    })
                
                correlated_events.append(enhanced_event)
            
            return correlated_events
            
        except Exception as e:
            logging.error(f"Seismic correlation failed: {e}")
            return local_events  # Return original events on error
    
    def _assess_deformation_confidence(self, gps_data: List[Dict], satellite_data: List) -> float:
        """Assess confidence in deformation measurements using satellite context.
        
        Args:
            gps_data: GPS measurement data
            satellite_data: Satellite imagery records
            
        Returns:
            Confidence score (0-1)
        """
        try:
            base_confidence = 0.5
            
            # Higher confidence with more GPS stations
            num_stations = len(set(measurement.get('station_id', '') for measurement in gps_data))
            station_factor = min(1.0, num_stations / 10)  # Normalize by 10 stations
            
            # Higher confidence with better satellite coverage
            satellite_quality = 0.0
            if satellite_data:
                avg_cloud_cover = np.mean([record.quality_score for record in satellite_data if hasattr(record, 'quality_score')])
                satellite_quality = avg_cloud_cover
            
            # Combine factors
            confidence = base_confidence + (station_factor * 0.3) + (satellite_quality * 0.2)
            return min(1.0, confidence)
            
        except Exception as e:
            logging.warning(f"Deformation confidence assessment failed: {e}")
            return 0.5  # Default moderate confidence
    
    def _calculate_scientific_confidence(self, articles: List[Dict]) -> float:
        """Calculate scientific confidence based on research articles.
        
        Args:
            articles: Research article metadata
            
        Returns:
            Scientific confidence score (0-1)
        """
        try:
            if not articles:
                return 0.3  # Low confidence without research backing
            
            # Count high-impact journals
            high_impact_journals = ['Journal of Geophysical Research', 'Nature', 'Science', 'Earth and Planetary Science Letters']
            impact_score = sum(1 for article in articles 
                              if any(journal in article.get('journal', '') for journal in high_impact_journals))
            impact_factor = impact_score / len(articles)
            
            # Recent research gets higher confidence
            recent_count = sum(1 for article in articles 
                              if '2024' in article.get('publication_date', '') or '2023' in article.get('publication_date', ''))
            recency_factor = recent_count / len(articles)
            
            # Calculate relevance from keywords
            relevance_scores = [self._calculate_article_relevance(article) for article in articles]
            avg_relevance = np.mean(relevance_scores) if relevance_scores else 0.0
            
            # Combine factors
            confidence = 0.3 + (impact_factor * 0.3) + (recency_factor * 0.2) + (avg_relevance * 0.2)
            return min(1.0, confidence)
            
        except Exception as e:
            logging.warning(f"Scientific confidence calculation failed: {e}")
            return 0.5
    
    def _infer_region_name(self, bbox: Tuple[float, float, float, float]) -> str:
        """Infer region name from bounding box coordinates.
        
        Args:
            bbox: Bounding box (min_lon, min_lat, max_lon, max_lat)
            
        Returns:
            Inferred region name
        """
        center_lat = (bbox[1] + bbox[3]) / 2
        center_lon = (bbox[0] + bbox[2]) / 2
        
        # Simple region inference based on coordinates
        if 32 <= center_lat <= 42 and -125 <= center_lon <= -114:
            return "California"
        elif 58 <= center_lat <= 65 and -155 <= center_lon <= -130:
            return "Alaska"  
        elif 35 <= center_lat <= 49 and -125 <= center_lon <= -67:
            return "Western United States"
        elif -20 <= center_lat <= 20 and 95 <= center_lon <= 141:
            return "Indonesia"
        elif 35 <= center_lat <= 42 and 135 <= center_lon <= 146:
            return "Japan"
        elif -43 <= center_lat <= -34 and 166 <= center_lon <= 179:
            return "New Zealand"
        else:
            return f"Region_{int(center_lat)}N_{int(abs(center_lon))}{'E' if center_lon > 0 else 'W'}"
    
    def _process_seismic_updates(self, seismic_events: List[Dict]):
        """Process real-time seismic event updates (fallback method)."""
        try:
            for event in seismic_events:
                magnitude = event.get('magnitude', 0.0)
                location = event.get('location', [0, 0, 0])
                time = event.get('time', 0)
                
                # Update stress field based on seismic activity
                if magnitude > 4.0:  # Significant event
                    # Adjust model parameters based on seismic activity
                    distance_factor = self._compute_distance_factor(location)
                    stress_adjustment = magnitude * distance_factor * 0.1
                    
                    # Update relevant parameters
                    if 'stress_field' in self.parameters:
                        current_stress = self.parameters.get('stress_field', 1.0)
                        self.parameters['stress_field'] = current_stress + stress_adjustment
                    
                    logging.info(f"Applied seismic update: M{magnitude} at {location}")
                
        except Exception as e:
            logging.error(f"Seismic update processing failed: {e}")
    
    def _process_gps_updates_with_database(self, gps_measurements: List[Dict]):
        """Process real-time GPS measurement updates using database_integration.py."""
        try:
            for measurement in gps_measurements:
                station_id = measurement.get('station_id')
                displacement = measurement.get('displacement', [0, 0, 0])
                uncertainty = measurement.get('uncertainty', [0.001, 0.001, 0.001])
                timestamp = measurement.get('timestamp', datetime.utcnow())
                
                # Store deformation measurement in database using real database integration
                if hasattr(self, 'db_manager') and station_id:
                    try:
                        measurement_data = {
                            'station_id': station_id,
                            'timestamp': timestamp,
                            'displacement_x': displacement[0] if len(displacement) > 0 else 0.0,  # East (mm)
                            'displacement_y': displacement[1] if len(displacement) > 1 else 0.0,  # North (mm)
                            'displacement_z': displacement[2] if len(displacement) > 2 else 0.0,  # Up (mm)
                            'uncertainty_x': uncertainty[0] if len(uncertainty) > 0 else 0.001,
                            'uncertainty_y': uncertainty[1] if len(uncertainty) > 1 else 0.001,
                            'uncertainty_z': uncertainty[2] if len(uncertainty) > 2 else 0.002,
                            'processing_method': measurement.get('processing_method', 'PPP'),
                            'quality_flag': measurement.get('quality_flag', 'GOOD'),
                            'metadata': {
                                'source': 'elastic_inversion_model',
                                'processing_time': datetime.utcnow().isoformat(),
                                'model_version': '2.0'
                            }
                        }
                        
                        # Insert deformation measurement asynchronously
                        import asyncio
                        try:
                            try:
                                loop = asyncio.get_running_loop()
                                future = asyncio.run_coroutine_threadsafe(
                                    self.db_manager.insert_deformation_measurement(measurement_data), loop
                                )
                                future.result(timeout=10)
                            except RuntimeError:
                                asyncio.run(self.db_manager.insert_deformation_measurement(measurement_data))
                            logging.info(f"Stored GPS measurement for station {station_id} in database")
                        except Exception as db_error:
                            logging.warning(f"Could not store GPS measurement in database: {db_error}")
                            
                    except Exception as e:
                        logging.warning(f"Database integration failed for GPS measurement: {e}")
                
                # Update model constraints based on GPS data
                if station_id and 'gps_constraints' not in self.parameters:
                    self.parameters['gps_constraints'] = {}
                
                if station_id:
                    self.parameters['gps_constraints'][station_id] = {
                        'displacement': displacement,
                        'uncertainty': uncertainty,
                        'timestamp': timestamp
                    }
                
                logging.debug(f"Updated GPS constraint for station {station_id} with database integration")
                
        except Exception as e:
            logging.error(f"GPS update processing with database failed: {e}")
    
