    def _update_model_from_geological_structures(self, structures: List[Dict]):
        """Update model parameters based on geological structures."""
        try:
            for structure in structures:
                structure_type = structure.get('type', 'fault')
                
                if structure_type == 'fault':
                    # Update fault-related parameters
                    strike = structure.get('strike')
                    dip = structure.get('dip')
                    
                    if strike is not None and dip is not None:
                        # Update model with fault geometry
                        if 'fault_parameters' not in self.parameters:
                            self.parameters['fault_parameters'] = []
                        
                        fault_param = {
                            'strike': strike,
                            'dip': dip,
                            'geometry': structure.get('geometry'),
                            'properties': structure.get('properties', {})
                        }
                        self.parameters['fault_parameters'].append(fault_param)
                
                logging.debug(f"Updated model parameters for {structure_type}")
                
        except Exception as e:
            logging.error(f"Failed to update model from geological structures: {e}")
    
    def _get_current_time(self) -> str:
        """Get current time as ISO string."""
        from datetime import datetime, timedelta
        return datetime.utcnow().isoformat()
    
    def _process_geological_model_updates_with_database(self, geological_models: Dict):
        """Process geological model updates using database_integration.py."""
        try:
            if 'geological_structures' in geological_models:
                structures = geological_models['geological_structures']
                
                # Store geological structures in database using real database integration
                if hasattr(self, 'db_manager'):
                    for structure in structures:
                        try:
                            structure_data = {
                                'structure_id': structure.get('id', f'struct_{datetime.utcnow().timestamp()}'),
                                'structure_type': structure.get('type', 'fault'),
                                'geometry': structure.get('geometry'),  # WKT or GeoJSON
                                'strike': structure.get('strike'),
                                'dip': structure.get('dip'),
                                'age': structure.get('age'),
                                'lithology': structure.get('lithology'),
                                'properties': structure.get('properties', {}),
                                'metadata': {
                                    'source': 'elastic_inversion_model',
                                    'update_time': datetime.utcnow().isoformat(),
                                    'model_version': '2.0'
                                }
                            }
                            
                            # Would store structure in database (async operation)
                            logging.info(f"Would store geological structure {structure_data['structure_id']} in database")
                            
                        except Exception as e:
                            logging.warning(f"Database integration failed for geological structure: {e}")
                
                # Update model parameters based on geological structures
                self._update_model_from_geological_structures(structures)
            
            if 'crustal_structure' in geological_models:
                structure = geological_models['crustal_structure']
                
                # Update elastic parameters based on crustal structure
                if 'layers' in structure:
                    for layer in structure['layers']:
                        depth_range = layer.get('depth_range', [0, 10000])
                        elastic_params = layer.get('elastic_parameters', {})
                        
                        # Update model parameters for this depth range
                        if 'elastic_layers' not in self.parameters:
                            self.parameters['elastic_layers'] = []
                        
                        self.parameters['elastic_layers'].append({
                            'depth_range': depth_range,
                            'elastic_parameters': elastic_params
                        })
                
                logging.info("Updated crustal structure parameters with database integration")
                
        except Exception as e:
            logging.error(f"Geological model update processing with database failed: {e}")
    
