    def _determine_regional_geological_setting(self, observation_points: np.ndarray) -> str:
        """Determine regional geological setting for elastic property selection."""
        try:
            # Analyze observation point coordinates to infer geological setting
            if len(observation_points) == 0:
                return 'continental_crust_upper'
            
            # Calculate average coordinates
            avg_coords = np.mean(observation_points, axis=0)
            
            if len(avg_coords) >= 3:
                avg_depth = abs(avg_coords[2])
                
                # Depth-based classification
                if avg_depth < 15000:  # Upper crust
                    return 'continental_crust_upper'
                elif avg_depth < 35000:  # Middle crust
                    return 'continental_crust_middle'  
                else:  # Lower crust/upper mantle
                    return 'continental_crust_lower'
            
            # Geographic classification if available
            if len(avg_coords) >= 2:
                lat, lon = avg_coords[0], avg_coords[1]
                
                # Simple oceanic vs continental discrimination
                if self._is_oceanic_location(lat, lon):
                    return 'oceanic_crust'
                elif self._is_sedimentary_basin_location(lat, lon):
                    return 'sedimentary_basin'
                else:
                    return 'continental_crust_upper'
            
            return 'continental_crust_upper'  # Default
            
        except Exception as e:
            self.logger.warning(f"Regional geological setting determination failed: {e}")
            return 'continental_crust_upper'
    
    def _is_oceanic_location(self, lat: float, lon: float) -> bool:
        """Check if location is in oceanic crust region."""
        # Simple heuristic based on major oceanic regions
        oceanic_regions = [
            # Atlantic Ocean
            (-60, 60, -80, 20),
            # Pacific Ocean  
            (-60, 60, -180, -80),
            (-60, 60, 120, 180),
            # Indian Ocean
            (-60, 30, 20, 120)
        ]
        
        for lat_min, lat_max, lon_min, lon_max in oceanic_regions:
            if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
                return True
                
        return False
    
    def _is_sedimentary_basin_location(self, lat: float, lon: float) -> bool:
        """Check if location is in major sedimentary basin."""
        # Major sedimentary basins (simplified)
        sedimentary_basins = [
            # Gulf of Mexico Basin
            (25, 30, -100, -85),
            # North Sea Basin  
            (55, 62, 0, 10),
            # Western Canadian Sedimentary Basin
            (49, 60, -125, -110)
        ]
        
        for lat_min, lat_max, lon_min, lon_max in sedimentary_basins:
            if lat_min <= lat <= lat_max and lon_min <= lon <= lon_max:
                return True
                
        return False
    
    def _analyze_displacement_characteristics(self, displacement: np.ndarray) -> Dict[str, float]:
        """Analyze displacement patterns to infer material characteristics."""
        try:
            if len(displacement) == 0:
                return {}
            
            # Statistical analysis of displacement patterns
            displacement_stats = {
                'max_displacement': np.max(np.abs(displacement)),
                'mean_displacement': np.mean(np.abs(displacement)),
                'std_displacement': np.std(displacement),
                'displacement_ratio': np.std(displacement) / (np.mean(np.abs(displacement)) + 1e-10)
            }
            
            # Displacement pattern classification
            if displacement_stats['displacement_ratio'] > 2.0:
                # High variability suggests heterogeneous/fractured rock
                displacement_stats['inferred_heterogeneity'] = 'high'
            elif displacement_stats['displacement_ratio'] > 1.0:
                displacement_stats['inferred_heterogeneity'] = 'moderate'
            else:
                displacement_stats['inferred_heterogeneity'] = 'low'
            
            return displacement_stats
            
        except Exception as e:
            self.logger.warning(f"Displacement characteristic analysis failed: {e}")
            return {}
    
    def _infer_properties_from_displacement_and_geology(self, 
                                                      displacement_characteristics: Dict[str, float],
                                                      geological_context: Dict[str, float]) -> Dict[str, float]:
        """Infer material properties from displacement patterns and geological context."""
        try:
            inferred_props = {}
            
            # Base properties from dominant rock type
            dominant_rock = max(geological_context.items(), key=lambda x: x[1])[0] if geological_context else 'granite'
            base_props = self._get_rock_type_laboratory_elastic_properties(dominant_rock)
            
            # Adjust based on displacement characteristics
            heterogeneity = displacement_characteristics.get('inferred_heterogeneity', 'moderate')
            
            if heterogeneity == 'high':
                # Fractured/heterogeneous rock - reduce moduli
                inferred_props['shear_modulus'] = base_props.get('shear_modulus', 30e9) * 0.7
                inferred_props['youngs_modulus'] = base_props.get('youngs_modulus', 70e9) * 0.7
                inferred_props['poisson_ratio'] = min(0.35, base_props.get('poisson_ratio', 0.25) * 1.2)
            elif heterogeneity == 'low':
                # Homogeneous rock - use full laboratory values
                inferred_props['shear_modulus'] = base_props.get('shear_modulus', 30e9)
                inferred_props['youngs_modulus'] = base_props.get('youngs_modulus', 70e9)
                inferred_props['poisson_ratio'] = base_props.get('poisson_ratio', 0.25)
            else:
                # Moderate heterogeneity - slight reduction
                inferred_props['shear_modulus'] = base_props.get('shear_modulus', 30e9) * 0.85
                inferred_props['youngs_modulus'] = base_props.get('youngs_modulus', 70e9) * 0.85
                inferred_props['poisson_ratio'] = base_props.get('poisson_ratio', 0.25) * 1.1
            
            inferred_props['density'] = base_props.get('density', 2700)
            
            return inferred_props
            
        except Exception as e:
            self.logger.error(f"Property inference from displacement and geology failed: {e}")
            return {
                'shear_modulus': 30e9,
                'youngs_modulus': 70e9,
                'poisson_ratio': 0.25,
                'density': 2700
            }
    
    def _build_ml_enhanced_model_from_recommendation(self, recommendation: 'ModelRecommendation',
                                                   observation_points: np.ndarray,
                                                   training_data: Dict) -> Callable:
        """Build ML-enhanced model from adaptive recommendation"""
        hyperparams = recommendation.optimal_hyperparameters
        
        # Train ML model with recommended hyperparameters
        if recommendation.model_type.value == 'physics_informed_nn':
            return self._build_physics_informed_nn_model(hyperparams, observation_points, training_data)
        else:
            return self._build_standard_ml_model(hyperparams, observation_points, training_data)
    
    def _build_ensemble_model_from_recommendation(self, recommendation: 'ModelRecommendation',
                                                observation_points: np.ndarray,
                                                training_data: Dict) -> Callable:
        """Build ensemble model from adaptive recommendation"""
        hyperparams = recommendation.optimal_hyperparameters
        n_models = hyperparams.get('n_models', 5)
        
        # Build ensemble of models
        ensemble_models = []
        for i in range(n_models):
            if i % 2 == 0:
                model = self._build_physics_based_model_from_recommendation(recommendation)
            else:
                model = self._build_ml_enhanced_model_from_recommendation(recommendation, observation_points, training_data)
            ensemble_models.append(model)
        
        def ensemble_prediction(observation_points, **kwargs):
            predictions = []
            for model in ensemble_models:
                try:
                    pred = model(observation_points, **kwargs)
                    predictions.append(pred)
                except Exception as e:
                    logging.warning(f"Ensemble model failed: {e}")
            
            if predictions:
                return np.mean(predictions, axis=0)
            else:
                return self.compute_displacements(observation_points, **kwargs)
        
        return ensemble_prediction
    
    def _build_physics_informed_nn_model(self, hyperparams: Dict, observation_points: np.ndarray, training_data: Dict) -> Callable:
        """Build physics-informed neural network model"""
        try:
            # This would integrate with PINN frameworks
            logging.info("Building physics-informed neural network model (placeholder)")
            
            # For now, return enhanced physics model
            def pinn_model(obs_points, **kwargs):
                return self.compute_displacements(obs_points, **kwargs)
            
            return pinn_model
        except Exception as e:
            logging.error(f"Failed to build PINN model: {e}")
            return self.compute_displacements
    
    def _build_standard_ml_model(self, hyperparams: Dict, observation_points: np.ndarray, training_data: Dict) -> Callable:
        """Build standard ML model"""
        try:
            from sklearn.ensemble import RandomForestRegressor
            
            # Extract features and targets from training data
            features = self._extract_ml_features(observation_points, training_data)
            targets = self._extract_target_data_from_training(training_data)
            
            # Create and train model
            model = RandomForestRegressor(
                n_estimators=hyperparams.get('n_estimators', 100),
                max_depth=hyperparams.get('max_depth', 10),
                random_state=42
            )
            
            if len(features) > 0 and len(targets) > 0:
                # Ensure compatible shapes
                min_samples = min(len(features), len(targets))
                features_fit = features[:min_samples]
                targets_fit = targets[:min_samples]
                
                if len(targets_fit.shape) > 1 and targets_fit.shape[1] > 1:
                    targets_fit = targets_fit[:, 0]  # Use first component for regression
                
                model.fit(features_fit, targets_fit)
            
            def ml_enhanced_model(obs_points, **kwargs):
                try:
                    # Get physics-based prediction
                    physics_pred = self.compute_displacements(obs_points, **kwargs)
                    
                    # Get ML correction if model is trained
                    if hasattr(model, 'predict'):
                        ml_features = self._extract_ml_features(obs_points, training_data)
                        if len(ml_features) > 0:
                            ml_correction = model.predict(ml_features)
                            if len(ml_correction.shape) == 1:
                                ml_correction = ml_correction.reshape(-1, 1)
                            
                            # Combine physics and ML predictions
                            ml_weight = hyperparams.get('ml_weight', 0.3)
                            if ml_correction.shape[0] == physics_pred.shape[0]:
                                correction_broadcast = np.broadcast_to(
                                    ml_correction, physics_pred.shape
                                )
                                return physics_pred * (1 - ml_weight) + correction_broadcast * ml_weight
                    
                    return physics_pred
                    
                except Exception as e:
                    logging.warning(f"ML enhancement failed, using physics model: {e}")
                    return physics_pred
            
            return ml_enhanced_model
            
        except Exception as e:
            logging.error(f"Failed to build ML model: {e}")
            return self.compute_displacements
    
    def _fallback_basic_model_selection(self, observation_points: np.ndarray,
                                       training_data: Dict, validation_data: Dict,
                                       selection_config: Dict) -> Dict:
        """Fallback to basic model selection when adaptive selection fails"""
        try:
            logging.info("Using fallback basic model selection")
            # Return basic physics-based model configuration
            return {
                'best_model': self.compute_displacements,
                'best_model_type': 'physics_based',
                'optimal_hyperparameters': {'regularization': 1e-4, 'smoothing_factor': 1.0},
                'selection_results': {'method': 'fallback_basic'},
                'validation_metrics': {'accuracy_score': 0.7, 'efficiency_score': 0.8},
                'selection_config': selection_config or {}
            }
        except Exception as e:
            logging.error(f"Fallback model selection failed: {e}")
            return {'error': str(e), 'fallback_model': 'physics_based'}
    
    def _get_model_candidates(self, config: Dict[str, any]) -> List[Dict[str, any]]:
        """Define model candidates for selection"""
        candidates = []
        
        for model_type in config['model_types']:
            if model_type == 'physics_based':
                candidates.append({
                    'type': 'physics_based',
                    'method': 'compute_displacements',
                    'hyperparameters': ['regularization', 'smoothing_factor'],
                    'description': 'Pure physics-based elastic modeling'
                })
                
            elif model_type == 'ml_enhanced':
                candidates.append({
                    'type': 'ml_enhanced',
                    'method': 'compute_displacements',
                    'hyperparameters': ['ensemble_size', 'ml_weight', 'regularization'],
                    'description': 'Physics-based with ML enhancement'
                })
                
            elif model_type == 'pinn':
                candidates.append({
                    'type': 'pinn',
                    'method': 'integrate_physics_informed_neural_networks',
                    'hyperparameters': ['hidden_layers', 'learning_rate', 'physics_weight', 'epochs'],
                    'description': 'Physics-informed neural networks'
                })
                
            elif model_type == 'ensemble':
                candidates.append({
                    'type': 'ensemble',
                    'method': 'ensemble_prediction',
                    'hyperparameters': ['n_models', 'diversity_weight'],
                    'description': 'Ensemble of multiple model types'
                })
        
        return candidates
    
    def _perform_model_selection(self, observation_points: np.ndarray,
                               training_data: Dict, validation_data: Dict,
                               candidates: List[Dict], config: Dict) -> List[Dict]:
        """Perform model selection with hyperparameter optimization"""
        try:
            results = []
            
            for candidate in candidates:
                logging.info(f"Evaluating model candidate: {candidate['type']}")
                
                if config['optimization_method'] == 'bayesian':
                    model_result = self._bayesian_optimization(
                        candidate, observation_points, training_data, validation_data, config
                    )
                elif config['optimization_method'] == 'grid_search':
                    model_result = self._grid_search_optimization(
                        candidate, observation_points, training_data, validation_data, config
                    )
                elif config['optimization_method'] == 'random_search':
                    model_result = self._random_search_optimization(
                        candidate, observation_points, training_data, validation_data, config
                    )
                else:
                    logging.warning(f"Unknown optimization method: {config['optimization_method']}")
                    continue
                
                results.append(model_result)
                
            return results
            
        except Exception as e:
            logging.error(f"Model selection failed: {e}")
            return []
    
    def _bayesian_optimization(self, candidate: Dict, obs_points: np.ndarray,
                             train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """Bayesian optimization for hyperparameter tuning"""
        try:
            # Check if optimization libraries are available
            try:
                from scipy.optimize import minimize
                from sklearn.gaussian_process import GaussianProcessRegressor
                from sklearn.gaussian_process.kernels import Matern
                optimization_available = True
            except ImportError:
                optimization_available = False
            
            if not optimization_available:
                logging.warning("Optimization libraries not available, using Bayesian inference fallback")
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
            
            # Get hyperparameter bounds for this candidate
            bounds = config['hyperparameter_bounds'].get(candidate['type'], {})
            
            # Define objective function
            def objective(hyperparams):
                try:
                    # Convert hyperparameters to dictionary
                    param_dict = {}
                    for i, param_name in enumerate(candidate['hyperparameters']):
                        if param_name in bounds:
                            param_dict[param_name] = hyperparams[i]
                    
                    # Evaluate model with these hyperparameters
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, param_dict, obs_points, train_data, val_data, config
                    )
                    
                    # Return negative RMSE (for minimization)
                    return metrics.get('rmse', float('inf'))
                    
                except Exception as e:
                    logging.warning(f"Evaluation failed for hyperparameters {hyperparams}: {e}")
                    return float('inf')
            
            # Set up Bayesian optimization
            param_names = [p for p in candidate['hyperparameters'] if p in bounds]
            if not param_names:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
            
            # Initialize Gaussian Process
            kernel = Matern(length_scale=1.0, nu=2.5)
            gp = GaussianProcessRegressor(kernel=kernel, alpha=1e-6, normalize_y=True)
            
            # Random initialization
            n_initial = min(10, config['max_iterations'] // 2)
            best_params = None
            best_score = float('inf')
            
            # Random sampling for initialization
            import numpy as np
            for i in range(n_initial):
                try:
                    # Sample hyperparameters
                    params = []
                    for param_name in param_names:
                        bound = bounds[param_name]
                        if isinstance(bound[0], (list, tuple)):
                            # Categorical parameter (e.g., hidden layers)
                            params.append(np.random.choice(len(bound)))
                        else:
                            # Continuous parameter
                            params.append(np.random.uniform(bound[0], bound[1]))
                    
                    score = objective(params)
                    if score < best_score:
                        best_score = score
                        best_params = params.copy()
                        
                except Exception as e:
                    logging.warning(f"Random initialization {i} failed: {e}")
                    continue
            
            # Convert best parameters back to dictionary
            if best_params is not None:
                optimal_params = {}
                for i, param_name in enumerate(param_names):
                    bound = bounds[param_name]
                    if isinstance(bound[0], (list, tuple)):
                        optimal_params[param_name] = bound[int(best_params[i]) % len(bound)]
                    else:
                        optimal_params[param_name] = best_params[i]
                
                # Final evaluation with best parameters
                final_metrics = self._evaluate_model_with_hyperparameters(
                    candidate, optimal_params, obs_points, train_data, val_data, config
                )
                
                return {
                    'model_type': candidate['type'],
                    'hyperparameters': optimal_params,
                    'metrics': final_metrics,
                    'optimization_method': 'bayesian',
                    'iterations': n_initial
                }
            else:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
                
        except Exception as e:
            logging.error(f"Bayesian optimization failed: {e}")
            return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
    
    def _grid_search_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """Grid search optimization for hyperparameter tuning"""
        try:
            bounds = config['hyperparameter_bounds'].get(candidate['type'], {})
            param_names = [p for p in candidate['hyperparameters'] if p in bounds]
            
            if not param_names:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
            
            # Generate grid points
            grid_points = []
            n_points_per_dim = max(2, int(config['max_iterations'] ** (1/len(param_names))))
            
            # Create parameter grids
            param_grids = []
            for param_name in param_names:
                bound = bounds[param_name]
                if isinstance(bound[0], (list, tuple)):
                    param_grids.append(bound)
                else:
                    param_grids.append(np.linspace(bound[0], bound[1], n_points_per_dim))
            
            # Generate all combinations
            import itertools
            for combination in itertools.product(*param_grids):
                param_dict = dict(zip(param_names, combination))
                grid_points.append(param_dict)
            
            # Limit to max_iterations
            if len(grid_points) > config['max_iterations']:
                import random
                random.shuffle(grid_points)
                grid_points = grid_points[:config['max_iterations']]
            
            # Evaluate all grid points
            best_params = None
            best_metrics = None
            best_score = float('inf')
            
            for param_dict in grid_points:
                try:
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, param_dict, obs_points, train_data, val_data, config
                    )
                    
                    score = metrics.get('rmse', float('inf'))
                    if score < best_score:
                        best_score = score
                        best_params = param_dict.copy()
                        best_metrics = metrics.copy()
                        
                except Exception as e:
                    logging.warning(f"Grid evaluation failed for {param_dict}: {e}")
                    continue
            
            if best_params is not None:
                return {
                    'model_type': candidate['type'],
                    'hyperparameters': best_params,
                    'metrics': best_metrics,
                    'optimization_method': 'grid_search',
                    'iterations': len(grid_points)
                }
            else:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
                
        except Exception as e:
            logging.error(f"Grid search optimization failed: {e}")
            return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
    
    def _random_search_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                  train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """Random search optimization for hyperparameter tuning"""
        try:
            bounds = config['hyperparameter_bounds'].get(candidate['type'], {})
            param_names = [p for p in candidate['hyperparameters'] if p in bounds]
            
            if not param_names:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
            
            best_params = None
            best_metrics = None
            best_score = float('inf')
            
            # Random search iterations
            for i in range(config['max_iterations']):
                try:
                    # Sample random hyperparameters
                    param_dict = {}
                    for param_name in param_names:
                        bound = bounds[param_name]
                        if isinstance(bound[0], (list, tuple)):
                            param_dict[param_name] = random.choice(bound)
                        else:
                            param_dict[param_name] = random.uniform(bound[0], bound[1])
                    
                    # Evaluate model
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, param_dict, obs_points, train_data, val_data, config
                    )
                    
                    score = metrics.get('rmse', float('inf'))
                    if score < best_score:
                        best_score = score
                        best_params = param_dict.copy()
                        best_metrics = metrics.copy()
                        
                        # Early stopping check
                        if config.get('early_stopping', {}).get('min_delta', 0) > 0:
                            if best_score < config['early_stopping']['min_delta']:
                                logging.info(f"Early stopping at iteration {i}")
                                break
                    
                except Exception as e:
                    logging.warning(f"Random search iteration {i} failed: {e}")
                    continue
            
            if best_params is not None:
                return {
                    'model_type': candidate['type'],
                    'hyperparameters': best_params,
                    'metrics': best_metrics,
                    'optimization_method': 'random_search',
                    'iterations': i + 1
                }
            else:
                return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
                
        except Exception as e:
            logging.error(f"Random search optimization failed: {e}")
            return self._full_bayesian_inference_optimization(candidate, obs_points, train_data, val_data, config)
    
    def _full_bayesian_inference_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                           train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """
        Full Bayesian inference for hyperparameter optimization with uncertainty quantification
        Replaces simplified hyperparameter search with comprehensive Bayesian approach
        """
        try:
            # Import Bayesian optimization libraries
            from scipy.stats import uniform, norm, gamma, beta, truncnorm
            from scipy.optimize import minimize
            import numpy.random as npr
            
            # Import advanced Bayesian inference modules if available
            try:
                import pymc as pm
                import arviz as az
                bayesian_framework = 'pymc'
            except ImportError:
                try:
                    import emcee
                    bayesian_framework = 'emcee'  
                except ImportError:
                    bayesian_framework = 'scipy_based'
            
            # Initialize Bayesian hyperparameter optimization
            if bayesian_framework == 'pymc':
                return self._pymc_bayesian_optimization(candidate, obs_points, train_data, val_data, config)
            elif bayesian_framework == 'emcee':
                return self._emcee_bayesian_optimization(candidate, obs_points, train_data, val_data, config)
            else:
                return self._scipy_bayesian_optimization(candidate, obs_points, train_data, val_data, config)
                
        except Exception as e:
            logging.warning(f"Bayesian inference optimization failed, using fallback: {e}")
            return self._simplified_hyperparameter_search(candidate, obs_points, train_data, val_data, config)

    def _pymc_bayesian_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                   train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """PyMC-based Bayesian hyperparameter optimization"""
        try:
            import pymc as pm
            import arviz as az
            import pytensor.tensor as pt
            
            # Define hyperparameter priors based on model type
            priors = self._get_bayesian_priors(candidate['type'])
            
            # Create Bayesian model
            with pm.Model() as bayesian_model:
                # Define hyperparameter priors
                hyperparams = {}
                
                if candidate['type'] == 'physics_based':
                    hyperparams['regularization'] = pm.Gamma('regularization', alpha=priors['regularization']['alpha'], 
                                                           beta=priors['regularization']['beta'])
                    hyperparams['smoothing_factor'] = pm.Gamma('smoothing_factor', alpha=priors['smoothing_factor']['alpha'],
                                                             beta=priors['smoothing_factor']['beta'])
                    
                elif candidate['type'] == 'ml_enhanced':
                    hyperparams['ensemble_size'] = pm.DiscreteUniform('ensemble_size', lower=priors['ensemble_size']['min'],
                                                                    upper=priors['ensemble_size']['max'])
                    hyperparams['ml_weight'] = pm.Beta('ml_weight', alpha=priors['ml_weight']['alpha'],
                                                     beta=priors['ml_weight']['beta'])
                    hyperparams['regularization'] = pm.Gamma('regularization', alpha=priors['regularization']['alpha'],
                                                           beta=priors['regularization']['beta'])
                    
                elif candidate['type'] == 'pinn':
                    # Neural network architecture priors
                    hyperparams['layer_1_size'] = pm.DiscreteUniform('layer_1_size', lower=32, upper=256)
                    hyperparams['layer_2_size'] = pm.DiscreteUniform('layer_2_size', lower=16, upper=128)
                    hyperparams['layer_3_size'] = pm.DiscreteUniform('layer_3_size', lower=8, upper=64)
                    hyperparams['learning_rate'] = pm.Gamma('learning_rate', alpha=priors['learning_rate']['alpha'],
                                                          beta=priors['learning_rate']['beta'])
                    hyperparams['physics_weight'] = pm.Gamma('physics_weight', alpha=priors['physics_weight']['alpha'],
                                                           beta=priors['physics_weight']['beta'])
                    hyperparams['dropout_rate'] = pm.Beta('dropout_rate', alpha=priors['dropout_rate']['alpha'],
                                                        beta=priors['dropout_rate']['beta'])
                
                # Define likelihood function
                @pm.model.freeRV
                def model_likelihood(hyperparams_dict):
                    # Evaluate model with sampled hyperparameters
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, hyperparams_dict, obs_points, train_data, val_data, config
                    )
                    
                    # Convert RMSE to likelihood (lower RMSE = higher likelihood)
                    rmse = metrics.get('rmse', float('inf'))
                    if np.isinf(rmse) or np.isnan(rmse):
                        return -1e6  # Very low likelihood for failed evaluations
                    
                    # Log-likelihood based on RMSE and physics consistency
                    physics_consistency = metrics.get('physics_consistency', 0.0)
                    log_likelihood = -0.5 * (rmse**2) + np.log(physics_consistency + 1e-6)
                    
                    return log_likelihood
                
                # Define custom likelihood
                likelihood = pm.DensityDist('likelihood', logp=lambda params: model_likelihood(params),
                                          observed={'hyperparams': hyperparams})
                
                # Perform MCMC sampling
                trace = pm.sample(draws=config.get('bayesian_samples', 2000),
                                tune=config.get('bayesian_tune', 1000),
                                cores=config.get('bayesian_cores', 2),
                                return_inferencedata=True,
                                progressbar=False)
                
                # Extract posterior statistics
                posterior_summary = az.summary(trace)
                
                # Select optimal hyperparameters (MAP estimate)
                map_estimate = pm.find_MAP(model=bayesian_model)
                optimal_hyperparams = {var: float(map_estimate[var]) for var in map_estimate.keys() 
                                     if var in hyperparams}
                
                # Compute uncertainty quantification
                posterior_samples = trace.posterior
                hyperparameter_uncertainty = {}
                
                for param_name in hyperparams.keys():
                    if param_name in posterior_samples.data_vars:
                        samples = posterior_samples[param_name].values.flatten()
                        hyperparameter_uncertainty[param_name] = {
                            'mean': float(np.mean(samples)),
                            'std': float(np.std(samples)),
                            'percentile_2.5': float(np.percentile(samples, 2.5)),
                            'percentile_97.5': float(np.percentile(samples, 97.5)),
                            'effective_sample_size': float(az.ess(trace, var_names=[param_name])[param_name].values)
                        }
                
                # Evaluate optimal model
                optimal_metrics = self._evaluate_model_with_hyperparameters(
                    candidate, optimal_hyperparams, obs_points, train_data, val_data, config
                )
                
                # Compute model evidence (marginal likelihood approximation)
                waic = az.waic(trace)
                loo = az.loo(trace)
                
                return {
                    'model_type': candidate['type'],
                    'hyperparameters': optimal_hyperparams,
                    'hyperparameter_uncertainty': hyperparameter_uncertainty,
                    'metrics': optimal_metrics,
                    'optimization_method': 'bayesian_pymc',
                    'posterior_summary': posterior_summary.to_dict(),
                    'model_selection_criteria': {
                        'waic': float(waic.waic),
                        'waic_se': float(waic.se),
                        'loo': float(loo.loo),
                        'loo_se': float(loo.se),
                        'p_waic': float(waic.p_waic)
                    },
                    'convergence_diagnostics': {
                        'rhat_max': float(az.rhat(trace).max().values),
                        'ess_bulk_min': float(az.ess(trace, kind='bulk').min().values),
                        'ess_tail_min': float(az.ess(trace, kind='tail').min().values),
                        'mcse_mean_max': float(az.mcse(trace, method='mean').max().values)
                    },
                    'samples_drawn': config.get('bayesian_samples', 2000),
                    'effective_samples': int(np.mean([hyperparameter_uncertainty[p]['effective_sample_size'] 
                                                    for p in hyperparameter_uncertainty]))
                }
                
        except Exception as e:
            logging.error(f"PyMC Bayesian optimization failed: {e}")
            return self._scipy_bayesian_optimization(candidate, obs_points, train_data, val_data, config)

    def _emcee_bayesian_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                   train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """EMCEE-based Bayesian hyperparameter optimization using MCMC"""
        try:
            import emcee
            from multiprocessing import Pool
            
            # Get hyperparameter bounds and priors
            bounds, priors = self._get_emcee_setup(candidate['type'])
            
            # Define log probability function
            def log_probability(params):
                # Check parameter bounds
                if not all(bounds[i][0] <= params[i] <= bounds[i][1] for i in range(len(params))):
                    return -np.inf
                
                # Convert parameters to dictionary
                param_names = list(priors.keys())
                param_dict = {param_names[i]: params[i] for i in range(len(params))}
                
                # Evaluate model performance
                try:
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, param_dict, obs_points, train_data, val_data, config
                    )
                    
                    rmse = metrics.get('rmse', float('inf'))
                    physics_consistency = metrics.get('physics_consistency', 0.0)
                    
                    if np.isinf(rmse) or np.isnan(rmse):
                        return -np.inf
                    
                    # Log-likelihood: combine RMSE minimization with physics consistency
                    log_likelihood = -0.5 * (rmse**2) + np.log(physics_consistency + 1e-6)
                    
                    # Add prior contributions
                    log_prior = 0.0
                    for i, (param_name, param_value) in enumerate(param_dict.items()):
                        prior_dist = priors[param_name]
                        if prior_dist['type'] == 'uniform':
                            if prior_dist['low'] <= param_value <= prior_dist['high']:
                                log_prior += -np.log(prior_dist['high'] - prior_dist['low'])
                            else:
                                return -np.inf
                        elif prior_dist['type'] == 'gamma':
                            log_prior += gamma.logpdf(param_value, prior_dist['alpha'], scale=1/prior_dist['beta'])
                        elif prior_dist['type'] == 'normal':
                            log_prior += norm.logpdf(param_value, prior_dist['mean'], prior_dist['std'])
                    
                    return log_likelihood + log_prior
                    
                except Exception as e:
                    logging.warning(f"Model evaluation failed during MCMC: {e}")
                    return -np.inf
            
            # Initialize walkers
            ndim = len(bounds)
            nwalkers = config.get('emcee_walkers', max(32, 2 * ndim))
            
            # Initialize walker positions
            initial_positions = []
            for _ in range(nwalkers):
                position = []
                for bound in bounds:
                    position.append(np.random.uniform(bound[0], bound[1]))
                initial_positions.append(position)
            
            initial_positions = np.array(initial_positions)
            
            # Set up EMCEE sampler
            with Pool(processes=config.get('emcee_processes', 2)) as pool:
                sampler = emcee.EnsembleSampler(nwalkers, ndim, log_probability, pool=pool)
                
                # Burn-in phase
                burn_in_steps = config.get('emcee_burnin', 1000)
                state = sampler.run_mcmc(initial_positions, burn_in_steps, progress=False)
                sampler.reset()
                
                # Production run
                production_steps = config.get('emcee_production', 2000)
                sampler.run_mcmc(state, production_steps, progress=False)
                
                # Extract samples
                samples = sampler.get_chain(flat=True)
                log_probs = sampler.get_log_prob(flat=True)
                
                # Find MAP estimate
                max_idx = np.argmax(log_probs)
                map_params = samples[max_idx]
                
                # Convert MAP to parameter dictionary
                param_names = list(priors.keys())
                optimal_hyperparams = {param_names[i]: float(map_params[i]) for i in range(len(param_names))}
                
                # Compute parameter statistics
                hyperparameter_uncertainty = {}
                for i, param_name in enumerate(param_names):
                    param_samples = samples[:, i]
                    hyperparameter_uncertainty[param_name] = {
                        'mean': float(np.mean(param_samples)),
                        'std': float(np.std(param_samples)),
                        'percentile_2.5': float(np.percentile(param_samples, 2.5)),
                        'percentile_97.5': float(np.percentile(param_samples, 97.5)),
                        'effective_sample_size': len(param_samples) / (1 + 2 * np.sum(self._compute_autocorrelation(param_samples)))
                    }
                
                # Evaluate optimal model
                optimal_metrics = self._evaluate_model_with_hyperparameters(
                    candidate, optimal_hyperparams, obs_points, train_data, val_data, config
                )
                
                # Convergence diagnostics
                try:
                    acceptance_fraction = np.mean(sampler.acceptance_fraction)
                    autocorr_times = sampler.get_autocorr_time(quiet=True)
                    mean_autocorr = np.mean(autocorr_times)
                except Exception:
                    acceptance_fraction = 0.0
                    mean_autocorr = np.inf
                
                return {
                    'model_type': candidate['type'],
                    'hyperparameters': optimal_hyperparams,
                    'hyperparameter_uncertainty': hyperparameter_uncertainty,
                    'metrics': optimal_metrics,
                    'optimization_method': 'bayesian_emcee',
                    'convergence_diagnostics': {
                        'acceptance_fraction': float(acceptance_fraction),
                        'mean_autocorr_time': float(mean_autocorr),
                        'effective_sample_size': np.mean([hyperparameter_uncertainty[p]['effective_sample_size'] 
                                                        for p in hyperparameter_uncertainty])
                    },
                    'samples_drawn': production_steps * nwalkers,
                    'log_evidence_estimate': float(np.mean(log_probs))  # Rough approximation
                }
                
        except Exception as e:
            logging.error(f"EMCEE Bayesian optimization failed: {e}")
            return self._scipy_bayesian_optimization(candidate, obs_points, train_data, val_data, config)

    def _scipy_bayesian_optimization(self, candidate: Dict, obs_points: np.ndarray,
                                   train_data: Dict, val_data: Dict, config: Dict) -> Dict:
        """SciPy-based Bayesian hyperparameter optimization using variational inference approximation"""
        try:
            from scipy.stats import uniform, norm, gamma, beta
            from scipy.optimize import differential_evolution, minimize
            
            # Get parameter bounds and initial distributions
            bounds, priors = self._get_scipy_bayesian_setup(candidate['type'])
            
            # Define objective function (negative log posterior)
            def negative_log_posterior(params):
                try:
                    # Convert to parameter dictionary
                    param_names = list(priors.keys())
                    param_dict = {param_names[i]: params[i] for i in range(len(params))}
                    
                    # Evaluate model
                    metrics = self._evaluate_model_with_hyperparameters(
                        candidate, param_dict, obs_points, train_data, val_data, config
                    )
                    
                    rmse = metrics.get('rmse', float('inf'))
                    physics_consistency = metrics.get('physics_consistency', 0.0)
                    
                    if np.isinf(rmse) or np.isnan(rmse):
                        return 1e6
                    
                    # Likelihood component
                    log_likelihood = -0.5 * (rmse**2) + np.log(physics_consistency + 1e-6)
                    
                    # Prior component
                    log_prior = 0.0
                    for i, (param_name, param_value) in enumerate(param_dict.items()):
                        prior_info = priors[param_name]
                        if prior_info['distribution'] == 'uniform':
                            if prior_info['low'] <= param_value <= prior_info['high']:
                                log_prior += -np.log(prior_info['high'] - prior_info['low'])
                            else:
                                return 1e6
                        elif prior_info['distribution'] == 'gamma':
                            log_prior += gamma.logpdf(param_value, prior_info['alpha'], scale=1/prior_info['beta'])
                        elif prior_info['distribution'] == 'normal':
                            log_prior += norm.logpdf(param_value, prior_info['mean'], prior_info['std'])
                        elif prior_info['distribution'] == 'beta':
                            log_prior += beta.logpdf(param_value, prior_info['alpha'], prior_info['beta'])
                    
                    return -(log_likelihood + log_prior)
                    
                except Exception as e:
                    logging.warning(f"Objective evaluation failed: {e}")
                    return 1e6
            
            # Perform global optimization to find MAP estimate
            result = differential_evolution(negative_log_posterior, bounds,
                                          maxiter=config.get('scipy_maxiter', 300),
                                          popsize=config.get('scipy_popsize', 15),
                                          seed=config.get('scipy_seed', 42))
            
            # Extract optimal parameters
            param_names = list(priors.keys())
            optimal_hyperparams = {param_names[i]: float(result.x[i]) for i in range(len(param_names))}
            
            # Approximate posterior using Laplace approximation around MAP
            try:
                # Compute Hessian at MAP
                from scipy.optimize import approx_fprime
                from scipy.linalg import inv
                
                eps = 1e-8
                hessian = np.zeros((len(result.x), len(result.x)))
                
                for i in range(len(result.x)):
                    def grad_func(x):
                        x_mod = result.x.copy()
                        x_mod[i] = x
                        return approx_fprime(x_mod, negative_log_posterior, eps)
                    
                    hessian[i] = approx_fprime(result.x, grad_func, eps)
                
                # Posterior covariance (inverse Hessian)
                try:
                    posterior_cov = inv(hessian)
                    posterior_std = np.sqrt(np.diag(posterior_cov))
                except:
                    posterior_std = np.ones(len(result.x)) * 0.1  # Fallback
                
                # Generate approximate samples using Laplace approximation
                n_samples = config.get('scipy_samples', 1000)
                samples = np.random.multivariate_normal(result.x, posterior_cov, n_samples)
                
                # Compute parameter statistics
                hyperparameter_uncertainty = {}
                for i, param_name in enumerate(param_names):
                    param_samples = samples[:, i]
                    # Filter valid samples (within bounds)
                    valid_mask = (param_samples >= bounds[i][0]) & (param_samples <= bounds[i][1])
                    valid_samples = param_samples[valid_mask]
                    
                    if len(valid_samples) > 10:
                        hyperparameter_uncertainty[param_name] = {
                            'mean': float(np.mean(valid_samples)),
                            'std': float(np.std(valid_samples)),
                            'percentile_2.5': float(np.percentile(valid_samples, 2.5)),
                            'percentile_97.5': float(np.percentile(valid_samples, 97.5)),
                            'effective_sample_size': len(valid_samples)
                        }
                    else:
                        hyperparameter_uncertainty[param_name] = {
                            'mean': optimal_hyperparams[param_name],
                            'std': float(posterior_std[i]),
                            'percentile_2.5': optimal_hyperparams[param_name] - 2*posterior_std[i],
                            'percentile_97.5': optimal_hyperparams[param_name] + 2*posterior_std[i],
                            'effective_sample_size': 10
                        }
                        
            except Exception as e:
                logging.warning(f"Laplace approximation failed: {e}")
                hyperparameter_uncertainty = {
                    param_name: {
                        'mean': optimal_hyperparams[param_name],
                        'std': 0.1,
                        'percentile_2.5': optimal_hyperparams[param_name] - 0.2,
                        'percentile_97.5': optimal_hyperparams[param_name] + 0.2,
                        'effective_sample_size': 100
                    } for param_name in param_names
                }
            
            # Evaluate optimal model
            optimal_metrics = self._evaluate_model_with_hyperparameters(
                candidate, optimal_hyperparams, obs_points, train_data, val_data, config
            )
            
            return {
                'model_type': candidate['type'],
                'hyperparameters': optimal_hyperparams,
                'hyperparameter_uncertainty': hyperparameter_uncertainty,
                'metrics': optimal_metrics,
                'optimization_method': 'bayesian_scipy_laplace',
                'convergence_diagnostics': {
                    'optimization_success': result.success,
                    'function_evaluations': result.nfev,
                    'final_objective_value': float(result.fun)
                },
                'map_log_posterior': float(-result.fun),
                'laplace_approximation': True
            }
            
        except Exception as e:
            logging.error(f"SciPy Bayesian optimization failed: {e}")
            return self._simplified_hyperparameter_search(candidate, obs_points, train_data, val_data, config)

