        """Get Bayesian priors for hyperparameter optimization"""
        try:
            if model_type == 'physics_based':
                return {
                    'regularization': {'alpha': 2.0, 'beta': 200.0},  # Gamma distribution
                    'smoothing_factor': {'alpha': 3.0, 'beta': 2.0}   # Gamma distribution
                }
            elif model_type == 'ml_enhanced':
                return {
                    'ensemble_size': {'min': 5, 'max': 50},           # Discrete uniform
                    'ml_weight': {'alpha': 2.0, 'beta': 2.0},        # Beta distribution
                    'regularization': {'alpha': 2.0, 'beta': 200.0}  # Gamma distribution
                }
            elif model_type == 'pinn':
                return {
                    'learning_rate': {'alpha': 1.0, 'beta': 1000.0}, # Gamma distribution for learning rate
                    'physics_weight': {'alpha': 5.0, 'beta': 2.0},   # Gamma distribution
                    'dropout_rate': {'alpha': 1.0, 'beta': 9.0}      # Beta distribution (low dropout)
                }
            else:
                return {
                    'regularization': {'alpha': 2.0, 'beta': 200.0}
                }
        except Exception as e:
            logging.warning(f"Error getting Bayesian priors: {e}")
            return {'regularization': {'alpha': 2.0, 'beta': 200.0}}

