    def _evaluate_model_with_hyperparameters(self, candidate: Dict, hyperparams: Dict,
                                           obs_points: np.ndarray, train_data: Dict,
                                           val_data: Dict, config: Dict) -> Dict[str, float]:
        """Evaluate model performance with given hyperparameters"""
        try:
            # Configure model with hyperparameters
            if candidate['type'] == 'physics_based':
                predictions = self._evaluate_physics_model(obs_points, hyperparams)
            elif candidate['type'] == 'ml_enhanced':
                predictions = self._evaluate_ml_enhanced_model(obs_points, hyperparams, train_data)
            elif candidate['type'] == 'pinn':
                predictions = self._evaluate_pinn_model(obs_points, hyperparams, train_data)
            elif candidate['type'] == 'ensemble':
                predictions = self._evaluate_ensemble_model(obs_points, hyperparams, train_data)
            else:
                predictions = self.compute_displacements(obs_points)
            
            # Calculate validation metrics
            if val_data and 'displacements' in val_data:
                metrics = self._calculate_validation_metrics(predictions, val_data['displacements'])
            else:
                # Use synthetic validation if no validation data
                metrics = self._calculate_synthetic_metrics(predictions, obs_points)
            
            return metrics
            
        except Exception as e:
            logging.warning(f"Model evaluation failed: {e}")
            return {'rmse': float('inf'), 'mae': float('inf'), 'r2_score': -float('inf')}
    
    def _calculate_validation_metrics(self, predictions: np.ndarray, 
                                    true_values: np.ndarray) -> Dict[str, float]:
        """Calculate validation metrics"""
        try:
            from sklearn.metrics import mean_squared_error, mean_absolute_error, r2_score
            
            # Handle different prediction formats
            if isinstance(predictions, dict):
                pred_values = predictions.get('displacements', predictions.get('predictions', predictions))
            else:
                pred_values = predictions
            
            # Flatten arrays for metric calculation
            pred_flat = pred_values.flatten()
            true_flat = true_values.flatten()
            
            metrics = {
                'rmse': np.sqrt(mean_squared_error(true_flat, pred_flat)),
                'mae': mean_absolute_error(true_flat, pred_flat),
                'r2_score': r2_score(true_flat, pred_flat),
                'max_error': np.max(np.abs(true_flat - pred_flat)),
                'physics_consistency': self._calculate_physics_consistency(pred_values)
            }
            
            return metrics
            
        except Exception as e:
            logging.warning(f"Metric calculation failed: {e}")
            return {'rmse': float('inf'), 'mae': float('inf'), 'r2_score': -float('inf')}
    
    def _calculate_synthetic_metrics(self, predictions: np.ndarray, 
                                   obs_points: np.ndarray) -> Dict[str, float]:
        """Calculate metrics using synthetic data when validation data is unavailable"""
        try:
            # Generate synthetic "true" values using simplified physics
            synthetic_true = self._generate_synthetic_displacements(obs_points)
            
            return self._calculate_validation_metrics(predictions, synthetic_true)
            
        except Exception as e:
            logging.warning(f"Synthetic metric calculation failed: {e}")
            return {'rmse': float('inf'), 'mae': float('inf'), 'r2_score': -float('inf')}
    
    def _calculate_physics_consistency(self, predictions: np.ndarray) -> float:
        """Calculate physics consistency score"""
        try:
            # Simple physics consistency check (placeholder)
            # In practice, this would check equilibrium equations, compatibility, etc.
            consistency_score = 1.0 - np.std(predictions.flatten()) / (np.mean(np.abs(predictions.flatten())) + 1e-8)
            return max(0.0, min(1.0, consistency_score))
            
        except Exception as e:
            logging.warning(f"Physics consistency calculation failed: {e}")
            return 0.0
    
    def _select_best_model(self, results: List[Dict], config: Dict) -> Dict:
        """Select best model based on validation metrics"""
        try:
            if not results:
                return {'model_type': 'physics_based', 'hyperparameters': {}, 'metrics': {}}
            
            # Define weights for different metrics
            metric_weights = {
                'rmse': -1.0,  # Lower is better
                'mae': -0.5,   # Lower is better
                'r2_score': 1.0,  # Higher is better
                'physics_consistency': 0.5  # Higher is better
            }
            
            best_model = None
            best_score = float('-inf')
            
            for result in results:
                if 'error' in result:
                    continue
                    
                metrics = result.get('metrics', {})
                
                # Calculate composite score
                score = 0.0
                for metric, weight in metric_weights.items():
                    if metric in metrics and not np.isinf(metrics[metric]):
                        score += weight * metrics[metric]
                
                if score > best_score:
                    best_score = score
                    best_model = result
            
            return best_model if best_model else results[0]
            
        except Exception as e:
            logging.error(f"Model selection failed: {e}")
            return results[0] if results else {'model_type': 'physics_based', 'hyperparameters': {}, 'metrics': {}}
    
