    def _run_accuracy_tests(self, config: Dict) -> Dict[str, any]:
        """Run accuracy validation tests"""
        try:
            accuracy_results = {
                'tests_completed': 0,
                'tests_passed': 0,
                'accuracy_metrics': {},
                'threshold_checks': {}
            }
            
            # Test displacement accuracy
            obs_points = np.random.uniform(-1000, 1000, (50, 3))
            obs_points[:, 2] = 0  # Surface observations
            
            displacements = self.compute_displacements(obs_points, uncertainty_quantification=True)
            
            if isinstance(displacements, dict) and 'uncertainty' in displacements:
                disp_uncertainty = np.mean(displacements['uncertainty'])
                rmse_threshold = config['accuracy_thresholds']['displacement_rmse']
                
                accuracy_results['accuracy_metrics']['displacement_uncertainty'] = disp_uncertainty
                accuracy_results['threshold_checks']['displacement_rmse'] = disp_uncertainty < rmse_threshold
                accuracy_results['tests_completed'] += 1
                if disp_uncertainty < rmse_threshold:
                    accuracy_results['tests_passed'] += 1
            
            return accuracy_results
            
        except Exception as e:
            logging.error(f"Accuracy tests failed: {e}")
            return {'error': str(e)}
    
    def _run_performance_tests(self, config: Dict) -> Dict[str, any]:
        """Run performance benchmark tests"""
        try:
            import time, psutil, os
            
            performance_results = {
                'execution_times': {},
                'memory_usage': {},
                'scalability_analysis': {}
            }
            
            # Test execution time scaling
            for data_size in config.get('test_data_sizes', [10, 100]):
                obs_points = np.random.uniform(-1000, 1000, (data_size, 3))
                
                # Monitor memory before
                process = psutil.Process(os.getpid())
                memory_before = process.memory_info().rss / 1024 / 1024  # MB
                
                start_time = time.time()
                result = self.compute_displacements(obs_points)
                execution_time = time.time() - start_time
                
                # Monitor memory after
                memory_after = process.memory_info().rss / 1024 / 1024  # MB
                memory_used = memory_after - memory_before
                
                performance_results['execution_times'][f'size_{data_size}'] = execution_time
                performance_results['memory_usage'][f'size_{data_size}'] = memory_used
            
            return performance_results
            
        except Exception as e:
            logging.warning(f"Advanced performance profiling failed: {e}")
            return self._fallback_basic_performance_profiling(config)
    
    def _run_robustness_tests(self, config: Dict) -> Dict[str, any]:
        """Run robustness validation tests"""
        try:
            robustness_results = {
                'noise_tolerance': {},
                'numerical_stability': {},
                'parameter_sensitivity': {}
            }
            
            # Test noise tolerance
            if config.get('robustness_tests', {}).get('noise_tolerance', False):
                obs_points = np.random.uniform(-500, 500, (20, 3))
                
                for noise_level in config.get('noise_levels', [0.001, 0.01]):
                    # Add noise to observation points
                    noisy_points = obs_points + np.random.normal(0, noise_level, obs_points.shape)
                    
                    try:
                        result = self.compute_displacements(noisy_points)
                        robustness_results['noise_tolerance'][f'noise_{noise_level}'] = {
                            'status': 'passed',
                            'message': 'Computation successful with noise'
                        }
                    except Exception as e:
                        robustness_results['noise_tolerance'][f'noise_{noise_level}'] = {
                            'status': 'failed',
                            'error': str(e)
                        }
            
            # Test numerical stability
            if config.get('robustness_tests', {}).get('numerical_stability', False):
                # Test with extreme coordinates
                extreme_points = np.array([[1e6, 1e6, 0], [1e-6, 1e-6, 0], [0, 0, 0]])
                
                try:
                    result = self.compute_displacements(extreme_points)
                    if isinstance(result, dict):
                        disp_values = result.get('displacements', result)
                    else:
                        disp_values = result
                    
                    has_nan = np.any(np.isnan(disp_values))
                    has_inf = np.any(np.isinf(disp_values))
                    
                    robustness_results['numerical_stability'] = {
                        'status': 'passed' if not (has_nan or has_inf) else 'failed',
                        'has_nan': has_nan,
                        'has_inf': has_inf
                    }
                except Exception as e:
                    robustness_results['numerical_stability'] = {
                        'status': 'failed',
                        'error': str(e)
                    }
            
            return robustness_results
            
        except Exception as e:
            logging.error(f"Robustness tests failed: {e}")
            return {'error': str(e)}
    
    def _generate_validation_summary(self, validation_results: Dict) -> Dict[str, any]:
        """Generate overall validation summary"""
        try:
            summary = {
                'overall_status': 'unknown',
                'total_tests': 0,
                'passed_tests': 0,
                'success_rate': 0.0,
                'major_issues': [],
                'recommendations': []
            }
            
            # Count tests from different categories
            test_categories = ['unit_tests', 'integration_tests', 'accuracy_tests', 'robustness_tests']
            
            for category in test_categories:
                if category in validation_results.get('test_results', {}):
                    test_data = validation_results['test_results'][category]
                    if 'total_tests' in test_data:
                        summary['total_tests'] += test_data['total_tests']
                        summary['passed_tests'] += test_data.get('passed_tests', 0)
            
            # Add benchmark results
            if 'benchmarks' in validation_results and 'summary' in validation_results['benchmarks']:
                bench_summary = validation_results['benchmarks']['summary']
                summary['total_tests'] += bench_summary.get('total_benchmarks', 0)
                summary['passed_tests'] += bench_summary.get('passed_benchmarks', 0)
            
            # Calculate success rate
            if summary['total_tests'] > 0:
                summary['success_rate'] = summary['passed_tests'] / summary['total_tests']
            
            # Determine overall status
            if summary['success_rate'] >= 0.9:
                summary['overall_status'] = 'excellent'
            elif summary['success_rate'] >= 0.8:
                summary['overall_status'] = 'good'
            elif summary['success_rate'] >= 0.6:
                summary['overall_status'] = 'fair'
            else:
                summary['overall_status'] = 'needs_improvement'
            
            # Generate recommendations based on results
            if summary['success_rate'] < 0.8:
                summary['recommendations'].append("Consider reviewing failed test cases and improving model accuracy")
            
            if 'performance_metrics' in validation_results:
                summary['recommendations'].append("Monitor computational performance for large datasets")
            
            return summary
            
        except Exception as e:
            logging.error(f"Validation summary generation failed: {e}")
            return {'error': str(e), 'overall_status': 'failed'}
    
