                test_data = np.random.randn(100)
                result = self.compute_multiscale_decomposition(test_data)
                
                if isinstance(result, dict) and 'decomposition_levels' in result:
                    unit_test_results['test_details'][test_name] = {'status': 'passed', 'message': 'Multi-scale decomposition successful'}
