    def _validate_against_benchmark(self, dataset: Dict[str, Any], observations: np.ndarray,
                                  locations: np.ndarray, **kwargs) -> Dict[str, Any]:
        """Validate model performance against a benchmark dataset."""
        try:
            result = {
                'dataset_name': dataset['name'],
                'validation_success': False,
                'performance_metrics': {},
                'parameter_recovery': {},
                'comparison_with_published': {}
            }
            
            # Get benchmark observations and parameters
            benchmark_obs = dataset.get('observations')
            known_params = dataset.get('known_source_parameters', {})
            
            if benchmark_obs is not None:
                # Run inversion on benchmark data
                if hasattr(self, 'solver') and self.solver:
                    inversion_result = self.solver.invert(benchmark_obs, locations, **kwargs)
                    
                    if inversion_result and 'predictions' in inversion_result:
                        # Compute performance metrics
                        metrics = self._compute_benchmark_metrics(
                            benchmark_obs, inversion_result['predictions']
                        )
                        result['performance_metrics'] = metrics
                        
                        # Compare estimated vs known parameters
                        if 'estimated_params' in inversion_result and known_params:
                            param_comparison = self._compare_estimated_vs_known_parameters(
                                inversion_result['estimated_params'], known_params
                            )
                            result['parameter_recovery'] = param_comparison
                        
                        # Compare with published results if available
                        if 'reference' in dataset:
                            published_comparison = self._compare_with_published_solution(
                                dataset, inversion_result
                            )
                            result['comparison_with_published'] = published_comparison
                        
                        result['validation_success'] = True
                        
            return result
            
        except Exception as e:
            logging.error(f"Benchmark validation failed: {e}")
            return {
                'dataset_name': dataset.get('name', 'unknown'),
                'validation_success': False,
                'error': str(e)
            }

    def _get_landers_observations(self) -> np.ndarray:
        """Get Landers earthquake observations from database or external sources."""
        try:
            # Try to load from database first
            if hasattr(self, 'db_manager') and self.db_manager:
                query = """
                SELECT displacement_east, displacement_north, displacement_up
                FROM benchmark_earthquake_data 
                WHERE event_name = 'landers_1992'
                ORDER BY station_id
                """
                result = self.db_manager.execute_query(query)
                if result and len(result) > 0:
                    return np.array([[r['displacement_east'], r['displacement_north'], 
                                    r['displacement_up']] for r in result])
            
            # Try external data connectors
            if hasattr(self, 'data_integration_manager'):
                landers_data = self.data_integration_manager.get_earthquake_data('landers_1992')
                if landers_data:
                    return landers_data.get('displacements')
            
            # Fallback to published values from literature (Massonnet et al., 1993)
            return self._get_landers_literature_data()
            
        except Exception as e:
            logging.warning(f"Failed to load Landers observations: {e}")
            return self._get_landers_literature_data()

