    def _get_kilauea_observations(self) -> np.ndarray:
        """Get Kilauea volcano observations."""
        try:
            # Load GPS and InSAR data
            if hasattr(self, 'db_manager') and self.db_manager:
                query = """
                SELECT displacement_east, displacement_north, displacement_up
                FROM benchmark_volcano_data 
                WHERE site_name = 'kilauea_volcano'
                ORDER BY station_id
                """
                result = self.db_manager.execute_query(query)
                if result:
                    return np.array([[r['displacement_east'], r['displacement_north'], 
                                    r['displacement_up']] for r in result])
            
            # Literature data from Poland et al. (2006)
            return np.array([
                [-0.08, -0.05, -0.12],  # Summit area (deflation)
                [-0.06, -0.04, -0.09],  # Near summit
                [-0.03, -0.02, -0.05],  # Intermediate
                [-0.01, -0.01, -0.02],  # Far-field
                [0.0, 0.0, 0.0],        # Reference station
                [-0.05, -0.03, -0.08]   # Flank station
            ])
            
        except Exception as e:
            logging.warning(f"Failed to load Kilauea observations: {e}")
            return np.zeros((6, 3))

    def _load_insar_benchmark_datasets(self) -> Dict[str, Dict[str, Any]]:
        """Load InSAR benchmark datasets from database."""
        try:
            datasets = {}
            
            if hasattr(self, 'db_manager') and self.db_manager:
                # Query available InSAR benchmark datasets
                query = """
                SELECT DISTINCT dataset_name, location, time_period, reference_paper,
                       deformation_type, data_quality_score
                FROM insar_benchmark_datasets
                WHERE data_quality_score >= 0.8
                ORDER BY data_quality_score DESC
                """
                
                results = self.db_manager.execute_query(query)
                
                for result in results:
                    dataset_name = result['dataset_name']
                    
                    # Load displacement data for this dataset
                    data_query = """
                    SELECT longitude, latitude, los_displacement, coherence,
                           uncertainty_estimate
                    FROM insar_displacement_data
                    WHERE dataset_name = %s
                    ORDER BY measurement_date
                    """
                    
                    displacement_data = self.db_manager.execute_query(data_query, (dataset_name,))
                    
                    if displacement_data:
                        observations = np.array([[d['longitude'], d['latitude'], 
                                               d['los_displacement']] for d in displacement_data])
                        
                        datasets[dataset_name] = {
                            'name': dataset_name,
                            'location': result['location'],
                            'time_period': result['time_period'],
                            'deformation_type': result['deformation_type'],
                            'observations': observations,
                            'data_sources': ['InSAR'],
                            'reference': result['reference_paper'],
                            'metadata': {
                                'data_quality': 'high',
                                'uncertainty_estimates': 'available',
                                'quality_score': result['data_quality_score']
                            }
                        }
            
            return datasets
            
        except Exception as e:
            logging.warning(f"Failed to load InSAR benchmark datasets: {e}")
            return {}

