    def _format_leveling_measurement(self, measurement: pd.Series) -> Optional[Dict]:
        """Format precision leveling measurement data into standardized structure."""
        try:
            return {
                'station_id': measurement.get('station_id', 'LEV_UNKNOWN'),
                'measurement_type': 'Leveling',
                'timestamp': measurement['measurement_date'],
                'coordinates': [
                    float(measurement.get('longitude', 0)),
                    float(measurement.get('latitude', 0)),
                    float(measurement.get('elevation', 0))
                ],
                'displacement': [
                    0,  # Leveling primarily measures vertical displacement
                    0,
                    float(measurement.get('height_change', 0)) * 1000  # Convert to mm
                ],
                'uncertainty': [
                    0,
                    0,
                    float(measurement.get('uncertainty', 0.001)) * 1000  # Convert to mm
                ],
                'quality': measurement.get('quality_flag', 'GOOD'),
                'processing_method': 'Precision_Leveling',
                'metadata': {
                    'survey_method': measurement.get('survey_method', 'differential'),
                    'benchmark_stability': measurement.get('benchmark_stability', 'unknown'),
                    'atmospheric_correction': measurement.get('atmospheric_correction', False)
                }
            }
        except Exception as e:
            logging.warning(f"Failed to format leveling measurement: {e}")
            return None
    
