    def _extract_real_displacement_correction_data(self, parameter_name: str) -> Dict[str, np.ndarray]:
        """Extract real displacement correction training data from geological samples."""
        try:
            from .geological_data_structures import GeologicalSample, DrillholeData
            
            training_data = {
                'features': np.array([]),
                'targets': np.array([]),
                'sample_metadata': []
            }
            
            # Extract from geological samples in database
            if hasattr(self.db_manager, 'query_geological_samples'):
                try:
                    geological_samples = self._run_async_query(
                        self.db_manager.query_geological_samples(
                            parameter_type=parameter_name,
                            include_measurements=True
                        )
                    )
                    
                    if geological_samples is not None and not geological_samples.empty:
                        features_list = []
                        targets_list = []
                        metadata_list = []
                        
                        for _, sample in geological_samples.iterrows():
                            # Extract spatial features
                            spatial_features = [
                                float(sample.get('longitude', 0)),
                                float(sample.get('latitude', 0)), 
                                float(sample.get('elevation', 0))
                            ]
                            
                            # Extract geological context features
                            geological_context = [
                                float(sample.get('depth_m', 0)),
                                float(sample.get('lithology_code', 1)),
                                float(sample.get('structural_complexity', 0.5)),
                                float(sample.get('metamorphic_grade', 0)),
                                float(sample.get('weathering_degree', 0))
                            ]
                            
                            # Combine features
                            sample_features = spatial_features + geological_context
                            features_list.append(sample_features)
                            
                            # Extract target displacement correction value
                            if 'displacement_correction' in parameter_name:
                                target_value = float(sample.get('displacement_correction', 0))
                            else:
                                target_value = float(sample.get(parameter_name, 0))
                            
                            targets_list.append(target_value)
                            metadata_list.append({
                                'sample_id': sample.get('sample_id', 'unknown'),
                                'sample_type': sample.get('sample_type', 'unknown'),
                                'quality': float(sample.get('quality', 1.0))
                            })
                        
                        if features_list:
                            training_data['features'] = np.array(features_list)
                            training_data['targets'] = np.array(targets_list)
                            training_data['sample_metadata'] = metadata_list
                            
                            logging.info(f"Extracted {len(features_list)} real displacement correction samples from database")
                            
                except Exception as db_error:
                    logging.warning(f"Database sample extraction failed: {db_error}")
            
            # Extract from drillhole data if available
            if training_data['features'].size == 0 and hasattr(self, 'drillhole_data'):
                drillhole_training = self._extract_displacement_correction_from_drillholes(parameter_name)
                if drillhole_training['features'].size > 0:
                    training_data = drillhole_training
                    logging.info(f"Extracted displacement correction data from drillholes")
            
            # Extract from geological model samples if available
            if training_data['features'].size == 0 and hasattr(self, 'geological_model'):
                model_training = self._extract_displacement_correction_from_geological_model(parameter_name)
                if model_training['features'].size > 0:
                    training_data = model_training
                    logging.info(f"Extracted displacement correction data from geological model")
                    
            return training_data
            
        except Exception as e:
            logging.error(f"Failed to extract real displacement correction data: {e}")
            return {
                'features': np.array([]),
                'targets': np.array([]),
                'sample_metadata': []
            }
    
    def _generate_geological_constraint_based_displacement_data(self, parameter_name: str) -> Dict[str, np.ndarray]:
        """Generate geological constraint-based displacement correction data."""
        try:
            n_samples = 150
            
            # Use geological constraints from database if available
            geological_constraints = self._get_geological_constraints_from_database()
            
            # Generate features based on geological constraints
            depth_range = geological_constraints.get('depth_range', [0, 10000])
            lithology_types = geological_constraints.get('lithology_types', list(range(1, 15)))
            
            features_list = []
            targets_list = []
            
            for i in range(n_samples):
                # Spatial coordinates based on model domain
                model_center = self._get_model_center_location()
                if model_center:
                    center_lat, center_lon = model_center
                    # Generate samples within model domain
                    lat_offset = np.random.normal(0, 0.01)  # ~1km standard deviation
                    lon_offset = np.random.normal(0, 0.01)
                    elevation = 100 + np.random.normal(0, 50)
                else:
                    center_lat, center_lon = 37.0, -122.0  # Default location
                    lat_offset = np.random.normal(0, 0.01)
                    lon_offset = np.random.normal(0, 0.01)
                    elevation = 100 + np.random.normal(0, 50)
                
                # Geological context features using constraints
                depth = np.random.uniform(depth_range[0], depth_range[1])
                lithology = np.random.choice(lithology_types)
                structural_complexity = np.random.beta(2, 3)  # Skewed towards simpler structures
                metamorphic_grade = np.random.exponential(0.3)  # Most rocks have low metamorphic grade
                weathering_degree = np.random.beta(2, 2)  # Moderate weathering
                
                sample_features = [
                    center_lon + lon_offset,
                    center_lat + lat_offset,
                    elevation,
                    depth,
                    lithology,
                    structural_complexity,
                    metamorphic_grade,
                    weathering_degree
                ]
                
                features_list.append(sample_features)
                
                # Generate realistic target values based on geological relationships
                if 'displacement_correction' in parameter_name:
                    # Displacement corrections are typically small
                    base_correction = 0.001 * (1 + structural_complexity) * (1 + metamorphic_grade)
                    target_value = base_correction + np.random.normal(0, base_correction * 0.1)
                else:
                    target_value = np.random.normal(0, 0.01)
                
                targets_list.append(target_value)
            
            return {
                'features': np.array(features_list),
                'targets': np.array(targets_list)
            }
            
        except Exception as e:
            logging.error(f"Failed to generate geological constraint-based displacement data: {e}")
            # Minimal fallback
            return {
                'features': np.zeros((10, 8)),
                'targets': np.zeros(10)
            }
    
    def _extract_real_geological_features_from_database(self, n_samples: int, parameter_name: str) -> Dict[str, np.ndarray]:
        """Extract real geological features from database samples."""
        try:
            geological_features = {}
            
            # Query geological samples from database
            if hasattr(self.db_manager, 'query_geological_samples'):
                try:
                    samples = self._run_async_query(
                        self.db_manager.query_geological_samples(
                            limit=n_samples,
                            include_properties=True
                        )
                    )
                    
                    if samples is not None and not samples.empty and len(samples) > 0:
                        # Extract features from real samples
                        geological_features = {
                            'depth': samples.get('depth_m', []).values,
                            'temperature': samples.get('temperature_c', []).values,
                            'pressure': samples.get('pressure_mpa', []).values,
                            'porosity': samples.get('porosity', []).values,
                            'grain_size': samples.get('grain_size_mm', []).values,
                            'weathering_degree': samples.get('weathering_degree', []).values,
                            'structural_complexity': samples.get('structural_complexity', []).values,
                            'metamorphic_grade': samples.get('metamorphic_grade', []).values,
                            'age': samples.get('age_ma', []).values,
                            'lithology_code': samples.get('lithology_code', []).values
                        }
                        
                        # Fill missing values with defaults and ensure correct length
                        for key in geological_features:
                            if len(geological_features[key]) == 0:
                                geological_features[key] = self._get_default_feature_values(key, n_samples)
                            elif len(geological_features[key]) < n_samples:
                                # Extend with interpolated values
                                existing_values = geological_features[key]
                                additional_samples = n_samples - len(existing_values)
                                if len(existing_values) > 1:
                                    # Interpolate/extrapolate missing samples
                                    extended_values = np.interp(
                                        np.linspace(0, len(existing_values)-1, additional_samples),
                                        range(len(existing_values)),
                                        existing_values
                                    )
                                    geological_features[key] = np.concatenate([existing_values, extended_values])
                                else:
                                    # Repeat single value
                                    geological_features[key] = np.full(n_samples, existing_values[0] if len(existing_values) > 0 else 0)
                            elif len(geological_features[key]) > n_samples:
                                # Downsample
                                geological_features[key] = geological_features[key][:n_samples]
                        
                        logging.info(f"Extracted {len(samples)} real geological samples from database")
                        return geological_features
                        
                except Exception as db_error:
                    logging.warning(f"Database geological feature extraction failed: {db_error}")
            
            # Try extracting from drillhole data
            if hasattr(self, 'drillhole_data') and self.drillhole_data:
                geological_features = self._extract_features_from_drillholes(n_samples)
                if geological_features:
                    logging.info(f"Extracted geological features from drillhole data")
                    return geological_features
            
            # Try extracting from geological model
            if hasattr(self, 'geological_model') and self.geological_model:
                geological_features = self._extract_features_from_geological_model(n_samples)
                if geological_features:
                    logging.info(f"Extracted geological features from geological model")
                    return geological_features
            
            # Try extracting from USGS geological survey data (new integration)
            try:
                from .external_data_connectors import USGSConnector
                usgs_connector = USGSConnector()
                geological_features = self._extract_features_from_usgs_geological_survey(usgs_connector, n_samples, parameter_name)
                if geological_features:
                    logging.info(f"Extracted {len(geological_features.get('depth', []))} geological features from USGS geological survey data")
                    return geological_features
            except ImportError as e:
                logging.warning(f"USGS connector not available: {e}")
            except Exception as e:
                logging.warning(f"USGS geological survey data extraction failed: {e}")
            
            # Try extracting from other geological survey APIs
            geological_features = self._extract_features_from_other_geological_surveys(n_samples, parameter_name)
            if geological_features:
                logging.info(f"Extracted geological features from other geological survey APIs")
                return geological_features
            
            return {}
            
        except Exception as e:
            logging.error(f"Failed to extract real geological features: {e}")
            return {}
    
    def _generate_constraint_based_geological_features(self, n_samples: int, parameter_name: str) -> Dict[str, np.ndarray]:
        """Generate geological features using advanced geostatistical sampling methods.
        
        Implements advanced geostatistical techniques including:
        - Kriging interpolation for spatial continuity
        - Variogram-based spatial correlation modeling
        - Sequential Gaussian simulation for realistic spatial patterns
        - Multi-scale sampling with fractal characteristics
        - Conditional simulation using existing data points
        """
        try:
            logging.info(f"Generating {n_samples} geological features using advanced geostatistical methods")
            
            # Get geological constraints and reference points from database
            constraints = self._get_geological_constraints_from_database()
            reference_data = self._get_reference_geological_data_for_geostatistics()
            
            # Generate spatially correlated sample locations using stratified sampling
            sample_locations = self._generate_geostatistical_sample_locations(n_samples, constraints)
            
            # Initialize geological features using advanced geostatistical methods
            geological_features = {}
            
            # Generate depth using Sequential Gaussian Simulation with spatial correlation
            depth_range = constraints.get('depth_range', [0, 15000])
            depth_variogram = self._get_depth_variogram_parameters(parameter_name, constraints)
            
            if reference_data.get('depth_points') is not None:
                # Use conditional simulation based on existing data
                depths = self._sequential_gaussian_simulation(
                    sample_locations, reference_data['depth_points'], depth_range,
                    variogram_params=depth_variogram, parameter_name='depth'
                )
            else:
                # Use unconditional geostatistical simulation
                depths = self._unconditional_geostatistical_simulation(
                    sample_locations, depth_range, depth_variogram, 'depth', parameter_name
                )
            
            geological_features['depth'] = depths
            
            # Temperature using kriging interpolation with geothermal gradients
            surface_temp = constraints.get('surface_temperature', 15)
            geothermal_gradient = constraints.get('geothermal_gradient', 25)  # °C/km
            
            if reference_data.get('temperature_points') is not None:
                temperatures = self._kriging_interpolation(
                    sample_locations, reference_data['temperature_points'],
                    fallback_model=lambda d: surface_temp + (d / 1000.0) * geothermal_gradient
                )
            else:
                # Spatially correlated temperature field
                temp_variogram = self._get_temperature_variogram_parameters(constraints)
                base_temps = surface_temp + (depths / 1000.0) * geothermal_gradient
                temp_residuals = self._generate_spatially_correlated_field(
                    sample_locations, temp_variogram, std_dev=5.0
                )
                temperatures = base_temps + temp_residuals
            
            geological_features['temperature'] = np.clip(temperatures, 0, 1000)
            
            # Pressure using geostatistical co-simulation with depth
            pressures = self._co_simulation_pressure_depth(
                sample_locations, depths, constraints, reference_data
            )
            geological_features['pressure'] = np.clip(pressures, 0.1, 2000)
            
            # Porosity using conditional simulation with compaction laws
            porosity_params = self._get_porosity_geostatistical_parameters(constraints)
            porosities = self._simulate_porosity_with_compaction(
                sample_locations, depths, porosity_params, reference_data
            )
            geological_features['porosity'] = np.clip(porosities, 0.001, 0.5)
            
            # Grain size using log-normal geostatistical simulation
            grain_size_variogram = self._get_grain_size_variogram_parameters(constraints)
            grain_sizes = self._log_normal_geostatistical_simulation(
                sample_locations, grain_size_variogram, reference_data
            )
            geological_features['grain_size'] = np.clip(grain_sizes, 0.001, 100)
            
            # Weathering degree using indicator kriging
            weathering_degrees = self._indicator_kriging_weathering(
                sample_locations, depths, constraints, reference_data
            )
            geological_features['weathering_degree'] = np.clip(weathering_degrees, 0, 1)
            
            # Structural complexity using fractal simulation
            structural_complexity = self._fractal_simulation_structural_complexity(
                sample_locations, constraints, reference_data
            )
            geological_features['structural_complexity'] = np.clip(structural_complexity, 0, 1)
            
            # Metamorphic grade using co-simulation with temperature and pressure
            metamorphic_grades = self._co_simulation_metamorphic_grade(
                sample_locations, temperatures, pressures, constraints, reference_data
            )
            geological_features['metamorphic_grade'] = np.clip(metamorphic_grades, 0, 1)
            
            # Geological age using Markov random field simulation
            ages = self._markov_random_field_age_simulation(
                sample_locations, constraints, parameter_name, reference_data
            )
            geological_features['age'] = ages
            
            # Lithology code using indicator co-simulation
            lithology_codes = self._indicator_co_simulation_lithology(
                sample_locations, geological_features, constraints, reference_data
            )
            geological_features['lithology_code'] = lithology_codes
            
            # Validate spatial continuity and geological consistency
            geological_features = self._validate_geostatistical_continuity(
                geological_features, sample_locations, constraints
            )
            
            logging.info(f"Generated {n_samples} geostatistically-sampled geological features with spatial continuity")
            return geological_features
            
        except Exception as e:
            logging.error(f"Failed to generate geostatistical geological features: {e}")
            return self._get_advanced_geostatistical_fallback(n_samples, parameter_name)
    
    def _extract_real_sample_locations_from_database(self, n_samples: int, geological_features: Dict) -> np.ndarray:
        """Extract real sample locations from database."""
        try:
            sample_locations = []
            
            # Query sample locations from database
            if hasattr(self.db_manager, 'query_sample_locations'):
                try:
                    locations = self._run_async_query(
                        self.db_manager.query_sample_locations(limit=n_samples)
                    )
                    
                    if locations is not None and not locations.empty:
                        for _, location in locations.iterrows():
                            sample_locations.append([
                                float(location.get('longitude', 0)),
                                float(location.get('latitude', 0)),
                                -float(location.get('depth_m', 0))  # Negative depth for Z-coordinate
                            ])
                        
                        # If we have enough real locations, return them
                        if len(sample_locations) >= n_samples:
                            logging.info(f"Using {n_samples} real sample locations from database")
                            return np.array(sample_locations[:n_samples])
                        
                except Exception as db_error:
                    logging.warning(f"Database sample location extraction failed: {db_error}")
            
            # If we don't have enough real locations, generate based on model domain
            if len(sample_locations) < n_samples:
                remaining_samples = n_samples - len(sample_locations)
                model_center = self._get_model_center_location()
                model_extent = self._get_model_spatial_extent()
                
                if model_center and model_extent:
                    center_lat, center_lon = model_center
                    extent_lat, extent_lon = model_extent
                    
                    for i in range(remaining_samples):
                        # Generate within model domain
                        lat = center_lat + np.random.uniform(-extent_lat/2, extent_lat/2)
                        lon = center_lon + np.random.uniform(-extent_lon/2, extent_lon/2)
                        depth = geological_features.get('depth', [0])[i % len(geological_features.get('depth', [0]))] if geological_features else 1000
                        
                        sample_locations.append([lon, lat, -depth])
                else:
                    # Default domain around model center
                    center_lat, center_lon = 37.0, -122.0  # Default
                    for i in range(remaining_samples):
                        lat = center_lat + np.random.uniform(-0.1, 0.1)  # ~10km extent
                        lon = center_lon + np.random.uniform(-0.1, 0.1)
                        depth = geological_features.get('depth', [1000])[i % len(geological_features.get('depth', [1000]))] if geological_features else 1000
                        
                        sample_locations.append([lon, lat, -depth])
                
                logging.info(f"Generated {remaining_samples} sample locations within model domain")
            
            return np.array(sample_locations[:n_samples])
            
        except Exception as e:
            logging.error(f"Failed to extract real sample locations: {e}")
            # Fallback: generate basic grid
            locations = []
            for i in range(n_samples):
                locations.append([
                    -122.0 + (i % 10) * 0.01,  # Simple grid
                    37.0 + (i // 10) * 0.01,
                    -1000 - i * 10
                ])
            return np.array(locations[:n_samples])
    
    def _compute_real_data_quality_scores(self, geological_features: Dict, n_samples: int) -> np.ndarray:
        """Compute data quality scores based on real geological characteristics."""
        try:
            quality_scores = np.ones(n_samples)
            
            # Quality based on depth (deeper samples may be less reliable)
            if 'depth' in geological_features:
                depths = geological_features['depth']
                depth_quality = 1.0 - (depths / 20000.0) * 0.3  # Reduce quality with depth
                quality_scores *= np.clip(depth_quality, 0.5, 1.0)
            
            # Quality based on weathering (more weathered = less reliable)
            if 'weathering_degree' in geological_features:
                weathering = geological_features['weathering_degree']
                weathering_quality = 1.0 - weathering * 0.2  # Reduce quality with weathering
                quality_scores *= np.clip(weathering_quality, 0.7, 1.0)
            
            # Quality based on structural complexity (higher complexity = more uncertainty)
            if 'structural_complexity' in geological_features:
                complexity = geological_features['structural_complexity']
                complexity_quality = 1.0 - complexity * 0.15  # Reduce quality with complexity
                quality_scores *= np.clip(complexity_quality, 0.75, 1.0)
            
            # Add some measurement uncertainty
            measurement_noise = np.random.normal(0, 0.05, n_samples)
            quality_scores += measurement_noise
            
            # Ensure quality scores are in reasonable range
            quality_scores = np.clip(quality_scores, 0.6, 1.0)
            
            logging.debug(f"Computed quality scores: mean={np.mean(quality_scores):.3f}, std={np.std(quality_scores):.3f}")
            return quality_scores
            
        except Exception as e:
            logging.error(f"Failed to compute real data quality scores: {e}")
            # Fallback: uniform high quality
            return np.full(n_samples, 0.9)
    
