    def _get_geological_constraints_from_database(self) -> Dict:
        """Get geological constraints from database for realistic feature generation."""
        try:
            constraints = {}
            
            if hasattr(self.db_manager, 'query_geological_constraints'):
                try:
                    db_constraints = self._run_async_query(
                        self.db_manager.query_geological_constraints()
                    )
                    
                    if db_constraints is not None:
                        for constraint in db_constraints:
                            constraints[constraint['parameter']] = constraint['value']
                        
                        logging.debug(f"Retrieved {len(constraints)} geological constraints from database")
                        return constraints
                        
                except Exception as db_error:
                    logging.warning(f"Database geological constraints query failed: {db_error}")
            
            # Default constraints based on geological domain knowledge
            return {
                'depth_range': [0, 15000],  # meters
                'surface_temperature': 15,  # °C
                'geothermal_gradient': 25,  # °C/km
                'surface_porosity': 0.3,
                'porosity_decay_rate': 1e-4,  # per meter
                'surface_weathering': 0.8,
                'tectonic_setting': 'stable',
                'age_range_ma': [0, 3500],
                'lithology_types': list(range(1, 16)),
                'lithology_weights': {
                    1: 0.15, 2: 0.12, 3: 0.10, 4: 0.08, 5: 0.08,
                    6: 0.06, 7: 0.05, 8: 0.05, 9: 0.04, 10: 0.04,
                    11: 0.03, 12: 0.03, 13: 0.03, 14: 0.02, 15: 0.12
                }
            }
            
        except Exception as e:
            logging.error(f"Failed to get geological constraints: {e}")
            return {}
    
    def _get_model_spatial_extent(self) -> Optional[Tuple[float, float]]:
        """Get model spatial extent in degrees (lat_extent, lon_extent)."""
        try:
            # Try to get from model parameters
            if hasattr(self, 'model_domain') and 'spatial_extent' in self.model_domain:
                extent = self.model_domain['spatial_extent']
                return (extent.get('lat_extent', 0.1), extent.get('lon_extent', 0.1))
            
            # Default extent (~10km x 10km)
            return (0.1, 0.1)
            
        except Exception:
            return (0.1, 0.1)
    
    def _get_default_feature_values(self, feature_name: str, n_samples: int) -> np.ndarray:
        """Get default values for missing geological features."""
        defaults = {
            'depth': lambda n: np.random.exponential(2000, n),
            'temperature': lambda n: np.random.normal(50, 25, n),
            'pressure': lambda n: np.random.normal(50, 25, n),
            'porosity': lambda n: np.random.beta(2, 3, n) * 0.4,
            'grain_size': lambda n: np.random.lognormal(0, 1, n),
            'weathering_degree': lambda n: np.random.beta(2, 2, n),
            'structural_complexity': lambda n: np.random.beta(1, 3, n),
            'metamorphic_grade': lambda n: np.random.exponential(0.3, n),
            'age': lambda n: np.random.uniform(0, 2000, n),
            'lithology_code': lambda n: np.random.randint(1, 16, n)
        }
        
        if feature_name in defaults:
            return defaults[feature_name](n_samples)
        else:
            return np.zeros(n_samples)
    
    def _get_advanced_geostatistical_fallback(self, n_samples: int, parameter_name: str) -> Dict[str, np.ndarray]:
        """Advanced geostatistical fallback with spatial correlation when primary methods fail."""
        try:
            logging.info("Using advanced geostatistical fallback with spatial correlation")
            
            # Generate spatially correlated sample grid
            x_coords = np.random.uniform(-10000, 10000, n_samples)
            y_coords = np.random.uniform(-10000, 10000, n_samples)
            sample_locations = np.column_stack([x_coords, y_coords])
            
            # Simple variogram for fallback spatial correlation
            correlation_range = 5000  # meters
            
            # Generate spatially correlated depth field
            depth_base = np.random.uniform(100, 5000, n_samples)
            depth_correlation = self._simple_spatial_correlation(
                sample_locations, correlation_range, variance=1000**2
            )
            depths = np.maximum(100, depth_base + depth_correlation)
            
            # Temperature with spatial correlation and depth dependency
            temp_base = 15 + (depths / 1000.0) * 25  # Geothermal gradient
            temp_correlation = self._simple_spatial_correlation(
                sample_locations, correlation_range * 0.8, variance=10**2
            )
            temperatures = temp_base + temp_correlation
            
            # Pressure with depth correlation
            pressures = (depths * 26.5) / 1000 + np.random.normal(0, 5, n_samples)
            
            # Porosity with exponential depth decay and spatial correlation
            porosity_base = 0.3 * np.exp(-depths * 1e-4)
            porosity_correlation = self._simple_spatial_correlation(
                sample_locations, correlation_range * 1.2, variance=0.05**2
            )
            porosities = np.maximum(0.001, porosity_base + porosity_correlation)
            
            return {
                'depth': depths,
                'temperature': np.clip(temperatures, 0, 1000),
                'pressure': np.clip(pressures, 0.1, 2000),
                'porosity': np.clip(porosities, 0.001, 0.5),
                'grain_size': np.random.lognormal(0, 0.5, n_samples),
                'weathering_degree': np.maximum(0, 0.8 * np.exp(-depths / 50) + 
                                               np.random.normal(0, 0.1, n_samples)),
                'structural_complexity': np.random.beta(2, 3, n_samples),
                'metamorphic_grade': np.clip(np.maximum(0, (temperatures - 200) / 500), 0, 1),
                'age': np.random.exponential(100, n_samples),
                'lithology_code': np.random.choice(range(1, 16), n_samples)
            }
            
        except Exception as e:
            logging.error(f"Advanced geostatistical fallback failed: {e}")
            # Ultimate fallback to basic geological features
            return {
                'depth': np.linspace(100, 5000, n_samples),
                'temperature': np.linspace(20, 150, n_samples),
                'pressure': np.linspace(5, 150, n_samples),
                'porosity': np.linspace(0.05, 0.25, n_samples),
                'grain_size': np.full(n_samples, 1.0),
                'weathering_degree': np.linspace(0.8, 0.1, n_samples),
                'structural_complexity': np.full(n_samples, 0.3),
                'metamorphic_grade': np.linspace(0, 0.5, n_samples),
                'age': np.linspace(0, 1000, n_samples),
                'lithology_code': np.full(n_samples, 1, dtype=int)
            }
    
    def _extract_displacement_correction_from_drillholes(self, parameter_name: str) -> Dict[str, np.ndarray]:
        """Extract displacement correction data from drillhole samples."""
        try:
            features_list = []
            targets_list = []
            
            if hasattr(self.drillhole_data, '__iter__'):
                for drillhole in self.drillhole_data:
                    if hasattr(drillhole, 'geology_data') and drillhole.geology_data is not None:
                        for _, sample in drillhole.geology_data.iterrows():
                            # Extract features
                            features = [
                                float(drillhole.collar_x),
                                float(drillhole.collar_y),
                                float(drillhole.collar_z),
                                float(sample.get('depth', 0)),
                                float(sample.get('lithology_code', 1)),
                                0.5,  # Default structural complexity
                                0.0,  # Default metamorphic grade
                                0.3   # Default weathering degree
                            ]
                            features_list.append(features)
                            
                            # Extract target (if available)
                            target = float(sample.get(parameter_name, 0))
                            targets_list.append(target)
            
            if features_list:
                return {
                    'features': np.array(features_list),
                    'targets': np.array(targets_list)
                }
            
        except Exception as e:
            logging.warning(f"Drillhole displacement correction extraction failed: {e}")
        
        return {'features': np.array([]), 'targets': np.array([])}
    
    def _extract_displacement_correction_from_geological_model(self, parameter_name: str) -> Dict[str, np.ndarray]:
        """Extract displacement correction data from geological model samples."""
        try:
            features_list = []
            targets_list = []
            
            if hasattr(self.geological_model, 'samples') and self.geological_model.samples:
                for sample in self.geological_model.samples:
                    if hasattr(sample, 'location') and sample.location is not None:
                        # Extract spatial features
                        features = list(sample.location)
                        
                        # Add geological context
                        features.extend([
                            float(sample.grade_data.get('depth', 0)) if sample.grade_data else 0,
                            1,  # Default lithology code
                            0.5, # Default structural complexity
                            0.0, # Default metamorphic grade  
                            0.3  # Default weathering degree
                        ])
                        
                        features_list.append(features)
                        
                        # Extract target
                        if sample.grade_data and parameter_name in sample.grade_data:
                            target = float(sample.grade_data[parameter_name])
                        else:
                            target = 0.0
                        
                        targets_list.append(target)
            
            if features_list:
                return {
                    'features': np.array(features_list),
                    'targets': np.array(targets_list)
                }
            
        except Exception as e:
            logging.warning(f"Geological model displacement correction extraction failed: {e}")
        
        return {'features': np.array([]), 'targets': np.array([])}

    # ============== ADVANCED GEOSTATISTICAL SAMPLING METHODS ==============
    
    def _get_reference_geological_data_for_geostatistics(self) -> Dict[str, Optional[np.ndarray]]:
        """Get reference geological data points for conditional geostatistical simulation."""
        try:
            reference_data = {}
            
            # Try to get reference data from database
            if hasattr(self.db_manager, 'query_reference_geological_points'):
                try:
                    ref_points = self._run_async_query(
                        self.db_manager.query_reference_geological_points(limit=1000)
                    )
                    
                    if ref_points is not None and not ref_points.empty:
                        reference_data['depth_points'] = ref_points[['x', 'y', 'depth']].values
                        if 'temperature' in ref_points.columns:
                            reference_data['temperature_points'] = ref_points[['x', 'y', 'temperature']].values
                        if 'pressure' in ref_points.columns:
                            reference_data['pressure_points'] = ref_points[['x', 'y', 'pressure']].values
                        if 'porosity' in ref_points.columns:
                            reference_data['porosity_points'] = ref_points[['x', 'y', 'porosity']].values
                            
                except Exception as e:
                    logging.warning(f"Failed to query reference geological points: {e}")
            
            # Get reference data from drillhole database if available
            if hasattr(self, 'drillhole_data') and self.drillhole_data:
                try:
                    drillhole_points = []
                    for drillhole in self.drillhole_data:
                        if hasattr(drillhole, 'collar_x') and hasattr(drillhole, 'geology_data'):
                            for _, sample in drillhole.geology_data.iterrows():
                                point = [
                                    float(drillhole.collar_x),
                                    float(drillhole.collar_y),
                                    float(sample.get('depth', 0))
                                ]
                                drillhole_points.append(point)
                    
                    if drillhole_points:
                        reference_data['depth_points'] = np.array(drillhole_points)
                        
                except Exception as e:
                    logging.warning(f"Failed to extract drillhole reference data: {e}")
            
            # Set None for missing data types
            for data_type in ['depth_points', 'temperature_points', 'pressure_points', 'porosity_points']:
                if data_type not in reference_data:
                    reference_data[data_type] = None
                    
            return reference_data
            
        except Exception as e:
            logging.error(f"Failed to get reference geological data: {e}")
            return {
                'depth_points': None, 'temperature_points': None,
                'pressure_points': None, 'porosity_points': None
            }
    
    def _generate_geostatistical_sample_locations(self, n_samples: int, constraints: Dict) -> np.ndarray:
        """Generate spatially distributed sample locations using stratified sampling."""
        try:
            # Get domain bounds from constraints
            x_bounds = constraints.get('x_bounds', [-50000, 50000])
            y_bounds = constraints.get('y_bounds', [-50000, 50000])
            
            # Use stratified sampling for better spatial distribution
            n_strata_x = int(np.sqrt(n_samples))
            n_strata_y = int(np.ceil(n_samples / n_strata_x))
            
            x_step = (x_bounds[1] - x_bounds[0]) / n_strata_x
            y_step = (y_bounds[1] - y_bounds[0]) / n_strata_y
            
            sample_locations = []
            sample_count = 0
            
            for i in range(n_strata_x):
                for j in range(n_strata_y):
                    if sample_count >= n_samples:
                        break
                    
                    # Random location within stratum
                    x = x_bounds[0] + i * x_step + np.random.uniform(0, x_step)
                    y = y_bounds[0] + j * y_step + np.random.uniform(0, y_step)
                    
                    sample_locations.append([x, y])
                    sample_count += 1
                
                if sample_count >= n_samples:
                    break
            
            # Fill remaining samples if needed
            while len(sample_locations) < n_samples:
                x = np.random.uniform(x_bounds[0], x_bounds[1])
                y = np.random.uniform(y_bounds[0], y_bounds[1])
                sample_locations.append([x, y])
            
            return np.array(sample_locations[:n_samples])
            
        except Exception as e:
            logging.error(f"Failed to generate geostatistical sample locations: {e}")
            # Fallback to random sampling
            return np.random.uniform(-10000, 10000, (n_samples, 2))
    
    def _get_depth_variogram_parameters(self, parameter_name: str, constraints: Dict) -> Dict:
        """Get variogram parameters for depth simulation."""
        try:
            tectonic_setting = constraints.get('tectonic_setting', 'stable')
            
            # Default variogram parameters based on tectonic setting
            if tectonic_setting == 'active':
                return {
                    'model': 'spherical',
                    'sill': 2000000,  # High variance in active areas
                    'range': 3000,    # Shorter correlation range
                    'nugget': 100000
                }
            elif tectonic_setting == 'extensional':
                return {
                    'model': 'exponential',
                    'sill': 1500000,
                    'range': 5000,
                    'nugget': 50000
                }
            else:  # stable
                return {
                    'model': 'gaussian',
                    'sill': 1000000,
                    'range': 8000,    # Longer correlation range
                    'nugget': 25000
                }
                
        except Exception as e:
            logging.error(f"Failed to get depth variogram parameters: {e}")
            return {'model': 'spherical', 'sill': 1000000, 'range': 5000, 'nugget': 50000}
    
    def _sequential_gaussian_simulation(self, sample_locations: np.ndarray, 
                                      reference_points: np.ndarray, value_range: Tuple[float, float],
                                      variogram_params: Dict, parameter_name: str) -> np.ndarray:
        """Sequential Gaussian simulation for spatially correlated sampling."""
        try:
            n_samples = len(sample_locations)
            simulated_values = np.zeros(n_samples)
            
            # Extract reference coordinates and values
            ref_coords = reference_points[:, :2]  # x, y coordinates
            ref_values = reference_points[:, 2]   # z values (depth/temperature/etc)
            
            # Normalize reference values to standard normal
            ref_mean = np.mean(ref_values)
            ref_std = np.std(ref_values) if np.std(ref_values) > 0 else 1.0
            ref_values_norm = (ref_values - ref_mean) / ref_std
            
            # Sequential simulation at each location
            for i, location in enumerate(sample_locations):
                try:
                    # Find nearby reference points for conditioning
                    distances = np.sqrt(np.sum((ref_coords - location)**2, axis=1))
                    max_neighbors = min(15, len(ref_coords))  # Limit conditioning points
                    nearest_indices = np.argsort(distances)[:max_neighbors]
                    
                    # Kriging estimation at current location
                    kriging_estimate, kriging_variance = self._simple_kriging_estimate(
                        location, ref_coords[nearest_indices], ref_values_norm[nearest_indices],
                        variogram_params
                    )
                    
                    # Generate conditional random value
                    conditional_std = np.sqrt(max(kriging_variance, 0.01))
                    simulated_values[i] = np.random.normal(kriging_estimate, conditional_std)
                    
                    # Add current simulation to conditioning data for next points
                    if i < n_samples - 1:
                        ref_coords = np.vstack([ref_coords, location.reshape(1, -1)])
                        ref_values_norm = np.append(ref_values_norm, simulated_values[i])
                        
                except Exception as e:
                    logging.debug(f"Sequential simulation failed at location {i}: {e}")
                    simulated_values[i] = np.random.normal(0, 1)
            
            # Transform back to original scale and constrain to range
            simulated_values = simulated_values * ref_std + ref_mean
            simulated_values = np.clip(simulated_values, value_range[0], value_range[1])
            
            return simulated_values
            
        except Exception as e:
            logging.error(f"Sequential Gaussian simulation failed: {e}")
            # Advanced fallback using machine learning and geological constraints
            return self._advanced_geological_simulation_fallback(
                sample_locations, reference_points, value_range, variogram_params, parameter_name
            )

    def _extract_features_from_drillholes(self, n_samples: int) -> Dict[str, np.ndarray]:
        """Extract geological features from drillhole data."""
        try:
            features = {}
            all_samples = []
            
            if hasattr(self.drillhole_data, '__iter__'):
                for drillhole in self.drillhole_data:
                    if hasattr(drillhole, 'geology_data') and drillhole.geology_data is not None:
                        for _, sample in drillhole.geology_data.iterrows():
                            all_samples.append({
                                'depth': float(sample.get('depth', 0)),
                                'lithology_code': int(sample.get('lithology_code', 1)),
                                'temperature': float(sample.get('temperature', 20)),
                                'pressure': float(sample.get('pressure', 10)),
                                'porosity': float(sample.get('porosity', 0.1)),
                                'grain_size': float(sample.get('grain_size', 1.0)),
                                'weathering_degree': float(sample.get('weathering_degree', 0.5)),
                                'structural_complexity': float(sample.get('structural_complexity', 0.3)),
                                'metamorphic_grade': float(sample.get('metamorphic_grade', 0.0)),
                                'age': float(sample.get('age', 100))
                            })
            
            # Convert to feature arrays
            if all_samples:
                for key in all_samples[0].keys():
                    values = [sample[key] for sample in all_samples]
                    if len(values) >= n_samples:
                        features[key] = np.array(values[:n_samples])
                    else:
                        # Extend with interpolation
                        extended_values = np.interp(
                            np.linspace(0, len(values)-1, n_samples),
                            range(len(values)),
                            values
                        )
                        features[key] = extended_values
            
            return features
            
        except Exception as e:
            logging.warning(f"Drillhole feature extraction failed: {e}")
            return {}
    
    def _extract_features_from_geological_model(self, n_samples: int) -> Dict[str, np.ndarray]:
        """Extract geological features from geological model samples."""
        try:
            features = {}
            all_samples = []
            
            if hasattr(self.geological_model, 'samples') and self.geological_model.samples:
                for sample in self.geological_model.samples:
                    sample_data = {
                        'depth': float(sample.location[2]) if len(sample.location) > 2 else 0,
                        'lithology_code': 1,  # Default
                        'temperature': 20 + abs(sample.location[2]) * 0.025 if len(sample.location) > 2 else 20,
                        'pressure': abs(sample.location[2]) * 0.025 if len(sample.location) > 2 else 10,
                        'porosity': 0.2,  # Default
                        'grain_size': 1.0,  # Default
                        'weathering_degree': max(0, 1.0 - abs(sample.location[2])/100) if len(sample.location) > 2 else 0.5,
                        'structural_complexity': 0.3,  # Default
                        'metamorphic_grade': 0.0,  # Default
                        'age': 500  # Default
                    }
                    
                    # Override with actual grade data if available
                    if sample.grade_data:
                        for key in sample_data:
                            if key in sample.grade_data:
                                sample_data[key] = float(sample.grade_data[key])
                    
                    all_samples.append(sample_data)
            
            # Convert to feature arrays
            if all_samples:
                for key in all_samples[0].keys():
                    values = [sample[key] for sample in all_samples]
                    if len(values) >= n_samples:
                        features[key] = np.array(values[:n_samples])
                    else:
                        # Extend with interpolation
                        if len(values) > 1:
                            extended_values = np.interp(
                                np.linspace(0, len(values)-1, n_samples),
                                range(len(values)),
                                values
                            )
                            features[key] = extended_values
                        else:
                            features[key] = np.full(n_samples, values[0] if values else 0)
            
            return features
            
        except Exception as e:
            logging.warning(f"Geological model feature extraction failed: {e}")
            return {}
    
