    def _analyze_deformation_for_parameter_drift(self, deformation_data: Dict[str, pd.DataFrame]) -> Dict:
        """Analyze deformation measurements for parameter drift detection."""
        updates = {}
        
        try:
            if not deformation_data:
                return updates
            
            # Combine all station data for regional trend analysis
            all_displacements = []
            for station_id, data in deformation_data.items():
                if not data.empty:
                    # Calculate displacement rates (mm/day)
                    if len(data) > 1:
                        time_diff = (data['timestamp'].max() - data['timestamp'].min()).total_seconds() / 86400  # days
                        if time_diff > 0:
                            dx_rate = (data['displacement_x'].iloc[-1] - data['displacement_x'].iloc[0]) / time_diff
                            dy_rate = (data['displacement_y'].iloc[-1] - data['displacement_y'].iloc[0]) / time_diff  
                            dz_rate = (data['displacement_z'].iloc[-1] - data['displacement_z'].iloc[0]) / time_diff
                            
                            all_displacements.append({
                                'station_id': station_id,
                                'dx_rate': dx_rate,
                                'dy_rate': dy_rate, 
                                'dz_rate': dz_rate,
                                'total_rate': np.sqrt(dx_rate**2 + dy_rate**2 + dz_rate**2)
                            })
            
            if all_displacements:
                # Analyze regional deformation patterns
                total_rates = [d['total_rate'] for d in all_displacements]
                mean_rate = np.mean(total_rates)
                max_rate = np.max(total_rates)
                
                # Detect significant deformation requiring parameter updates
                if max_rate > 5.0:  # >5 mm/day indicates rapid deformation
                    updates['elastic_modulus_factor'] = 0.9  # Softer response to rapid deformation
                    updates['deformation_update_reason'] = f'Rapid deformation detected ({max_rate:.1f} mm/day max)'
                elif mean_rate > 2.0:  # >2 mm/day average indicates ongoing deformation
                    updates['elastic_modulus_factor'] = 0.95
                    updates['deformation_update_reason'] = f'Sustained deformation ({mean_rate:.1f} mm/day average)'
                
                # Detect vertical vs horizontal deformation patterns
                vertical_rates = [d['dz_rate'] for d in all_displacements]
                horizontal_rates = [np.sqrt(d['dx_rate']**2 + d['dy_rate']**2) for d in all_displacements]
                
                mean_vertical = np.mean(np.abs(vertical_rates))
                mean_horizontal = np.mean(horizontal_rates)
                
                if mean_vertical > mean_horizontal * 1.5:  # Vertical dominates
                    updates['poisson_ratio_adjustment'] = 0.02  # Adjust for vertical deformation
                    updates['vertical_deformation_dominance'] = True
                elif mean_horizontal > mean_vertical * 2.0:  # Horizontal dominates  
                    updates['poisson_ratio_adjustment'] = -0.02  # Adjust for horizontal deformation
                    updates['horizontal_deformation_dominance'] = True
            
        except Exception as e:
            logging.error(f"Failed to analyze deformation for parameter drift: {e}")
        
        return updates
    
    def _check_model_calibration_updates(self, start_time: datetime, end_time: datetime) -> Dict:
        """Check for model calibration updates from external validation data."""
        updates = {}
        
