    def _calculate_comprehensive_rock_rheology_stress_evolution(self, significant_events: List[Dict], 
                                                              max_magnitude: float, 
                                                              current_time: float) -> Dict:
        """
        Calculate comprehensive stress field evolution using real rock rheology models.
        
        Integrates multiple rheological mechanisms including viscoelastic relaxation,
        poroelastic effects, and temperature-dependent creep processes.
        """
        try:
            from .multi_physics_coupling_engine import MultiPhysicsCouplingEngine
            from .database_integration import DatabaseIntegration
            
            # Initialize multi-physics engine for rheological calculations
            coupling_engine = MultiPhysicsCouplingEngine()
            db_integration = DatabaseIntegration()
            
            # Query real rock properties database for rheological parameters
            rock_properties = self._query_rheological_properties_database(significant_events)
            
            if not rock_properties or not rock_properties.get('success'):
                return {'success': False, 'error': 'Rheological database query failed'}
            
            # Extract key rheological parameters
            viscosity = rock_properties.get('bulk_viscosity', 1e19)  # Pa⋅s
            shear_modulus = rock_properties.get('shear_modulus', 3e10)  # Pa
            bulk_modulus = rock_properties.get('bulk_modulus', 6e10)  # Pa
            temperature = rock_properties.get('temperature', 573.15)  # K
            pressure = rock_properties.get('confining_pressure', 200e6)  # Pa
            
            # Calculate Maxwell relaxation time: τ = η/G
            maxwell_time = viscosity / shear_modulus  # seconds
            
            # Time since largest earthquake
            largest_event = max(significant_events, key=lambda e: e.get('magnitude', 0))
            event_time = largest_event.get('time', current_time - 86400)  # Default to 1 day ago
            time_elapsed = current_time - event_time
            
            # Advanced viscoelastic stress relaxation calculation
            # Using generalized Maxwell model with temperature and pressure dependencies
            
            # Temperature-dependent viscosity (Arrhenius relationship)
            activation_energy = rock_properties.get('activation_energy', 300e3)  # J/mol
            gas_constant = 8.314  # J/(mol⋅K)
            reference_temp = 573.15  # K (300°C reference)
            
            temp_factor = np.exp(activation_energy / gas_constant * (1.0/temperature - 1.0/reference_temp))
            effective_viscosity = viscosity * temp_factor
            
            # Pressure-dependent modulus
            pressure_derivative = rock_properties.get('pressure_modulus_derivative', 4.0)
            reference_pressure = 100e6  # Pa
            pressure_factor = 1.0 + pressure_derivative * np.log(pressure / reference_pressure)
            effective_shear_modulus = shear_modulus * pressure_factor
            
            # Effective Maxwell time with T,P corrections
            effective_maxwell_time = effective_viscosity / effective_shear_modulus
            
            # Multi-mechanism stress relaxation
            relaxation_mechanisms = {}
            
            # 1. Pure Maxwell viscoelastic relaxation
            maxwell_relaxation = np.exp(-time_elapsed / effective_maxwell_time)
            relaxation_mechanisms['maxwell'] = maxwell_relaxation
            
            # 2. Kelvin-Voigt component (retardation)
            retardation_time = rock_properties.get('retardation_time', effective_maxwell_time * 0.1)
            kelvin_relaxation = 1.0 - np.exp(-time_elapsed / retardation_time)
            relaxation_mechanisms['kelvin'] = kelvin_relaxation
            
            # 3. Power-law creep (long-term)
            if time_elapsed > effective_maxwell_time:
                stress_exponent = rock_properties.get('stress_exponent', 3.5)
                grain_size = rock_properties.get('grain_size', 1e-3)  # m
                diffusion_creep = self._calculate_diffusion_creep_contribution(
                    time_elapsed, temperature, pressure, grain_size, max_magnitude
                )
                relaxation_mechanisms['power_law_creep'] = diffusion_creep
            
            # 4. Poroelastic effects for fluid-bearing rocks
            porosity = rock_properties.get('porosity', 0.05)
            if porosity > 0.01:  # Significant porosity
                poroelastic_relaxation = self._calculate_poroelastic_stress_diffusion(
                    time_elapsed, porosity, rock_properties
                )
                relaxation_mechanisms['poroelastic'] = poroelastic_relaxation
            
            # 5. Thermal effects (thermal expansion/contraction)
            thermal_expansion = rock_properties.get('thermal_expansion', 3e-5)  # /K
            temp_anomaly = rock_properties.get('temperature_anomaly', 0)  # K
            if abs(temp_anomaly) > 10:
                thermal_stress_factor = 1.0 + thermal_expansion * temp_anomaly * 0.1
                relaxation_mechanisms['thermal'] = thermal_stress_factor
            
            # Combine all mechanisms using weighted ensemble
            mechanism_weights = {
                'maxwell': 0.4,
                'kelvin': 0.2,
                'power_law_creep': 0.2,
                'poroelastic': 0.15,
                'thermal': 0.05
            }
            
            total_relaxation_factor = 0.0
            total_weight = 0.0
            
            for mechanism, factor in relaxation_mechanisms.items():
                weight = mechanism_weights.get(mechanism, 0.1)
                total_relaxation_factor += weight * factor
                total_weight += weight
            
            if total_weight > 0:
                stress_relaxation_factor = total_relaxation_factor / total_weight
            else:
                stress_relaxation_factor = maxwell_relaxation
            
            # Ensure physical bounds [0.1, 1.0]
            stress_relaxation_factor = max(0.1, min(1.0, stress_relaxation_factor))
            
            # Magnitude-dependent adjustment
            magnitude_factor = self._calculate_magnitude_dependent_rheological_scaling(max_magnitude)
            final_relaxation_factor = stress_relaxation_factor * magnitude_factor
            
            return {
                'success': True,
                'stress_relaxation_factor': final_relaxation_factor,
                'rheology_model': 'multi_mechanism_viscoelastic',
                'rheological_properties': {
                    'effective_viscosity': effective_viscosity,
                    'effective_shear_modulus': effective_shear_modulus,
                    'maxwell_time': effective_maxwell_time,
                    'temperature': temperature,
                    'pressure': pressure
                },
                'viscoelastic_parameters': {
                    'relaxation_time': effective_maxwell_time,
                    'retardation_time': retardation_time,
                    'temperature_factor': temp_factor,
                    'pressure_factor': pressure_factor
                },
                'evolution_model': {
                    'mechanisms': relaxation_mechanisms,
                    'weights': mechanism_weights,
                    'time_elapsed': time_elapsed,
                    'magnitude_factor': magnitude_factor
                }
            }
            
        except Exception as e:
            logging.error(f"Comprehensive rock rheology calculation failed: {e}")
            return {'success': False, 'error': str(e)}
    
    def _calculate_time_dependent_rheological_relaxation(self, current_time: float, 
                                                       last_check_time: float) -> Dict:
        """
        Calculate time-dependent rheological relaxation for ongoing stress evolution.
        """
        try:
            time_elapsed = current_time - last_check_time
            
            # Query geological context for current location
            geological_context = self._get_current_geological_context()
            
            # Default rheological parameters based on geological setting
            if geological_context.get('tectonic_setting') == 'active_fault_zone':
                base_relaxation_rate = 1e-8  # /s (fast relaxation in active zones)
                mechanism = 'fault_zone_viscoelasticity'
            elif geological_context.get('rock_type') == 'volcanic':
                base_relaxation_rate = 5e-9  # /s (moderate relaxation in volcanic rocks)
                mechanism = 'volcanic_rheology'
            else:
                base_relaxation_rate = 1e-9  # /s (slow relaxation in stable crust)
                mechanism = 'stable_crustal_rheology'
            
            # Temperature-dependent adjustment
            temperature = geological_context.get('temperature', 298.15)  # K
            temp_factor = np.exp(-3000 / temperature)  # Arrhenius-type scaling
            
            # Pressure-dependent adjustment  
            depth = geological_context.get('depth', 5000)  # m
            pressure_factor = 1.0 + 0.0001 * depth  # Increase with depth
            
            effective_relaxation_rate = base_relaxation_rate * temp_factor * pressure_factor
            
            # Calculate relaxation factor
            relaxation_factor = 1.0 - effective_relaxation_rate * time_elapsed
            relaxation_factor = max(0.9, min(1.0, relaxation_factor))  # Physical bounds
            
            # Maxwell time constant
            time_constant = 1.0 / effective_relaxation_rate
            
            return {
                'success': True,
                'relaxation_factor': relaxation_factor,
                'mechanism': mechanism,
                'time_constant': time_constant,
                'geological_context': geological_context
            }
            
        except Exception as e:
            logging.error(f"Time-dependent rheological relaxation failed: {e}")
            return {'success': False}
    
    def _query_rheological_properties_database(self, significant_events: List[Dict]) -> Dict:
        """
        Query comprehensive rheological properties database for earthquake locations.
        """
        try:
            from .database_integration import DatabaseIntegration
            
            db = DatabaseIntegration()
            
            # Get representative location from largest event
            largest_event = max(significant_events, key=lambda e: e.get('magnitude', 0))
            lat = largest_event.get('latitude', 37.0)
            lon = largest_event.get('longitude', -122.0)
            depth = largest_event.get('depth', 10000)  # m
            
            # Query rheological database
            rheology_query = f"""
            SELECT 
                bulk_viscosity,
                shear_modulus,
                bulk_modulus,
                temperature,
                confining_pressure,
                activation_energy,
                pressure_modulus_derivative,
                retardation_time,
                stress_exponent,
                grain_size,
                porosity,
                thermal_expansion,
                temperature_anomaly,
                rock_type,
                tectonic_setting
            FROM rheological_properties_global 
            WHERE ST_DWithin(ST_Point(%s, %s), location, 50000)  -- 50 km radius
            AND depth_min <= %s AND depth_max >= %s
            ORDER BY ST_Distance(ST_Point(%s, %s), location)
            LIMIT 1;
            """
            
            results = db.execute_query(rheology_query, (lon, lat, depth, depth, lon, lat))
            
            if results:
                result = results[0]
                return {
                    'success': True,
                    'bulk_viscosity': result.get('bulk_viscosity', 1e19),
                    'shear_modulus': result.get('shear_modulus', 3e10),
                    'bulk_modulus': result.get('bulk_modulus', 6e10),
                    'temperature': result.get('temperature', 573.15),
                    'confining_pressure': result.get('confining_pressure', 200e6),
                    'activation_energy': result.get('activation_energy', 300e3),
                    'pressure_modulus_derivative': result.get('pressure_modulus_derivative', 4.0),
                    'retardation_time': result.get('retardation_time', 1e12),
                    'stress_exponent': result.get('stress_exponent', 3.5),
                    'grain_size': result.get('grain_size', 1e-3),
                    'porosity': result.get('porosity', 0.05),
                    'thermal_expansion': result.get('thermal_expansion', 3e-5),
                    'temperature_anomaly': result.get('temperature_anomaly', 0),
                    'rock_type': result.get('rock_type', 'granite'),
                    'tectonic_setting': result.get('tectonic_setting', 'stable_crust')
                }
            else:
                return {'success': False, 'error': 'No rheological data found'}
                
        except Exception as e:
            logging.error(f"Rheological database query failed: {e}")
            return {'success': False, 'error': str(e)}
    
    def _calculate_diffusion_creep_contribution(self, time_elapsed: float, temperature: float,
                                              pressure: float, grain_size: float, 
                                              magnitude: float) -> float:
        """
        Calculate power-law diffusion creep contribution to stress relaxation.
        """
        try:
            # Nabarro-Herring diffusion creep model
            # ε̇ = A * (σ/G)^n * (d/d₀)^-m * exp(-Q/RT)
            
            stress_from_magnitude = 10**(1.5 * magnitude + 9)  # Rough stress estimate from magnitude
            reference_stress = 1e6  # Pa
            normalized_stress = stress_from_magnitude / reference_stress
            
            # Material constants (for olivine/quartz)
            creep_constant = 1e-14  # /s
            stress_exponent = 1.0  # Diffusion creep (n=1)
            grain_size_exponent = 2.0  # Nabarro-Herring (m=2) 
            activation_energy = 300e3  # J/mol
            gas_constant = 8.314  # J/(mol⋅K)
            
            reference_grain_size = 1e-3  # m
            grain_size_factor = (reference_grain_size / grain_size)**grain_size_exponent
            
            temperature_factor = np.exp(-activation_energy / (gas_constant * temperature))
            
            creep_rate = (creep_constant * normalized_stress**stress_exponent * 
                         grain_size_factor * temperature_factor)
            
            # Convert to relaxation factor
            creep_relaxation = creep_rate * time_elapsed
            return max(0.0, min(0.5, creep_relaxation))  # Limit contribution
            
        except Exception as e:
            logging.error(f"Diffusion creep calculation failed: {e}")
            return 0.01
    
    def _calculate_poroelastic_stress_diffusion(self, time_elapsed: float, porosity: float,
                                              rock_properties: Dict) -> float:
        """
        Calculate poroelastic stress diffusion effects.
        """
        try:
            # Poroelastic diffusion equation: c = k/(μφct)
            # where c is diffusivity, k is permeability, μ is viscosity,
            # φ is porosity, ct is total compressibility
            
            permeability = rock_properties.get('permeability', 1e-15)  # m²
            fluid_viscosity = rock_properties.get('fluid_viscosity', 1e-3)  # Pa⋅s  
            total_compressibility = rock_properties.get('total_compressibility', 1e-9)  # /Pa
            
            # Hydraulic diffusivity
            hydraulic_diffusivity = permeability / (fluid_viscosity * porosity * total_compressibility)
            
            # Characteristic diffusion length
            diffusion_length = np.sqrt(hydraulic_diffusivity * time_elapsed)
            
            # Poroelastic relaxation function
            # R(t) = 1 - exp(-√(ct/τ)) where τ is poroelastic time
            poroelastic_time = porosity * total_compressibility * fluid_viscosity / permeability
            poroelastic_relaxation = 1.0 - np.exp(-np.sqrt(time_elapsed / poroelastic_time))
            
            return max(0.0, min(0.8, poroelastic_relaxation))
            
        except Exception as e:
            logging.error(f"Poroelastic diffusion calculation failed: {e}")
            return 0.1
    
    def _calculate_magnitude_dependent_rheological_scaling(self, magnitude: float) -> float:
        """
        Calculate magnitude-dependent scaling for rheological effects.
        """
        try:
            # Larger earthquakes cause more stress perturbation and slower recovery
            if magnitude >= 7.0:
                return 0.7  # Major perturbation, slow recovery
            elif magnitude >= 6.0:
                return 0.8  # Significant perturbation
            elif magnitude >= 5.0:
                return 0.9  # Moderate perturbation
            else:
                return 0.95  # Minor perturbation
                
        except Exception as e:
            logging.error(f"Magnitude scaling calculation failed: {e}")
            return 0.9
    
    def _enhanced_rheological_fallback_stress_calculation(self, significant_events: List[Dict],
                                                        max_magnitude: float) -> Dict:
        """
        Enhanced fallback stress calculation with geological context.
        """
        try:
            # Get geological context
            context = self._get_current_geological_context()
            
            # Context-dependent stress decay
            if context.get('tectonic_setting') == 'active_fault_zone':
                base_decay = 0.85  # Faster stress redistribution in active zones
            elif context.get('rock_type') == 'volcanic':
                base_decay = 0.90  # Moderate redistribution in volcanic terrain
            else:
                base_decay = 0.95  # Slower redistribution in stable crust
            
            # Magnitude adjustment
            magnitude_adjustment = max(0.05, (7.0 - max_magnitude) * 0.05)
            stress_decay = max(0.7, base_decay - magnitude_adjustment)
            
            return {
                'stress_field_decay': stress_decay,
                'stress_field_update_reason': f'Enhanced geological M{max_magnitude:.1f}: {context.get("rock_type", "unknown")}',
                'geological_context': context,
                'rheological_mechanism': 'enhanced_fallback'
            }
            
        except Exception as e:
            logging.error(f"Enhanced rheological fallback failed: {e}")
            return {
                'stress_field_decay': 0.9,
                'stress_field_update_reason': f'Basic fallback M{max_magnitude:.1f}',
                'rheological_mechanism': 'basic_fallback'
            }
    
    def _enhanced_geological_context_stress_relaxation(self, current_time: float) -> Dict:
        """
        Enhanced geological context-based stress relaxation calculation.
        """
        try:
            context = self._get_current_geological_context()
            
            # Base relaxation rates by geological setting
            relaxation_rates = {
                'active_fault_zone': 0.98,
                'volcanic': 0.985,
                'sedimentary_basin': 0.99,
                'stable_crust': 0.995,
                'oceanic_crust': 0.99,
                'continental_shield': 0.998
            }
            
            setting = context.get('tectonic_setting', 'stable_crust')
            relaxation_factor = relaxation_rates.get(setting, 0.995)
            
            return {
                'relaxation_factor': relaxation_factor,
                'context': context,
                'mechanism': f'geological_context_{setting}'
            }
            
        except Exception as e:
            logging.error(f"Enhanced geological context relaxation failed: {e}")
            return {
                'relaxation_factor': 0.99,
                'context': {'error': str(e)},
                'mechanism': 'error_fallback'
            }
    
