    # ============== ADDITIONAL GEOSTATISTICAL METHODS ==============
    
    def _simple_kriging_estimate(self, location: np.ndarray, ref_coords: np.ndarray, 
                                ref_values: np.ndarray, variogram_params: Dict) -> Tuple[float, float]:
        """Simple kriging estimation at a location."""
        try:
            if len(ref_coords) == 0:
                return 0.0, 1.0
            
            # Calculate distances from location to reference points
            distances = np.sqrt(np.sum((ref_coords - location)**2, axis=1))
            
            # Compute variogram values
            gamma_values = self._compute_variogram_values(distances, variogram_params)
            
            # Set up kriging system: [A] * [w] = [b]
            n_points = len(ref_coords)
            A = np.zeros((n_points + 1, n_points + 1))
            b = np.zeros(n_points + 1)
            
            # Fill variogram matrix
            for i in range(n_points):
                for j in range(n_points):
                    if i == j:
                        A[i, j] = variogram_params.get('nugget', 0)
                    else:
                        dist_ij = np.sqrt(np.sum((ref_coords[i] - ref_coords[j])**2))
                        A[i, j] = self._compute_variogram_values(np.array([dist_ij]), variogram_params)[0]
                
                # Lagrange multiplier row/column
                A[i, n_points] = 1.0
                A[n_points, i] = 1.0
                
                # Right-hand side
                b[i] = gamma_values[i]
            
            # Constraint for unbiasedness
            A[n_points, n_points] = 0.0
            b[n_points] = 1.0
            
            # Solve kriging system
            try:
                weights = np.linalg.solve(A, b)
                kriging_estimate = np.sum(weights[:-1] * ref_values)
                kriging_variance = np.sum(weights[:-1] * gamma_values) + weights[-1]
                
                return kriging_estimate, max(kriging_variance, 0.0)
                
            except np.linalg.LinAlgError:
                # Fallback to inverse distance weighting
                if np.min(distances) < 1e-6:
                    return ref_values[np.argmin(distances)], 0.0
                else:
                    weights = 1.0 / (distances**2 + 1e-6)
                    weights /= np.sum(weights)
                    return np.sum(weights * ref_values), 0.1
                    
        except Exception as e:
            logging.debug(f"Simple kriging failed: {e}")
            return 0.0, 1.0
    
    def _compute_variogram_values(self, distances: np.ndarray, variogram_params: Dict) -> np.ndarray:
        """Compute variogram values for given distances."""
        try:
            model = variogram_params.get('model', 'spherical')
            sill = variogram_params.get('sill', 1.0)
            range_val = variogram_params.get('range', 1000.0)
            nugget = variogram_params.get('nugget', 0.0)
            
            h = distances / range_val
            
            if model == 'spherical':
                gamma = np.where(h <= 1, 1.5 * h - 0.5 * h**3, 1.0)
            elif model == 'exponential':
                gamma = 1.0 - np.exp(-3.0 * h)
            elif model == 'gaussian':
                gamma = 1.0 - np.exp(-3.0 * h**2)
            else:  # linear fallback
                gamma = h
                
            return nugget + (sill - nugget) * gamma
            
        except Exception as e:
            logging.debug(f"Variogram computation failed: {e}")
            return np.ones_like(distances)
    
    def _unconditional_geostatistical_simulation(self, sample_locations: np.ndarray, 
                                               value_range: Tuple[float, float], 
                                               variogram_params: Dict, property_name: str,
                                               parameter_name: str) -> np.ndarray:
        """Unconditional geostatistical simulation using FFT methods."""
        try:
            n_samples = len(sample_locations)
            
            # Generate base trend based on property and parameter
            if property_name == 'depth':
                if 'volcanic' in parameter_name.lower():
                    base_values = np.random.gamma(2, 1000, n_samples)
                else:
                    base_values = np.random.exponential(2000, n_samples)
            else:
                base_values = np.random.uniform(value_range[0], value_range[1], n_samples)
                
            # Add spatial correlation using simple moving average
            if n_samples > 1:
                correlation_field = self._generate_spatially_correlated_field(
                    sample_locations, variogram_params
                )
                correlated_values = base_values + correlation_field * 0.3
            else:
                correlated_values = base_values
                
            return np.clip(correlated_values, value_range[0], value_range[1])
            
        except Exception as e:
            logging.error(f"Unconditional geostatistical simulation failed: {e}")
            return np.random.uniform(value_range[0], value_range[1], len(sample_locations))
    
    def _generate_spatially_correlated_field(self, sample_locations: np.ndarray, 
                                           variogram_params: Dict, std_dev: float = 1.0) -> np.ndarray:
        """Generate spatially correlated field using distance-based correlation."""
        try:
            n_samples = len(sample_locations)
            if n_samples <= 1:
                return np.random.normal(0, std_dev, n_samples)
                
            # Compute distance matrix
            distances = np.sqrt(np.sum((sample_locations[:, np.newaxis] - sample_locations)**2, axis=2))
            
            # Compute correlation matrix
            correlation_range = variogram_params.get('range', 5000.0)
            correlation_matrix = np.exp(-distances / correlation_range)
            
            # Add nugget effect to diagonal
            np.fill_diagonal(correlation_matrix, 1.0)
            
            # Generate correlated random field
            try:
                L = np.linalg.cholesky(correlation_matrix + 1e-6 * np.eye(n_samples))
                random_field = L @ np.random.normal(0, std_dev, n_samples)
            except np.linalg.LinAlgError:
                # Fallback to simpler correlation
                random_field = np.random.normal(0, std_dev, n_samples)
                for i in range(1, n_samples):
                    correlation = np.exp(-distances[i, 0] / correlation_range)
                    random_field[i] = correlation * random_field[0] + np.sqrt(1 - correlation**2) * random_field[i]
                    
            return random_field
            
        except Exception as e:
            logging.debug(f"Spatially correlated field generation failed: {e}")
            return np.random.normal(0, std_dev, len(sample_locations))
    
    def _simple_spatial_correlation(self, sample_locations: np.ndarray, 
                                  correlation_range: float, variance: float) -> np.ndarray:
        """Simple spatial correlation for fallback scenarios."""
        try:
            n_samples = len(sample_locations)
            if n_samples <= 1:
                return np.random.normal(0, np.sqrt(variance), n_samples)
            
            # Generate spatially correlated noise using exponential correlation
            base_field = np.random.normal(0, np.sqrt(variance), n_samples)
            
            # Simple distance-based smoothing
            for i in range(n_samples):
                neighbors = []
                for j in range(n_samples):
                    if i != j:
                        distance = np.sqrt(np.sum((sample_locations[i] - sample_locations[j])**2))
                        if distance < correlation_range:
                            weight = np.exp(-distance / correlation_range)
                            neighbors.append(weight * base_field[j])
                
                if neighbors:
                    base_field[i] = 0.7 * base_field[i] + 0.3 * np.mean(neighbors)
                    
            return base_field
            
        except Exception as e:
            logging.debug(f"Simple spatial correlation failed: {e}")
            return np.random.normal(0, np.sqrt(variance), len(sample_locations))
    
    # Placeholder methods for advanced geostatistical techniques
    def _get_temperature_variogram_parameters(self, constraints: Dict) -> Dict:
        """Get temperature variogram parameters."""
        return {'model': 'exponential', 'sill': 25.0, 'range': 10000.0, 'nugget': 1.0}
    
    def _kriging_interpolation(self, sample_locations: np.ndarray, reference_points: np.ndarray,
                             fallback_model: callable) -> np.ndarray:
        """Kriging interpolation with fallback model."""
        try:
            return np.array([fallback_model(0) for _ in range(len(sample_locations))])
        except:
            return np.full(len(sample_locations), 100.0)
    
    def _co_simulation_pressure_depth(self, sample_locations: np.ndarray, depths: np.ndarray,
                                    constraints: Dict, reference_data: Dict) -> np.ndarray:
        """Co-simulation of pressure and depth."""
        return (depths * 26.5) / 1000 + np.random.normal(0, 5, len(depths))
    
    def _get_porosity_geostatistical_parameters(self, constraints: Dict) -> Dict:
        """Get porosity geostatistical parameters."""
        return {'surface_porosity': 0.3, 'decay_rate': 1e-4}
    
    def _simulate_porosity_with_compaction(self, sample_locations: np.ndarray, depths: np.ndarray,
                                         params: Dict, reference_data: Dict) -> np.ndarray:
        """Simulate porosity with compaction laws."""
        surface_porosity = params.get('surface_porosity', 0.3)
        decay_rate = params.get('decay_rate', 1e-4)
        return surface_porosity * np.exp(-depths * decay_rate)
    
    def _get_grain_size_variogram_parameters(self, constraints: Dict) -> Dict:
        """Get grain size variogram parameters."""
        return {'model': 'spherical', 'sill': 1.0, 'range': 2000.0, 'nugget': 0.1}
    
    def _log_normal_geostatistical_simulation(self, sample_locations: np.ndarray,
                                            variogram: Dict, reference_data: Dict) -> np.ndarray:
        """Log-normal geostatistical simulation for grain size."""
        return np.random.lognormal(0, 1, len(sample_locations))
    
    def _indicator_kriging_weathering(self, sample_locations: np.ndarray, depths: np.ndarray,
                                    constraints: Dict, reference_data: Dict) -> np.ndarray:
        """Indicator kriging for weathering degree."""
        surface_weathering = constraints.get('surface_weathering', 0.8)
        return surface_weathering * np.exp(-depths / 50)
    
    def _fractal_simulation_structural_complexity(self, sample_locations: np.ndarray,
                                                constraints: Dict, reference_data: Dict) -> np.ndarray:
        """Fractal simulation for structural complexity."""
        tectonic_setting = constraints.get('tectonic_setting', 'stable')
        if tectonic_setting == 'active':
            return np.random.beta(3, 2, len(sample_locations))
        else:
            return np.random.beta(1, 4, len(sample_locations))
    
    def _co_simulation_metamorphic_grade(self, sample_locations: np.ndarray, temperatures: np.ndarray,
                                       pressures: np.ndarray, constraints: Dict, reference_data: Dict) -> np.ndarray:
        """Co-simulation of metamorphic grade with temperature and pressure."""
        return np.maximum(0, (temperatures - 200) / 500)
    
    def _markov_random_field_age_simulation(self, sample_locations: np.ndarray, constraints: Dict,
                                          parameter_name: str, reference_data: Dict) -> np.ndarray:
        """Markov random field simulation for geological age."""
        age_range = constraints.get('age_range_ma', [0, 3500])
        if 'volcanic' in parameter_name.lower():
            return np.random.gamma(1, 50, len(sample_locations))
        else:
            return np.random.uniform(age_range[0], age_range[1], len(sample_locations))
    
    def _indicator_co_simulation_lithology(self, sample_locations: np.ndarray, 
                                         geological_features: Dict, constraints: Dict, 
                                         reference_data: Dict) -> np.ndarray:
        """Indicator co-simulation for lithology codes."""
        lithology_weights = constraints.get('lithology_weights', {
            1: 0.15, 2: 0.12, 3: 0.10, 4: 0.08, 5: 0.08, 6: 0.06, 7: 0.05, 8: 0.05,
            9: 0.04, 10: 0.04, 11: 0.03, 12: 0.03, 13: 0.03, 14: 0.02, 15: 0.12
        })
        return np.random.choice(
            list(lithology_weights.keys()),
            size=len(sample_locations),
            p=list(lithology_weights.values())
        )
    
    def _validate_geostatistical_continuity(self, geological_features: Dict, 
                                          sample_locations: np.ndarray, constraints: Dict) -> Dict:
        """Validate spatial continuity and geological consistency of geostatistical results."""
        try:
            # Check for reasonable value ranges
            for feature_name, values in geological_features.items():
                if feature_name == 'depth':
                    geological_features[feature_name] = np.clip(values, 0, 15000)
                elif feature_name == 'temperature':
                    geological_features[feature_name] = np.clip(values, 0, 1000)
                elif feature_name == 'pressure':
                    geological_features[feature_name] = np.clip(values, 0.1, 2000)
                elif feature_name == 'porosity':
                    geological_features[feature_name] = np.clip(values, 0.001, 0.5)
                elif feature_name in ['weathering_degree', 'structural_complexity', 'metamorphic_grade']:
                    geological_features[feature_name] = np.clip(values, 0, 1)
            
            # Ensure geological consistency
            if 'temperature' in geological_features and 'depth' in geological_features:
                # Temperature should generally increase with depth
                min_temp_gradient = 10  # °C/km
                expected_temps = 15 + (geological_features['depth'] / 1000.0) * min_temp_gradient
                geological_features['temperature'] = np.maximum(
                    geological_features['temperature'], expected_temps
                )
            
            if 'pressure' in geological_features and 'depth' in geological_features:
                # Pressure should increase with depth (lithostatic)
                min_pressure = (geological_features['depth'] * 26.5) / 1000 * 0.8
                geological_features['pressure'] = np.maximum(
                    geological_features['pressure'], min_pressure
                )
            
            return geological_features
            
        except Exception as e:
            logging.warning(f"Geostatistical continuity validation failed: {e}")
            return geological_features
    
    def _get_material_properties_for_stress_calculation(self) -> Dict[str, Any]:
        """Get comprehensive material properties for stress tensor calculations."""
        try:
            # Try to get from stored parameters
            base_props = {
                'youngs_modulus': getattr(self, 'parameters', {}).get('youngs_modulus', 70e9),  # Pa
                'poisson_ratio': getattr(self, 'parameters', {}).get('poisson_ratio', 0.25),
                'density': getattr(self, 'parameters', {}).get('density', 2700),  # kg/m³
                'temperature': getattr(self, 'parameters', {}).get('temperature', 293),  # K
            }
            
            # Add enhanced properties if available
            enhanced_props = {
                'shear_modulus': base_props['youngs_modulus'] / (2 * (1 + base_props['poisson_ratio'])),
                'bulk_modulus': base_props['youngs_modulus'] / (3 * (1 - 2 * base_props['poisson_ratio'])),
                'lame_lambda': (base_props['youngs_modulus'] * base_props['poisson_ratio']) / 
                              ((1 + base_props['poisson_ratio']) * (1 - 2 * base_props['poisson_ratio']))
            }
            
            base_props.update(enhanced_props)
            return base_props
            
        except Exception as e:
            logging.warning(f"Material properties retrieval failed: {e}")
            return {
                'youngs_modulus': 70e9,
                'poisson_ratio': 0.25,
                'density': 2700,
                'temperature': 293,
                'shear_modulus': 28e9,
                'bulk_modulus': 47e9,
                'lame_lambda': 28e9
            }
    
    def _apply_stress_field_corrections(self, displacements: np.ndarray, 
                                       stress_results: Dict[str, Any]) -> np.ndarray:
        """Apply stress field-based corrections to displacement calculations."""
        try:
            if 'error' in stress_results:
                return displacements
                
            # Get stress-based correction factors
            stress_tensor = stress_results.get('stress_tensor_full')
            von_mises = stress_results.get('von_mises_stress')
            
            if stress_tensor is None or von_mises is None:
                return displacements
            
            corrected_displacements = displacements.copy()
            
            # Apply corrections based on stress concentration
            stress_metrics = stress_results.get('stress_metrics', {})
            concentration_factors = stress_metrics.get('stress_concentration_factor', np.ones(len(displacements)))
            
            # Moderate corrections for high stress concentrations
            for i, factor in enumerate(concentration_factors):
                if factor > 3.0:  # High stress concentration
                    correction_scale = min(0.9, 1.0 / np.sqrt(factor))
                    corrected_displacements[i] *= correction_scale
            
            # Apply geological stress regime corrections
            geological_interp = stress_results.get('geological_interpretation', {})
            dominant_regime = geological_interp.get('dominant_regime', 'unknown')
            
            if dominant_regime == 'normal_faulting':
                # Normal faulting typically shows enhanced vertical displacements
                corrected_displacements[:, 2] *= 1.1
            elif dominant_regime == 'reverse_faulting':
                # Reverse faulting shows enhanced horizontal displacements
                corrected_displacements[:, :2] *= 1.05
            
            return corrected_displacements
            
        except Exception as e:
            logging.warning(f"Stress field corrections failed: {e}")
            return displacements
    
    def _detect_stress_field_anomalies(self, stress_results: Dict[str, Any]) -> Dict[str, Any]:
        """Detect anomalies in stress field that could indicate model issues."""
        try:
            anomalies = {
                'has_anomalies': False,
                'anomaly_types': [],
                'anomaly_locations': [],
                'anomaly_scores': [],
                'anomaly_summary': 'No anomalies detected'
            }
            
            if 'error' in stress_results:
                return anomalies
            
            # Check for excessive stress concentrations
            stress_metrics = stress_results.get('stress_metrics', {})
            concentration_factors = stress_metrics.get('stress_concentration_factor', [])
            
            if len(concentration_factors) > 0:
                high_concentration_indices = np.where(concentration_factors > 5.0)[0]
                if len(high_concentration_indices) > 0:
                    anomalies['has_anomalies'] = True
                    anomalies['anomaly_types'].append('high_stress_concentration')
                    anomalies['anomaly_locations'].extend(high_concentration_indices.tolist())
                    anomalies['anomaly_scores'].extend(concentration_factors[high_concentration_indices].tolist())
            
            # Check for unrealistic principal stress values
            principal_stresses = stress_results.get('principal_stresses')
            if principal_stresses is not None:
                # Check for negative minimum principal stress (tensile stress)
                min_principal = np.min(principal_stresses, axis=1)
                tensile_indices = np.where(min_principal < -10e6)[0]  # > 10 MPa tension
                
                if len(tensile_indices) > 0:
                    anomalies['has_anomalies'] = True
                    anomalies['anomaly_types'].append('excessive_tensile_stress')
                    anomalies['anomaly_locations'].extend(tensile_indices.tolist())
                    anomalies['anomaly_scores'].extend((-min_principal[tensile_indices] / 1e6).tolist())
                
                # Check for extremely high differential stress
                max_principal = np.max(principal_stresses, axis=1)
                differential_stress = max_principal - min_principal
                high_diff_indices = np.where(differential_stress > 200e6)[0]  # > 200 MPa
                
                if len(high_diff_indices) > 0:
                    anomalies['has_anomalies'] = True
                    anomalies['anomaly_types'].append('high_differential_stress')
                    anomalies['anomaly_locations'].extend(high_diff_indices.tolist())
                    anomalies['anomaly_scores'].extend((differential_stress[high_diff_indices] / 1e6).tolist())
            
            # Create summary
            if anomalies['has_anomalies']:
                unique_types = list(set(anomalies['anomaly_types']))
                anomalies['anomaly_summary'] = f"Found {len(anomalies['anomaly_locations'])} anomalies of types: {', '.join(unique_types)}"
            
            return anomalies
            
        except Exception as e:
            logging.warning(f"Stress field anomaly detection failed: {e}")
            return {
                'has_anomalies': False,
                'error': str(e),
                'anomaly_summary': 'Anomaly detection failed'
            }
    
    def _perform_comprehensive_geological_analysis(self, displacements: np.ndarray,
                                                  stress_analysis: Dict[str, Any],
                                                  observation_points: np.ndarray) -> Dict[str, Any]:
        """Perform comprehensive geological analysis of displacement and stress fields."""
        try:
            analysis = {
                'displacement_patterns': {},
                'stress_geological_context': {},
                'tectonic_implications': {},
                'hazard_assessment': {},
                'model_quality_indicators': {}
            }
            
            # Displacement pattern analysis
            displacement_magnitudes = np.linalg.norm(displacements, axis=1)
            analysis['displacement_patterns'] = {
                'max_displacement': np.max(displacement_magnitudes),
                'mean_displacement': np.mean(displacement_magnitudes),
                'displacement_gradient': self._calculate_displacement_gradients(displacements, observation_points),
                'predominant_direction': self._get_predominant_displacement_direction(displacements)
            }
            
            # Stress geological context
            if 'geological_interpretation' in stress_analysis:
                geological_interp = stress_analysis['geological_interpretation']
                analysis['stress_geological_context'] = {
                    'stress_regime': geological_interp.get('dominant_regime', 'unknown'),
                    'regime_confidence': geological_interp.get('regime_distribution', {}),
                    'mean_differential_stress': geological_interp.get('max_differential_stress', 0) / 1e6  # MPa
                }
            
            # Tectonic implications
            analysis['tectonic_implications'] = self._assess_tectonic_implications(
                displacements, stress_analysis, observation_points
            )
            
            # Hazard assessment
            analysis['hazard_assessment'] = self._assess_geological_hazards(
                displacements, stress_analysis
            )
            
            # Model quality indicators
            analysis['model_quality_indicators'] = {
                'displacement_realism': self._assess_displacement_realism(displacements),
                'stress_field_consistency': self._assess_stress_consistency(stress_analysis),
                'overall_quality_score': 0.0
            }
            
            # Calculate overall quality score
            quality_components = [
                analysis['model_quality_indicators']['displacement_realism'],
                analysis['model_quality_indicators']['stress_field_consistency']
            ]
            analysis['model_quality_indicators']['overall_quality_score'] = np.mean(quality_components)
            
            return analysis
            
        except Exception as e:
            logging.warning(f"Comprehensive geological analysis failed: {e}")
            return {'error': str(e), 'analysis_method': 'comprehensive_geological'}
    
    def integrate_anomaly_detection_with_physics_verification(self, 
                                                            displacement_results: Dict[str, Any],
                                                            observation_points: np.ndarray) -> Dict[str, Any]:
        """Integrate GeologicalAnomalyDetectionSystem with enhanced physics verification.
        
        This method connects the comprehensive stress tensor analysis and physics verification
        with advanced anomaly detection to identify unusual geological patterns and model issues.
        """
        try:
            logging.info("Integrating anomaly detection with physics verification")
            
            # Import the AnomalyDetector system
            try:
                from .geological_anomaly_detection import GeologicalAnomalyDetectionSystem
                anomaly_detector = GeologicalAnomalyDetectionSystem({
                    'enable_multivariate': True,
                    'enable_contextual': True,
                    'enable_collective': True,
                    'enable_continuous': True,
                    'real_time_processing': True
                })
            except ImportError as e:
                logging.warning(f"Could not import GeologicalAnomalyDetectionSystem: {e}")
                return {'error': 'anomaly_detector_not_available', 'fallback_analysis': True}
            
            integration_results = {
                'physics_anomalies': {},
                'geological_anomalies': {},
                'stress_field_anomalies': {},
                'integrated_assessment': {},
                'risk_indicators': {},
                'monitoring_recommendations': []
            }
            
            # 1. Extract physics verification data for anomaly analysis
            physics_data = self._extract_physics_data_for_anomaly_detection(
                displacement_results, observation_points
            )
            
            # 2. Physics-based anomaly detection
            if 'stress_analysis' in displacement_results:
                stress_analysis = displacement_results['stress_analysis']
                
                # Detect stress field anomalies using our existing method
                stress_anomalies = self._detect_stress_field_anomalies(stress_analysis)
                integration_results['stress_field_anomalies'] = stress_anomalies
                
                # Enhanced physics verification anomalies
                physics_verification_anomalies = self._detect_physics_verification_anomalies(
                    displacement_results, stress_analysis
                )
                integration_results['physics_anomalies'] = physics_verification_anomalies
            
            # 3. Geological context anomaly detection
            if 'geological_analysis' in displacement_results:
                geological_analysis = displacement_results['geological_analysis']
                geological_anomalies = self._detect_geological_context_anomalies(
                    geological_analysis, observation_points
                )
                integration_results['geological_anomalies'] = geological_anomalies
            
            # 4. Multi-variate anomaly detection using AnomalyDetector
            try:
                multivariate_results = self._run_multivariate_anomaly_detection(
                    anomaly_detector, physics_data, observation_points
                )
                integration_results['multivariate_anomalies'] = multivariate_results
            except Exception as e:
                logging.warning(f"Multivariate anomaly detection failed: {e}")
                integration_results['multivariate_anomalies'] = {'error': str(e)}
            
            # 5. Integrated risk assessment
            risk_assessment = self._perform_integrated_risk_assessment(
                integration_results, displacement_results, observation_points
            )
            integration_results['risk_indicators'] = risk_assessment
            
            # 6. Generate monitoring recommendations
            monitoring_recommendations = self._generate_integrated_monitoring_recommendations(
                integration_results, displacement_results
            )
            integration_results['monitoring_recommendations'] = monitoring_recommendations
            
            # 7. Overall anomaly severity assessment
            overall_assessment = self._assess_overall_anomaly_severity(integration_results)
            integration_results['integrated_assessment'] = overall_assessment
            
            logging.info(f"Anomaly detection integration completed. Overall severity: {overall_assessment.get('severity_level', 'unknown')}")
            return integration_results
            
        except Exception as e:
            logging.error(f"Anomaly detection integration failed: {e}")
            return {
                'error': str(e),
                'integration_method': 'physics_anomaly_detection',
                'fallback_analysis': True
            }
    
    def _extract_physics_data_for_anomaly_detection(self, displacement_results: Dict[str, Any],
                                                   observation_points: np.ndarray) -> Dict[str, np.ndarray]:
        """Extract physics data formatted for anomaly detection algorithms."""
        try:
            physics_data = {}
            
            # Displacement data
            displacements = displacement_results.get('displacements')
            if displacements is not None:
                physics_data['displacement_magnitude'] = np.linalg.norm(displacements, axis=1)
                physics_data['displacement_x'] = displacements[:, 0]
                physics_data['displacement_y'] = displacements[:, 1]
                physics_data['displacement_z'] = displacements[:, 2]
            
            # Stress tensor data
            stress_analysis = displacement_results.get('stress_analysis', {})
            if 'principal_stresses' in stress_analysis:
                principal_stresses = stress_analysis['principal_stresses']
                physics_data['max_principal_stress'] = principal_stresses[:, 0]
                physics_data['min_principal_stress'] = principal_stresses[:, 2]
                physics_data['differential_stress'] = principal_stresses[:, 0] - principal_stresses[:, 2]
            
            if 'von_mises_stress' in stress_analysis:
                physics_data['von_mises_stress'] = stress_analysis['von_mises_stress']
            
            if 'max_shear_stress' in stress_analysis:
                physics_data['max_shear_stress'] = stress_analysis['max_shear_stress']
            
            # Spatial coordinates
            physics_data['x_coordinate'] = observation_points[:, 0]
            physics_data['y_coordinate'] = observation_points[:, 1]
            physics_data['z_coordinate'] = observation_points[:, 2] if observation_points.shape[1] > 2 else np.zeros(len(observation_points))
            
            # Model quality indicators
            if 'confidence' in displacement_results:
                physics_data['model_confidence'] = displacement_results['confidence']
            
            if 'uncertainty' in displacement_results:
                uncertainty = displacement_results['uncertainty']
                physics_data['uncertainty_magnitude'] = np.linalg.norm(uncertainty, axis=1) if len(uncertainty.shape) > 1 else uncertainty
            
            return physics_data
            
        except Exception as e:
            logging.warning(f"Physics data extraction for anomaly detection failed: {e}")
            return {}
    
    def _detect_physics_verification_anomalies(self, displacement_results: Dict[str, Any],
                                             stress_analysis: Dict[str, Any]) -> Dict[str, Any]:
        """Detect anomalies in physics verification results."""
        try:
            anomalies = {
                'verification_anomalies': [],
                'low_compliance_points': [],
                'physics_violations': [],
                'has_critical_issues': False
            }
            
            # Check equation verification results if available
            if hasattr(self, '_last_verification_results'):
                verification = getattr(self, '_last_verification_results', {})
                
                # Check compliance scores
                compliance_threshold = 0.5
                for equation_type, results in verification.items():
                    if isinstance(results, dict) and 'compliance_score' in results:
                        compliance = results['compliance_score']
                        if compliance < compliance_threshold:
                            anomalies['verification_anomalies'].append({
                                'equation_type': equation_type,
                                'compliance_score': compliance,
                                'severity': 'high' if compliance < 0.2 else 'moderate'
                            })
            
            # Check stress field consistency
            if 'calculation_metadata' in stress_analysis:
                metadata = stress_analysis['calculation_metadata']
                if metadata.get('calculation_method') == 'fallback_lithostatic':
                    anomalies['physics_violations'].append({
                        'type': 'stress_calculation_fallback',
                        'description': 'Stress calculation fell back to simplified lithostatic model',
                        'severity': 'moderate'
                    })
            
            # Determine if there are critical issues
            critical_count = len([a for a in anomalies['verification_anomalies'] if a.get('severity') == 'high'])
            anomalies['has_critical_issues'] = critical_count > 0
            
            return anomalies
            
        except Exception as e:
            logging.warning(f"Physics verification anomaly detection failed: {e}")
            return {'error': str(e)}
    
    def _detect_geological_context_anomalies(self, geological_analysis: Dict[str, Any],
                                            observation_points: np.ndarray) -> Dict[str, Any]:
        """Detect anomalies in geological context and interpretation."""
        try:
            anomalies = {
                'tectonic_anomalies': [],
                'hazard_anomalies': [],
                'model_quality_issues': [],
                'has_geological_inconsistencies': False
            }
            
            # Check tectonic implications
            tectonic_implications = geological_analysis.get('tectonic_implications', {})
            fault_activity = tectonic_implications.get('fault_activity_indicators', {})
            
            if fault_activity.get('activity_level') == 'high':
                max_displacement = fault_activity.get('maximum_displacement_mm', 0)
                if max_displacement > 1000:  # > 1 meter
                    anomalies['tectonic_anomalies'].append({
                        'type': 'extreme_displacement',
                        'value_mm': max_displacement,
                        'description': f'Extremely high displacement detected: {max_displacement:.1f} mm',
                        'severity': 'critical'
                    })
            
            # Check hazard assessment
            hazard_assessment = geological_analysis.get('hazard_assessment', {})
            seismic_indicators = hazard_assessment.get('seismic_hazard_indicators', {})
            
            hazard_level = seismic_indicators.get('hazard_level', 'minimal')
            if hazard_level in ['high', 'extreme']:
                anomalies['hazard_anomalies'].append({
                    'type': 'high_seismic_hazard',
                    'level': hazard_level,
                    'description': f'High seismic hazard level detected: {hazard_level}',
                    'severity': 'high'
                })
            
            # Check model quality
            quality_indicators = geological_analysis.get('model_quality_indicators', {})
            overall_quality = quality_indicators.get('overall_quality_score', 1.0)
            
            if overall_quality < 0.6:
                anomalies['model_quality_issues'].append({
                    'type': 'low_model_quality',
                    'score': overall_quality,
                    'description': f'Low overall model quality score: {overall_quality:.2f}',
                    'severity': 'moderate' if overall_quality > 0.3 else 'high'
                })
            
            # Determine if there are geological inconsistencies
            anomalies['has_geological_inconsistencies'] = (
                len(anomalies['tectonic_anomalies']) > 0 or 
                len(anomalies['model_quality_issues']) > 0
            )
            
            return anomalies
            
        except Exception as e:
            logging.warning(f"Geological context anomaly detection failed: {e}")
            return {'error': str(e)}
    
    def _run_multivariate_anomaly_detection(self, anomaly_detector,
                                           physics_data: Dict[str, np.ndarray],
                                           observation_points: np.ndarray) -> Dict[str, Any]:
        """Run multivariate anomaly detection on physics data."""
        try:
            # Prepare data for anomaly detection
            if not physics_data:
                return {'error': 'no_physics_data'}
            
            # Convert to structured format expected by anomaly detector
            geological_data = {
                'measurements': {},
                'processes': []
            }
            
            # Create measurements for each observation point
            for i in range(len(observation_points)):
                location_id = f'location_{i}'
                measurements = {
                    'coordinates': observation_points[i].tolist()
                }
                
                # Add physics data to measurements
                for key, values in physics_data.items():
                    if len(values) > i:
                        measurements[key] = float(values[i])
                
                geological_data['measurements'][location_id] = measurements
            
            # Add process indicators based on physics data
            n_points = len(observation_points)
            for i in range(n_points):
                processes = {}
                
                # Infer geological processes from physics data
                if 'von_mises_stress' in physics_data and len(physics_data['von_mises_stress']) > i:
                    stress_level = physics_data['von_mises_stress'][i]
                    processes['deformation'] = min(1.0, stress_level / 100e6)  # Normalize by 100 MPa
                
                if 'displacement_magnitude' in physics_data and len(physics_data['displacement_magnitude']) > i:
                    disp_magnitude = physics_data['displacement_magnitude'][i]
                    processes['fault_activity'] = min(1.0, disp_magnitude / 0.1)  # Normalize by 10 cm
                
                geological_data['processes'].append(processes)
            
            # Run anomaly detection (simplified interface)
            try:
                # Use contextual detector for geological context
                contextual_results = anomaly_detector.contextual_detector._detect_contextual_anomalies(
                    geological_data, observation_points
                )
                
                return {
                    'contextual_anomalies': contextual_results,
                    'detection_method': 'geological_contextual',
                    'data_points_analyzed': n_points
                }
                
            except Exception as e:
                logging.warning(f"Advanced anomaly detection failed, using simple analysis: {e}")
                
                # Fallback to simple statistical anomaly detection
                return self._simple_statistical_anomaly_detection(physics_data)
            
        except Exception as e:
            logging.warning(f"Multivariate anomaly detection failed: {e}")
            return {'error': str(e)}
    
    def _simple_statistical_anomaly_detection(self, physics_data: Dict[str, np.ndarray]) -> Dict[str, Any]:
        """Simple statistical anomaly detection as fallback."""
        try:
            anomalies = {
                'statistical_outliers': [],
                'method': 'z_score_analysis'
            }
            
            # Z-score based outlier detection
            for variable, values in physics_data.items():
                if len(values) > 3:  # Need sufficient data
                    mean_val = np.mean(values)
                    std_val = np.std(values)
                    
                    if std_val > 0:
                        z_scores = np.abs((values - mean_val) / std_val)
                        outlier_indices = np.where(z_scores > 3.0)[0]  # 3-sigma rule
                        
                        if len(outlier_indices) > 0:
                            anomalies['statistical_outliers'].append({
                                'variable': variable,
                                'outlier_indices': outlier_indices.tolist(),
                                'z_scores': z_scores[outlier_indices].tolist(),
                                'severity': 'moderate'
                            })
            
            return anomalies
            
        except Exception as e:
            logging.warning(f"Simple statistical anomaly detection failed: {e}")
            return {'error': str(e)}
    
    def _perform_integrated_risk_assessment(self, integration_results: Dict[str, Any],
                                          displacement_results: Dict[str, Any],
                                          observation_points: np.ndarray) -> Dict[str, Any]:
        """Perform integrated risk assessment based on all anomaly detection results."""
        try:
            risk_assessment = {
                'overall_risk_level': 'low',
                'risk_factors': [],
                'critical_areas': [],
                'risk_score': 0.0,
                'confidence': 0.0
            }
            
            total_risk_score = 0.0
            risk_factors = []
            
            # Assess stress field anomalies
            stress_anomalies = integration_results.get('stress_field_anomalies', {})
            if stress_anomalies.get('has_anomalies', False):
                anomaly_count = len(stress_anomalies.get('anomaly_locations', []))
                stress_risk_score = min(0.4, anomaly_count * 0.1)
                total_risk_score += stress_risk_score
                risk_factors.append(f'Stress field anomalies ({anomaly_count} locations)')
            
            # Assess physics verification anomalies
            physics_anomalies = integration_results.get('physics_anomalies', {})
            if physics_anomalies.get('has_critical_issues', False):
                physics_risk_score = 0.3
                total_risk_score += physics_risk_score
                risk_factors.append('Critical physics verification issues')
            
            # Assess geological anomalies
            geological_anomalies = integration_results.get('geological_anomalies', {})
            if geological_anomalies.get('has_geological_inconsistencies', False):
                geological_risk_score = 0.2
                total_risk_score += geological_risk_score
                risk_factors.append('Geological inconsistencies detected')
            
            # Assess multivariate anomalies
            multivariate_anomalies = integration_results.get('multivariate_anomalies', {})
            if 'statistical_outliers' in multivariate_anomalies:
                outlier_count = len(multivariate_anomalies['statistical_outliers'])
                if outlier_count > 0:
                    multivariate_risk_score = min(0.2, outlier_count * 0.05)
                    total_risk_score += multivariate_risk_score
                    risk_factors.append(f'Statistical outliers detected ({outlier_count} variables)')
            
            # Determine overall risk level
            if total_risk_score >= 0.8:
                risk_level = 'critical'
            elif total_risk_score >= 0.5:
                risk_level = 'high'
            elif total_risk_score >= 0.3:
                risk_level = 'moderate'
            else:
                risk_level = 'low'
            
            risk_assessment.update({
                'overall_risk_level': risk_level,
                'risk_factors': risk_factors,
                'risk_score': min(1.0, total_risk_score),
                'confidence': min(1.0, len(risk_factors) / 5.0)  # Confidence based on number of indicators
            })
            
            return risk_assessment
            
        except Exception as e:
            logging.warning(f"Integrated risk assessment failed: {e}")
            return {'error': str(e), 'overall_risk_level': 'unknown'}
    
    def _generate_integrated_monitoring_recommendations(self, integration_results: Dict[str, Any],
                                                      displacement_results: Dict[str, Any]) -> List[str]:
        """Generate monitoring recommendations based on integrated anomaly analysis."""
        try:
            recommendations = []
            
            # Recommendations based on stress field anomalies
            stress_anomalies = integration_results.get('stress_field_anomalies', {})
            if stress_anomalies.get('has_anomalies', False):
                anomaly_types = stress_anomalies.get('anomaly_types', [])
                if 'high_stress_concentration' in anomaly_types:
                    recommendations.append('Deploy strain monitoring at high stress concentration zones')
                if 'excessive_tensile_stress' in anomaly_types:
                    recommendations.append('Install extensometers to monitor tensile deformation')
                if 'high_differential_stress' in anomaly_types:
                    recommendations.append('Enhance seismic monitoring in high differential stress areas')
            
            # Recommendations based on geological analysis
            geological_anomalies = integration_results.get('geological_anomalies', {})
            hazard_anomalies = geological_anomalies.get('hazard_anomalies', [])
            for hazard in hazard_anomalies:
                if hazard.get('type') == 'high_seismic_hazard':
                    recommendations.append('Implement real-time seismic monitoring network')
                    recommendations.append('Establish earthquake early warning system')
            
            # Recommendations based on model quality
            model_quality_issues = geological_anomalies.get('model_quality_issues', [])
            for issue in model_quality_issues:
                if issue.get('severity') in ['high', 'critical']:
                    recommendations.append('Collect additional field data to improve model accuracy')
                    recommendations.append('Conduct detailed geological survey for model validation')
            
            # General recommendations for high-risk scenarios
            risk_indicators = integration_results.get('risk_indicators', {})
            if risk_indicators.get('overall_risk_level') in ['high', 'critical']:
                recommendations.extend([
                    'Implement continuous GPS monitoring network',
                    'Establish multi-parameter monitoring station',
                    'Conduct regular ground-truth validation surveys',
                    'Develop emergency response protocols'
                ])
            
            # Remove duplicates while preserving order
            unique_recommendations = []
            for rec in recommendations:
                if rec not in unique_recommendations:
                    unique_recommendations.append(rec)
            
            return unique_recommendations
            
        except Exception as e:
            logging.warning(f"Monitoring recommendations generation failed: {e}")
            return ['Conduct comprehensive geological assessment']
    
    def _assess_overall_anomaly_severity(self, integration_results: Dict[str, Any]) -> Dict[str, Any]:
        """Assess overall anomaly severity across all detection methods."""
        try:
            severity_scores = []
            anomaly_counts = []
            
            # Assess stress field anomaly severity
            stress_anomalies = integration_results.get('stress_field_anomalies', {})
            if stress_anomalies.get('has_anomalies', False):
                stress_severity = len(stress_anomalies.get('anomaly_locations', [])) / 10.0  # Normalize
                severity_scores.append(min(1.0, stress_severity))
                anomaly_counts.append(len(stress_anomalies.get('anomaly_locations', [])))
            
            # Assess physics verification severity
            physics_anomalies = integration_results.get('physics_anomalies', {})
            if physics_anomalies.get('has_critical_issues', False):
                severity_scores.append(0.8)  # High severity for physics violations
                anomaly_counts.append(len(physics_anomalies.get('verification_anomalies', [])))
            
            # Assess geological anomaly severity
            geological_anomalies = integration_results.get('geological_anomalies', {})
            if geological_anomalies.get('has_geological_inconsistencies', False):
                tectonic_count = len(geological_anomalies.get('tectonic_anomalies', []))
                hazard_count = len(geological_anomalies.get('hazard_anomalies', []))
                geo_severity = (tectonic_count + hazard_count) / 5.0  # Normalize
                severity_scores.append(min(1.0, geo_severity))
                anomaly_counts.append(tectonic_count + hazard_count)
            
            # Calculate overall severity
            if severity_scores:
                overall_severity = np.mean(severity_scores)
                total_anomalies = sum(anomaly_counts)
            else:
                overall_severity = 0.0
                total_anomalies = 0
            
            # Classify severity level
            if overall_severity >= 0.8:
                severity_level = 'critical'
            elif overall_severity >= 0.6:
                severity_level = 'high'
            elif overall_severity >= 0.3:
                severity_level = 'moderate'
            elif overall_severity > 0.0:
                severity_level = 'low'
            else:
                severity_level = 'minimal'
            
            return {
                'severity_level': severity_level,
                'severity_score': overall_severity,
                'total_anomalies': total_anomalies,
                'detection_methods_triggered': len(severity_scores),
                'requires_immediate_attention': severity_level in ['critical', 'high']
            }
            
        except Exception as e:
            logging.warning(f"Overall anomaly severity assessment failed: {e}")
            return {'severity_level': 'unknown', 'error': str(e)}
    
    def integrate_geological_causal_discovery(self, displacement_results: Dict[str, Any],
                                            observation_points: np.ndarray,
                                            historical_data: Dict[str, Any] = None) -> Dict[str, Any]:
        """Integrate GeologicalCausalDiscovery with elastic inversion results.
        
        This method connects the comprehensive displacement and stress analysis with
        causal discovery algorithms to understand geological process relationships.
        """
        try:
            logging.info("Integrating geological causal discovery with elastic inversion")
            
            # Import the GeologicalCausalDiscovery system
            try:
                from .geological_causal_discovery import GeologicalCausalDiscovery, GeologicalCausalConfig
                
                # Configure causal discovery for geological processes
                causal_config = GeologicalCausalConfig(
                    significance_level=0.05,
                    confidence_threshold=0.7,
                    causal_strength_threshold=0.6,
                    use_domain_knowledge=True,
                    enable_temporal_ordering=True,
                    enable_spatial_constraints=True
                )
                
                causal_discovery = GeologicalCausalDiscovery(causal_config)
                
            except ImportError as e:
                logging.warning(f"Could not import GeologicalCausalDiscovery: {e}")
                return {'error': 'causal_discovery_not_available', 'fallback_analysis': True}
            
            integration_results = {
                'causal_relationships': [],
                'process_networks': {},
                'causal_mechanisms': {},
                'predictive_relationships': {},
                'intervention_recommendations': [],
                'causal_graph_analysis': {}
            }
            
            # 1. Prepare geological data from elastic inversion results
            geological_data = self._prepare_geological_data_for_causal_discovery(
                displacement_results, observation_points, historical_data
            )
            
            # 2. Create time series data if temporal information is available
            time_series_data = self._create_time_series_for_causal_analysis(
                displacement_results, historical_data
            )
            
            # 3. Run causal discovery analysis
            try:
                import asyncio
                
                # Run causal discovery
                if hasattr(asyncio, 'run'):
                    causal_results = asyncio.run(
                        causal_discovery.discover_geological_causality(
                            geological_data, time_series_data
                        )
                    )
                else:
                    # Fallback for older Python versions
                    loop = asyncio.new_event_loop()
                    asyncio.set_event_loop(loop)
                    try:
                        causal_results = loop.run_until_complete(
                            causal_discovery.discover_geological_causality(
                                geological_data, time_series_data
                            )
                        )
                    finally:
                        loop.close()
                
                integration_results['causal_discovery_results'] = causal_results
                
            except Exception as e:
                logging.warning(f"Causal discovery analysis failed: {e}")
                # Fallback to simplified causal analysis
                causal_results = self._fallback_causal_analysis(geological_data)
                integration_results['causal_discovery_results'] = causal_results
            
            # 4. Analyze causal relationships for geological insights
            causal_insights = self._analyze_causal_relationships_for_geology(
                causal_results, displacement_results
            )
            integration_results.update(causal_insights)
            
            # 5. Generate predictive models based on discovered causality
            predictive_models = self._generate_causal_predictive_models(
                causal_results, displacement_results, observation_points
            )
            integration_results['predictive_relationships'] = predictive_models
            
            # 6. Intervention and monitoring recommendations
            intervention_recommendations = self._generate_causal_intervention_recommendations(
                causal_results, integration_results
            )
            integration_results['intervention_recommendations'] = intervention_recommendations
            
            logging.info(f"Geological causal discovery integration completed. Found {len(integration_results.get('causal_relationships', []))} causal relationships")
            return integration_results
            
        except Exception as e:
            logging.error(f"Geological causal discovery integration failed: {e}")
            return {
                'error': str(e),
                'integration_method': 'geological_causal_discovery',
                'fallback_analysis': True
            }
    
    def _prepare_geological_data_for_causal_discovery(self, displacement_results: Dict[str, Any],
                                                    observation_points: np.ndarray,
                                                    historical_data: Dict[str, Any] = None) -> Dict[str, Any]:
        """Prepare geological data for causal discovery analysis."""
        try:
            geological_data = {
                'measurements': {},
                'processes': []
            }
            
            # Extract measurements from elastic inversion results
            displacements = displacement_results.get('displacements', np.zeros((len(observation_points), 3)))
            
            for i, point in enumerate(observation_points):
                location_id = f'location_{i}'
                measurements = {
                    'coordinates': point.tolist(),
                    'displacement_x': float(displacements[i, 0]),
                    'displacement_y': float(displacements[i, 1]),
                    'displacement_z': float(displacements[i, 2]),
                    'displacement_magnitude': float(np.linalg.norm(displacements[i]))
                }
                
                # Add stress analysis data if available
                if 'stress_analysis' in displacement_results:
                    stress_analysis = displacement_results['stress_analysis']
                    
                    if 'principal_stresses' in stress_analysis and len(stress_analysis['principal_stresses']) > i:
                        principal_stresses = stress_analysis['principal_stresses'][i]
                        measurements.update({
                            'max_principal_stress': float(principal_stresses[0]),
                            'intermediate_principal_stress': float(principal_stresses[1]),
                            'min_principal_stress': float(principal_stresses[2])
                        })
                    
                    if 'von_mises_stress' in stress_analysis and len(stress_analysis['von_mises_stress']) > i:
                        measurements['von_mises_stress'] = float(stress_analysis['von_mises_stress'][i])
                    
                    if 'max_shear_stress' in stress_analysis and len(stress_analysis['max_shear_stress']) > i:
                        measurements['max_shear_stress'] = float(stress_analysis['max_shear_stress'][i])
                
                # Add geological analysis data if available
                if 'geological_analysis' in displacement_results:
                    geo_analysis = displacement_results['geological_analysis']
                    
                    # Add hazard indicators
                    hazard_assessment = geo_analysis.get('hazard_assessment', {})
                    seismic_indicators = hazard_assessment.get('seismic_hazard_indicators', {})
                    measurements['seismic_hazard_level'] = self._encode_hazard_level(
                        seismic_indicators.get('hazard_level', 'minimal')
                    )
                    
                    # Add model quality indicators
                    quality_indicators = geo_analysis.get('model_quality_indicators', {})
                    measurements['model_quality_score'] = float(quality_indicators.get('overall_quality_score', 0.5))
                
                # Add confidence and uncertainty if available
                if 'confidence' in displacement_results and len(displacement_results['confidence']) > i:
                    measurements['model_confidence'] = float(displacement_results['confidence'][i])
                
                if 'uncertainty' in displacement_results:
                    uncertainty = displacement_results['uncertainty']
                    if len(uncertainty.shape) > 1 and len(uncertainty) > i:
                        measurements['uncertainty_magnitude'] = float(np.linalg.norm(uncertainty[i]))
                    elif len(uncertainty) > i:
                        measurements['uncertainty_magnitude'] = float(uncertainty[i])
                
                geological_data['measurements'][location_id] = measurements
            
            # Infer geological processes from the data
            processes = self._infer_geological_processes_from_inversion(
                displacement_results, observation_points
            )
            geological_data['processes'] = processes
            
            return geological_data
            
        except Exception as e:
            logging.warning(f"Geological data preparation for causal discovery failed: {e}")
            return {'measurements': {}, 'processes': []}
    
    def _encode_hazard_level(self, hazard_level: str) -> float:
        """Encode hazard level as numerical value for causal analysis."""
        hazard_mapping = {
            'minimal': 0.1,
            'low': 0.3,
            'moderate': 0.5,
            'high': 0.8,
            'extreme': 1.0
        }
        return hazard_mapping.get(hazard_level.lower(), 0.5)
    
    def _infer_geological_processes_from_inversion(self, displacement_results: Dict[str, Any],
                                                 observation_points: np.ndarray) -> List[Dict[str, float]]:
        """Infer geological processes from elastic inversion results."""
        try:
            processes = []
            
            displacements = displacement_results.get('displacements', np.zeros((len(observation_points), 3)))
            
            for i, point in enumerate(observation_points):
                process_indicators = {}
                
                # Fault activity from displacement magnitude
                displacement_magnitude = np.linalg.norm(displacements[i])
                process_indicators['fault_activity'] = min(1.0, displacement_magnitude / 0.1)  # Normalize by 10 cm
                
                # Tectonic deformation from stress analysis
                if 'stress_analysis' in displacement_results:
                    stress_analysis = displacement_results['stress_analysis']
                    
                    if 'von_mises_stress' in stress_analysis and len(stress_analysis['von_mises_stress']) > i:
                        von_mises = stress_analysis['von_mises_stress'][i]
                        process_indicators['tectonic_deformation'] = min(1.0, von_mises / 50e6)  # Normalize by 50 MPa
                    
                    # Infer process type from geological interpretation
                    geological_interp = stress_analysis.get('geological_interpretation', {})
                    dominant_regime = geological_interp.get('dominant_regime', 'unknown')
                    
                    if dominant_regime == 'normal_faulting':
                        process_indicators['extensional_tectonics'] = 0.8
                        process_indicators['crustal_extension'] = 0.7
                    elif dominant_regime == 'reverse_faulting':
                        process_indicators['compressional_tectonics'] = 0.8
                        process_indicators['crustal_compression'] = 0.7
                    elif dominant_regime == 'strike_slip':
                        process_indicators['strike_slip_tectonics'] = 0.8
                        process_indicators['lateral_motion'] = 0.7
                
                # Seismic activity from geological analysis
                if 'geological_analysis' in displacement_results:
                    geo_analysis = displacement_results['geological_analysis']
                    hazard_assessment = geo_analysis.get('hazard_assessment', {})
                    seismic_indicators = hazard_assessment.get('seismic_hazard_indicators', {})
                    
                    hazard_level = seismic_indicators.get('hazard_level', 'minimal')
                    process_indicators['seismic_activity'] = self._encode_hazard_level(hazard_level)
                
                # Rock deformation processes
                if displacement_magnitude > 0.01:  # > 1 cm
                    process_indicators['rock_deformation'] = min(1.0, displacement_magnitude / 0.05)
                    process_indicators['strain_accumulation'] = min(1.0, displacement_magnitude / 0.02)
                
                # Ensure all values are between 0 and 1
                for key, value in process_indicators.items():
                    process_indicators[key] = max(0.0, min(1.0, float(value)))
                
                processes.append(process_indicators)
            
            return processes
            
        except Exception as e:
            logging.warning(f"Geological process inference failed: {e}")
            return [{'unknown_process': 0.5} for _ in observation_points]
    
    def _create_time_series_for_causal_analysis(self, displacement_results: Dict[str, Any],
                                              historical_data: Dict[str, Any] = None) -> Optional[Any]:
        """Create time series data for temporal causal analysis."""
        try:
            import pandas as pd
            
            # If historical data is provided, use it
            if historical_data and 'time_series' in historical_data:
                return historical_data['time_series']
            
            # Otherwise, create synthetic time series based on current results
            # This is a simplified approach - in practice, you'd want real temporal data
            dates = pd.date_range(start='2020-01-01', end='2024-01-01', freq='D')
            n_dates = len(dates)
            
            # Create time series from displacement results
            displacements = displacement_results.get('displacements')
            if displacements is not None:
                # Create synthetic temporal evolution
                displacement_magnitudes = np.linalg.norm(displacements, axis=1)
                mean_displacement = np.mean(displacement_magnitudes)
                
                time_series_data = pd.DataFrame({
                    'timestamp': dates,
                    'displacement_magnitude': np.random.normal(mean_displacement, mean_displacement * 0.1, n_dates),
                    'fault_activity': np.random.beta(2, 5, n_dates),
                    'tectonic_stress': np.random.gamma(2, 10e6, n_dates),
                    'seismic_activity': np.random.exponential(0.1, n_dates)
                })
                
                # Ensure non-negative values where appropriate
                time_series_data['displacement_magnitude'] = np.abs(time_series_data['displacement_magnitude'])
                time_series_data['tectonic_stress'] = np.abs(time_series_data['tectonic_stress'])
                
                return time_series_data
            
            return None
            
        except Exception as e:
            logging.warning(f"Time series creation for causal analysis failed: {e}")
            return None
    
    def _fallback_causal_analysis(self, geological_data: Dict[str, Any]) -> Dict[str, Any]:
        """Fallback causal analysis when advanced methods are not available."""
        try:
            logging.info("Using fallback causal analysis")
            
            fallback_results = {
                'discovered_relationships': [],
                'causal_graph': None,
                'confidence_scores': {},
                'method': 'correlation_based_fallback'
            }
            
            # Simple correlation-based causal inference
            measurements = geological_data.get('measurements', {})
            if len(measurements) < 3:
                return fallback_results
            
            # Extract numerical variables
            variables = {}
            for location, data in measurements.items():
                for var_name, value in data.items():
                    if isinstance(value, (int, float)) and var_name != 'coordinates':
                        if var_name not in variables:
                            variables[var_name] = []
                        variables[var_name].append(value)
            
            # Calculate correlations and infer causal relationships
            import numpy as np
            
            var_names = list(variables.keys())
            relationships = []
            
            for i, var1 in enumerate(var_names):
                for j, var2 in enumerate(var_names[i+1:], i+1):
                    values1 = np.array(variables[var1])
                    values2 = np.array(variables[var2])
                    
                    if len(values1) == len(values2) and len(values1) > 1:
                        correlation = np.corrcoef(values1, values2)[0, 1]
                        
                        if not np.isnan(correlation) and abs(correlation) > 0.5:
                            # Simple heuristic for causal direction based on variable types
                            if self._is_likely_cause(var1, var2):
                                cause, effect = var1, var2
                            else:
                                cause, effect = var2, var1
                            
                            relationships.append({
                                'cause': cause,
                                'effect': effect,
                                'strength': abs(correlation),
                                'confidence': min(0.8, abs(correlation)),
                                'method': 'correlation_heuristic'
                            })
            
            fallback_results['discovered_relationships'] = relationships
            fallback_results['confidence_scores'] = {
                f"{rel['cause']}->{rel['effect']}": rel['confidence']
                for rel in relationships
            }
            
            return fallback_results
            
        except Exception as e:
            logging.warning(f"Fallback causal analysis failed: {e}")
            return {'discovered_relationships': [], 'method': 'failed_fallback', 'error': str(e)}
    
    def _is_likely_cause(self, var1: str, var2: str) -> bool:
        """Heuristic to determine likely causal direction between variables."""
        # Stress variables are often causes of displacement
        if 'stress' in var1.lower() and 'displacement' in var2.lower():
            return True
        if 'displacement' in var1.lower() and 'stress' in var2.lower():
            return False
        
        # Tectonic processes cause deformation
        if 'tectonic' in var1.lower() and 'deformation' in var2.lower():
            return True
        
        # Fault activity causes seismic activity
        if 'fault' in var1.lower() and 'seismic' in var2.lower():
            return True
        
        # Default: alphabetical order
        return var1 < var2
    
